"""Verifier for 8764bfdd-69b5-57a0-bc6a-db095fe071db.

Two tiers are graded. The visible tier compares the delivered outputs (produced from
/app/data, which the verifier never sees) with expectations computed at build time from the
same seeded generator. The eval tier regenerates a fresh export set from EVAL_SEED with the
generator inlined below, runs the delivered tool on it as an unprivileged user, and compares
with the generator's own truth. Every HARD check needs both tiers and judges only its own
record population or its own concept, so one wrong fact costs the checks that own it:
  * record lines carry the outcome plus the fields governed by the record's traps (_RULE_FIELDS), never
    entry_id, which concept_c10_catalog owns;
  * a concept compares its own fields per record over the entries both sides keep (the
    agent must keep at least 99% of the expected entries) plus its own exception reasons,
    so which records become entries is graded once per owning reason and by C10;
  * concept_c5_journals owns which journal events become entries, concept_c6_content owns
    store_bytes, and concept_c10_catalog owns ids, the rest of the ledger and the chain.
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
import pwd
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import zipfile
import zlib
from pathlib import Path

from rewardkit import criteria, criterion

OUT = Path("/app/out")
ARTIFACTS = ["config.json", "report.json", "tool.zip", "profile_dev.json", "profile_prod.json",
             "validation_report.json", "summary.json"]
EVAL_SEED = 1972138169496734964
EVAL_SCALE = 200
TOOL_TIMEOUT = 1500
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
# Agent code never inherits the verifier environment, which carries the judge API key.
_TOOL_ENV = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": "/tmp",
             "PYTHONHASHSEED": "random"}
_EXPECT_B64 = ""
_CACHE: dict = {}
# rewardkit runs checks in worker threads: one re-entrant lock builds every shared cache once and
# serialises the extra tool runs, so the /app/data bait never overlaps another run.
_LOCK = threading.RLock()
ECS_REASONS = {"OUT_OF_AUTHORITY", "SUPERSEDED_SCOPE", "VOIDED", "NOT_A_FILE", "STALE_EVENT", "DEFERRED_EVENT",
               "PATH_UNRESOLVED", "SIZE_UNKNOWN", "HASH_UNRESOLVED", "OWNER_UNRESOLVED", "DUPLICATE_PATH",
               "ORPHAN_EVENT", "DELETED", "REPLACED", "HARDLINK_ALIAS", "PURGED"}
CONCEPT_REASONS = {
    "C1": {"OUT_OF_AUTHORITY", "SUPERSEDED_SCOPE", "VOIDED"},
    "C2": {"PATH_UNRESOLVED", "NOT_A_FILE"},
    "C3": {"SIZE_UNKNOWN", "HARDLINK_ALIAS", "DUPLICATE_PATH"},
    "C4": {"STALE_EVENT", "DEFERRED_EVENT"},
    "C5": {"ORPHAN_EVENT", "DELETED", "REPLACED"},
    "C6": {"HASH_UNRESOLVED"},
    "C7": {"OWNER_UNRESOLVED"},
    "C8": {"PURGED"},
}
CONCEPTS = ("C1", "C2", "C3", "C4", "C5", "C6", "C7", "C8", "C9", "C10")
# Entry fields each concept owns, compared record by record over the entries both sides keep.
ROW_FIELDS = {"C2": ("volume", "path"), "C3": ("bytes",), "C4": ("mtime",), "C6": ("sha256",), "C7": ("owner",),
              "C8": ("class", "action")}
# Share (per mille) of the expected entries the agent must keep before per-record fields count.
KEEP_PERMILLE = 990
# Record lines of the family and decoy checks; entry_id belongs to concept_c10_catalog alone.
LINE_FIELDS = ("volume", "path", "sha256", "bytes", "mtime", "owner", "class", "action")


def _expect() -> dict:
    if "expect" not in _CACHE:
        _CACHE["expect"] = json.loads(zlib.decompress(base64.b64decode(_EXPECT_B64)))
    return _CACHE["expect"]


def _sha(obj) -> str:
    return hashlib.sha256(json.dumps(obj, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()


def _read_json(path: Path):
    # Any failure (including RecursionError from hostile nesting) means unusable output.
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _outputs(root: Path) -> dict | None:
    docs = {}
    for name in ("config.json", "profile_prod.json", "profile_dev.json", "validation_report.json", "summary.json"):
        doc = _read_json(root / name)
        if doc is None:
            return None
        docs[name] = doc
    try:
        for prof in ("prod", "dev"):
            pdoc = docs[f"profile_{prof}.json"]
            by_origin = {}
            for e in pdoc["entries"]:
                by_origin[str(e["origin"])] = e
            docs[f"entries_{prof}"] = by_origin
            docs[f"reasons_{prof}"] = {str(x["rec_id"]): str(x["reason"]) for x in docs["validation_report.json"][prof]}
    except (KeyError, TypeError, AttributeError):
        return None
    return docs


def _line(docs: dict, prof: str, rid: str, mask: int = 0xFF) -> str:
    e = docs[f"entries_{prof}"].get(rid)
    if e is not None:
        try:
            return "E|" + json.dumps([e.get(k) for i, k in enumerate(LINE_FIELDS) if mask >> i & 1], ensure_ascii=False)
        except (TypeError, ValueError, AttributeError, RecursionError):
            return "E|?"
    r = docs[f"reasons_{prof}"].get(rid)
    return f"X|{r}" if r is not None else "A"


def _recset_digest(docs: dict, prof: str, recs, masks: dict) -> str:
    return hashlib.sha256("\n".join(f"{rid}={_line(docs, prof, rid, masks.get(rid, 0))}"
                                    for rid in sorted(recs)).encode()).hexdigest()


# Entry fields a trap's rule governs (first match wins). A family or decoy line compares the record's outcome
# plus only these fields, so a mistake in an unrelated rule is charged to the checks that own that rule; every
# field of every entry is still compared population-wide by the concept checks.
_F = {k: 1 << i for i, k in enumerate(LINE_FIELDS)}
_ALL_FIELDS = 0xFF
_RULE_FIELDS = [
    (r"^ECS 3\.5|errata", _F["sha256"] | _F["bytes"] | _F["mtime"] | _F["owner"]),
    (r"^ECS 4\.|clock incident|host zones|tz tables", _F["mtime"]),
    (r"^ECS 5\.[23]|serials|file-system types", _F["volume"] | _F["path"]),
    (r"^ECS 5\.[45]|account names|principal_|sid_history|OLDCORP", _F["owner"]),
    (r"^ECS 6\.1|units-bulletin|unknown size", _F["bytes"]),
    (r"^ECS 6\.[25]|hash_index", _F["sha256"]),
    (r"^ECS 7\.|v3 rule|retention|class ages|footnote|Annex F|holds?\b|legal-hold", _F["class"] | _F["action"]),
    (r"^ECS 3\.|^ECS 6\.[46]|authority_matrix|void|exclusion|audit|estate_manifest_q2|newer capture|decoy format damage", 0),
]


def _rule_fields(rule: str) -> int:
    for pat, bits in _RULE_FIELDS:
        if re.search(pat, rule):
            return bits
    return _ALL_FIELDS


def _set_masks(traps) -> dict:
    """Per graded set, the union of field masks of the traps touching each record (absent = outcome only)."""
    masks: dict = {}
    for t in traps:
        bits = _rule_fields(t["rule"])
        for key in {f"family:{t['family']}", t["test"]}:
            per = masks.setdefault(key, {})
            for rid in t["recs"]:
                per[rid] = per.get(rid, 0) | bits
    return masks


def _row_hash(rid: str, e, fields) -> bytes | None:
    try:
        return hashlib.sha256(json.dumps([rid, *[e.get(k) for k in fields]], ensure_ascii=False).encode()).digest()[:4]
    except (TypeError, ValueError, AttributeError, RecursionError):
        return None


def _journal_codes() -> set:
    return {FILE_CODE[f] for f in JOURNAL_FILES}


def _concept_parts(docs: dict, prof: str, concept: str) -> tuple | None:
    """Digests of what a concept owns besides its per-record entry fields."""
    try:
        reasons = CONCEPT_REASONS.get(concept, set())
        exc = sorted([rid, r] for rid, r in docs[f"reasons_{prof}"].items() if r in reasons)
        s = docs["summary.json"]
        extra = None
        if concept == "C9":
            extra = [docs["config.json"], docs["profile_prod.json"]["config"], docs["profile_dev.json"]["config"]]
        elif concept == "C5":
            codes = _journal_codes()
            extra = sorted(rid for rid in docs[f"entries_{prof}"] if rid.split("-", 1)[0] in codes)
        elif concept == "C6":
            extra = [s["profiles"][prof]["closing"]["store_bytes"], docs[f"profile_{prof}.json"]["control"]["store_bytes"]]
        elif concept == "C10":
            ledger = json.loads(json.dumps(s["profiles"][prof]))
            ledger["exceptions"] = {k: v for k, v in ledger["exceptions"].items() if v != 0}
            ledger["closing"].pop("store_bytes", None)
            control = dict(docs[f"profile_{prof}.json"]["control"])
            control.pop("store_bytes", None)
            ids = sorted([rid, e.get("entry_id")] for rid, e in docs[f"entries_{prof}"].items())
            extra = [s["opening_ctl_id"], s["chain"], ledger, control, ids]
        return _sha(exc), _sha(extra)
    except (KeyError, TypeError, AttributeError, IndexError, ValueError, RecursionError):
        return None


def _concept_spec(docs: dict) -> dict:
    spec = {}
    for prof in ("prod", "dev"):
        ents = docs[f"entries_{prof}"]
        for c in CONCEPTS:
            exc, extra = _concept_parts(docs, prof, c)
            rows = {rid: _row_hash(rid, e, ROW_FIELDS[c]) for rid, e in ents.items()} if c in ROW_FIELDS else None
            spec[(c, prof)] = (exc, extra, rows)
    return spec


def _concept_ok(got: dict, spec: dict, prof: str, concept: str) -> bool:
    exc, extra, rows = spec[(concept, prof)]
    if _concept_parts(got, prof, concept) != (exc, extra):
        return False
    if rows is None:
        return True
    ents = got[f"entries_{prof}"]
    fields = ROW_FIELDS[concept]
    kept = 0
    for rid, want in rows.items():
        e = ents.get(rid)
        if e is None:
            continue
        kept += 1
        if not isinstance(e, dict) or _row_hash(rid, e, fields) != want:
            return False
    return kept * 1000 >= len(rows) * KEEP_PERMILLE


def _gate_digest(docs: dict) -> str:
    try:
        s = docs["summary.json"]
        return _sha([s["opening_ctl_id"], s["chain"], [s["profiles"][p]["closing"] for p in ("prod", "dev")]])
    except (KeyError, TypeError):
        return "invalid"


def _visible() -> dict | None:
    with _LOCK:
        if "visible" not in _CACHE:
            _CACHE["visible"] = _outputs(OUT)
        return _CACHE["visible"]


def _visible_spec() -> dict:
    with _LOCK:
        if "visible_spec" not in _CACHE:
            exp = _expect()
            rows = exp["rows"]
            rids = rows["rids"]
            spec = {}
            for prof in ("prod", "dev"):
                mask = base64.b64decode(rows["member"][prof])
                mine = [i for i in range(len(rids)) if mask[i >> 3] >> (i & 7) & 1]
                for c in CONCEPTS:
                    exc, extra = exp["concepts"][c][prof]
                    per_rec = None
                    if c in ROW_FIELDS:
                        base = base64.b64decode(rows[c]["base"])
                        per_rec = {rids[i]: base[4 * i:4 * i + 4] for i in mine}
                        per_rec.update({rid: bytes.fromhex(h) for rid, h in rows[c]["over"][prof].items()})
                    spec[(c, prof)] = (exc, extra, per_rec)
            _CACHE["visible_spec"] = spec
        return _CACHE["visible_spec"]


def _visible_ok(test: str) -> bool:
    docs = _visible()
    if docs is None:
        return False
    exp = _expect()
    for prof in ("prod", "dev"):
        if test.startswith("C"):
            if not _concept_ok(docs, _visible_spec(), prof, test):
                return False
        else:
            spec = exp["sets"][test]
            masks = {rid: int(spec["mask"][2 * i:2 * i + 2], 16) for i, rid in enumerate(spec["recs"])}
            if _recset_digest(docs, prof, spec["recs"], masks) != spec[prof]:
                return False
    return True


# ---------------------------------------------------------------- delivered tool on the eval tier
def _untrusted(cmd: list[str]) -> list[str]:
    if os.name == "posix" and os.geteuid() == 0 and shutil.which("setpriv"):
        return [*_SETPRIV, *cmd]
    return cmd


def _sweep_uid(uid: int) -> None:
    """SIGKILL every process owned by uid, including children that left the process group with setsid."""
    proc_root = Path("/proc")
    for _ in range(50):
        found = False
        try:
            entries = [p for p in proc_root.iterdir() if p.name.isdigit()]
        except OSError:
            return
        for p in entries:
            try:
                status = (p / "status").read_text()
            except OSError:
                continue
            uids = next((line.split()[1:] for line in status.splitlines() if line.startswith("Uid:")), [])
            if str(uid) in uids:
                found = True
                try:
                    os.kill(int(p.name), signal.SIGKILL)
                except OSError:
                    pass
        if not found:
            return


def _grant_read(root: Path) -> None:
    """Make the program tree readable by the dropped uid, whatever modes it was staged with."""
    try:
        paths = [root, *root.rglob("*")]
    except OSError:
        return
    for p in paths:
        try:
            p.chmod(p.stat().st_mode | (0o555 if p.is_dir() else 0o444))
        except OSError:
            continue


def _run_untrusted(args: list[str], cwd: Path, env: dict, timeout: int) -> int | None:
    """Run agent code with a bounded wait; nothing it starts outlives the call.

    Output goes to temporary files rather than pipes, so a detached child holding the descriptors cannot
    block the wait. Afterwards the process group is killed and, when privileges were dropped, every process
    of the unprivileged uid is swept, which also catches children that escaped the group with setsid.
    Runs hold _LOCK so a sweep never kills another check's run.
    """
    with _LOCK:
        return _run_untrusted_locked(args, cwd, env, timeout)


def _run_untrusted_locked(args: list[str], cwd: Path, env: dict, timeout: int) -> int | None:
    cmd = _untrusted([sys.executable, "-E", "-s", *args])
    dropped = cmd[:1] == _SETPRIV[:1]
    if dropped:
        _grant_read(cwd)
    rc = None
    try:
        with tempfile.TemporaryFile() as out, tempfile.TemporaryFile() as err:
            try:
                proc = subprocess.Popen(cmd, cwd=str(cwd), env=env, stdin=subprocess.DEVNULL, stdout=out,
                                        stderr=err, start_new_session=True)
            except OSError:
                return None
            try:
                rc = proc.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                rc = None
            finally:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except OSError:
                    pass
                if dropped:
                    try:
                        _sweep_uid(pwd.getpwnam("nobody").pw_uid)
                    except KeyError:
                        pass
                if proc.poll() is None:
                    proc.kill()
                try:
                    proc.wait(timeout=10)
                except subprocess.TimeoutExpired:
                    rc = None
    except OSError:
        return None
    return rc


def _tool_dir() -> Path | None:
    with _LOCK:
        if "tool" in _CACHE:
            return _CACHE["tool"]
        root = None
        try:
            with zipfile.ZipFile(OUT / "tool.zip") as zf:
                root = Path(tempfile.mkdtemp(prefix="estate-tool-"))
                for info in zf.infolist():
                    name = info.filename
                    if name.startswith("/") or ".." in Path(name).parts or "\\" in name:
                        raise ValueError("unsafe member")
                    dest = root / name
                    if info.is_dir():
                        dest.mkdir(parents=True, exist_ok=True)
                        continue
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    dest.write_bytes(zf.read(info))
            for p in [root, *root.rglob("*")]:
                p.chmod(0o755 if p.is_dir() else 0o644)
            if not (root / "estatectl" / "estatectl.py").is_file():
                root = None
        except Exception as exc:  # any unreadable or hostile archive means no usable tool
            print(f"tool.zip unusable: {exc!r}", file=sys.stderr)
            root = None
        _CACHE["tool"] = root
        return root


def _run_tool(data: Path, label: str) -> Path | None:
    tool = _tool_dir()
    if tool is None:
        return None
    out = Path(tempfile.mkdtemp(prefix=f"estate-out-{label}-"))
    out.chmod(0o777)
    rc = _run_untrusted(["estatectl/estatectl.py", "run", "--data", str(data), "--out", str(out)], tool, dict(_TOOL_ENV),
                        TOOL_TIMEOUT)
    return out if rc == 0 else None


def _eval_world():
    with _LOCK:
        if "eval" in _CACHE:
            return _CACHE["eval"]
        result = None
        try:
            world = EstateSet(EVAL_SEED, EVAL_SCALE).build()
            base = Path(tempfile.mkdtemp(prefix="estate-eval-"))
            base.chmod(0o755)
            data = base / "data"
            world.render(data)
            for p in [data, *data.iterdir()]:
                p.chmod(0o755 if p.is_dir() else 0o644)
            exp = world.expected_outputs()
            result = {"world": world, "data": data, "base": base, "exp": exp}
        except Exception as exc:
            print(f"eval generation failed: {exc!r}", file=sys.stderr)
        _CACHE["eval"] = result
        return result


def _eval_spec(want: dict) -> dict:
    with _LOCK:
        if "eval_spec" not in _CACHE:
            _CACHE["eval_spec"] = _concept_spec(want)
        return _CACHE["eval_spec"]


def _expected_docs(exp: dict) -> dict:
    docs = dict(exp)
    for prof in ("prod", "dev"):
        docs[f"entries_{prof}"] = {e["origin"]: e for e in exp[f"profile_{prof}.json"]["entries"]}
        docs[f"reasons_{prof}"] = {x["rec_id"]: x["reason"] for x in exp["validation_report.json"][prof]}
    return docs


def _eval_run():
    with _LOCK:
        if "eval_run" in _CACHE:
            return _CACHE["eval_run"]
        ev = _eval_world()
        got = None
        if ev is not None:
            out = _run_tool(ev["data"], "a")
            if out is not None:
                got = _outputs(out)
                _CACHE["eval_out"] = out
        _CACHE["eval_run"] = got
        return got


def _eval_rerun() -> Path | None:
    """Second plain run on the same eval set; the reference every negative compares against."""
    with _LOCK:
        if "eval_rerun" not in _CACHE:
            ev = _eval_world()
            again = None
            if ev is not None and _eval_run() is not None:
                again = _run_tool(ev["data"], "d")
            _CACHE["eval_rerun"] = again
        return _CACHE["eval_rerun"]


def _deterministic() -> bool:
    return _same_tree(_CACHE.get("eval_out"), _eval_rerun())


def _eval_sets(world) -> dict:
    with _LOCK:
        if "eval_sets" in _CACHE:
            return _CACHE["eval_sets"]
        sets = {}
        for rec in world.recs:
            for tag in rec["tags"]:
                if tag.startswith("T") and tag[1:].isdigit():
                    sets.setdefault(f"family:{tag}", set()).add(rec["rec_id"])
                elif tag.startswith("D:"):
                    sets.setdefault(f"decoy:{tag[2:]}", set()).add(rec["rec_id"])
            if rec["file"] in DECOYS:
                sets.setdefault(f"decoy:{rec['file']}", set()).add(rec["rec_id"])
        _CACHE["eval_sets"] = sets
        return sets


def _eval_ok(test: str) -> bool:
    ev = _eval_world()
    got = _eval_run()
    if ev is None or got is None:
        return False
    want = _expected_docs(ev["exp"])
    for prof in ("prod", "dev"):
        if test.startswith("C"):
            if not _concept_ok(got, _eval_spec(want), prof, test):
                return False
        else:
            recs = _eval_sets(ev["world"]).get(test)
            if not recs:
                return False
            masks = _eval_masks(ev["world"]).get(test, {})
            if _recset_digest(got, prof, recs, masks) != _recset_digest(want, prof, recs, masks):
                return False
    return True


def _eval_masks(world) -> dict:
    with _LOCK:
        if "eval_masks" not in _CACHE:
            _CACHE["eval_masks"] = _set_masks(world.traps)
        return _CACHE["eval_masks"]


def _hard(test: str) -> bool:
    try:
        return _visible_ok(test) and _eval_ok(test)
    except Exception as exc:
        print(f"check {test} errored: {exc!r}", file=sys.stderr)
        return False


def _same_tree(a: Path | None, b: Path | None) -> bool:
    if a is None or b is None:
        return False
    names = ["config.json", "profile_prod.json", "profile_dev.json", "validation_report.json", "summary.json"]
    try:
        return all((a / n).read_bytes() == (b / n).read_bytes() for n in names)
    except OSError:
        return False


# ---------------------------------------------------------------- inlined generator
# ---- estate_gen.py
"""Inlined seeded generator.

One deterministic pipeline, two consumers:
  * environment/data of this bundle is rendered from it (visible tier, SCALE=5100 rows/file);
  * tests/test_output.py inlines this module and regenerates a fresh export set from
    EVAL_SEED at grade time (eval tier, small scale), then grades the delivered tool.

Design: the generator first builds a clean "world" (volumes, principals, contents,
entries, journal histories, reference tables) and the *intended outcome* of every
source record.  Renderers then write each logical row in its file's dialect, with
traps planted in the representation (the documented rules undo every trap).  The
truth evaluator works on clean logical values only, so it never parses a file.
"""


import base64
import hashlib
import io
import json
import random
import sqlite3
import struct
import unicodedata
import zipfile
import zlib
from pathlib import Path
from xml.sax.saxutils import escape as _xesc

DAY = 86400
GEN_VERSION = "ecs-gen-3"

# --------------------------------------------------------------------------------------
# calendar helpers (no tz libraries: every offset comes from the shipped tables)
# --------------------------------------------------------------------------------------


def g_days_from_civil(y: int, m: int, d: int) -> int:
    y -= m <= 2
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def g_civil_from_days(z: int) -> tuple[int, int, int]:
    z += 719468
    era = (z if z >= 0 else z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + (3 if mp < 10 else -9)
    return y + (m <= 2), m, d


def g_epoch(y, m, d, hh=0, mi=0, ss=0) -> int:
    return g_days_from_civil(y, m, d) * DAY + hh * 3600 + mi * 60 + ss


def g_parts(t: int) -> tuple[int, int, int, int, int, int]:
    days, rem = divmod(t, DAY)
    y, m, d = g_civil_from_days(days)
    return y, m, d, rem // 3600, rem % 3600 // 60, rem % 60


def g_iso(t: int) -> str:
    y, m, d, hh, mi, ss = g_parts(t)
    return f"{y:04d}-{m:02d}-{d:02d}T{hh:02d}:{mi:02d}:{ss:02d}Z"


def g_local_str(t: int, sep: str = " ") -> str:
    y, m, d, hh, mi, ss = g_parts(t)
    return f"{y:04d}-{m:02d}-{d:02d}{sep}{hh:02d}:{mi:02d}:{ss:02d}"


def g_weekday(days: int) -> int:  # 0=Monday
    return (days + 3) % 7


def g_nth_sunday(y: int, m: int, n: int) -> int:
    first = g_days_from_civil(y, m, 1)
    off = (6 - g_weekday(first)) % 7
    return first + off + 7 * (n - 1)


