# --------------------------------------------------------------------------------------
# small utilities
# --------------------------------------------------------------------------------------


def g_hex(rng: random.Random, nbits: int) -> str:
    return f"{rng.getrandbits(nbits):0{nbits // 4}x}"


def g_lower(s: str) -> str:
    """ECS case folding: Unicode simple lowercase (str.lower), never casefold."""
    return s.lower()


def g_half_even(num: int, den: int) -> int:
    q, r = divmod(num, den)
    if 2 * r > den or (2 * r == den and q % 2 == 1):
        q += 1
    return q


class Gen:
    """One seeded export set plus its truth."""

    def __init__(self, seed: int, scale: int = 5100):
        self.seed = seed
        self.N = scale
        self.small = scale < 1000
        self.rng = random.Random(seed)
        self.traps: list[dict] = []
        self.trap_seq = 0
        self.rows: dict[str, list] = {f: [] for f in FILE_NAMES}
        self.meta: dict[str, dict] = {f: {} for f in FILE_NAMES}
        self.notes: dict[str, list] = {f: [] for f in FILE_NAMES}
        self.recs: list[dict] = []          # inventory + journal records (logical)
        self.rec_by_id: dict[str, dict] = {}
        self.rec_counter = {f: 0 for f in FILE_NAMES}
        self.used_paths: dict[str, set] = {}

    # ---------------------------------------------------------------- trap bookkeeping
    def trap(self, file: str, locator: str, family: str, rule: str, test: str,
             recs: list[str] | None = None, direction: str | None = None) -> str:
        self.trap_seq += 1
        tid = f"TR{self.trap_seq:05d}"
        if direction is None and file in DECOYS:
            direction = "push" if family in ("T5", "T8", "T10") else "pull"
        self.traps.append({"id": tid, "file": file, "locator": locator, "family": family,
                           "decoy": file in DECOYS, "direction": direction, "rule": rule,
                           "test": test, "recs": list(recs or [])})
        return tid

    def new_rec_id(self, file: str) -> str:
        self.rec_counter[file] += 1
        return f"{FILE_CODE[file]}-{self.rec_counter[file]:06d}"

    # ---------------------------------------------------------------- build

    # ---------------------------------------------------------------- period
    def _period(self):
        r = self.rng
        choices = [(2026, 7), (2027, 1), (2026, 10), (2027, 4), (2025, 10), (2028, 1)]
        y, m = choices[self.seed % len(choices)] if self.seed != 20261019 else (2026, 7)
        self.win_start = g_epoch(y, m, 1)
        y2, m2 = (y + 1, 1) if m == 10 else (y, m + 3)
        self.win_end = g_epoch(y2, m2, 1)
        self.quarter = f"{y}Q{(m - 1) // 3 + 1}"
        py, pm = (y - 1, 10) if m == 1 else (y, m - 3)
        self.prev_quarter = f"{py}Q{(pm - 1) // 3 + 1}"
        self.prev_start = g_epoch(py, pm, 1)
        # Q2-style defaults window is the previous quarter (layer 10), overridden by layer 20
        r.random()

    # ---------------------------------------------------------------- zones and hosts
    def _zones_hosts(self):
        r = self.rng
        nz = 140 if not self.small else 14
        self.zones = {}
        for i in range(nz):
            std = r.choice([-10, -9, -8, -7, -6, -5, -4, -3, 0, 1, 2, 3, 4, 5, 5.5, 6, 8, 9, 10, 12]) * 3600
            rule = r.choice(["N", "N", "N", "S", "0"])
            dst = 0 if rule == "0" else r.choice([3600, 3600, 3600, 1800])
            if i in (0, 1, nz // 2, nz // 2 + 1):
                rule, dst = "N", 3600
            name = f"tz-{r.choice(WORDS)}-{i:03d}"
            self.zones[name] = {"std": int(std), "dst": dst, "rule": rule,
                                "part": "A" if i < nz // 2 else "B"}
        self.zone_names = sorted(self.zones)
        # explicit transition table, years 1995..2030
        self.tz_segments = {}
        for name, z in self.zones.items():
            segs = []
            for y in range(1995, 2031):
                start = g_epoch(y, 1, 1) - z["std"]
                if z["rule"] == "0":
                    segs.append((start, g_epoch(y + 1, 1, 1) - z["std"], z["std"], 0))
                    continue
                if z["rule"] == "N":
                    on = g_nth_sunday(y, 3, 2) * DAY + 2 * 3600 - z["std"]
                    off = g_nth_sunday(y, 11, 1) * DAY + 2 * 3600 - (z["std"] + z["dst"])
                    end = g_epoch(y + 1, 1, 1) - z["std"]
                    segs += [(start, on, z["std"], 0), (on, off, z["std"] + z["dst"], 1),
                             (off, end, z["std"], 0)]
                else:
                    off = g_nth_sunday(y, 4, 1) * DAY + 3 * 3600 - (z["std"] + z["dst"])
                    on = g_nth_sunday(y, 10, 1) * DAY + 2 * 3600 - z["std"]
                    end = g_epoch(y + 1, 1, 1) - (z["std"] + z["dst"])
                    segs += [(start - z["dst"], off, z["std"] + z["dst"], 1), (off, on, z["std"], 0),
                             (on, end, z["std"] + z["dst"], 1)]
            # merge contiguous segments into a clean, gapless list
            fixed = []
            for s in segs:
                if fixed:
                    s = (fixed[-1][1], s[1], s[2], s[3])
                fixed.append(s)
            self.tz_segments[name] = fixed
        nh = self.N
        self.hosts = {}
        used = set()
        for part in ("A", "B"):
            for i in range(nh):
                while True:
                    h = f"{r.choice(['nas', 'fs', 'app', 'db', 'wk', 'bk', 'lab', 'srv'])}-{r.choice(WORDS)}-{r.randrange(10000):04d}"
                    if h not in used:
                        used.add(h)
                        break
                self.hosts[h] = {"zone": r.choice(self.zone_names), "part": part}
        hosts_by_part = {"A": [h for h in self.hosts if self.hosts[h]["part"] == "A"],
                         "B": [h for h in self.hosts if self.hosts[h]["part"] == "B"]}
        self.hosts_by_part = hosts_by_part
        # each volume lives on one host; zones of DST kinds
        self.vol_host = {}
        dz = {p: [z for z in self.zone_names if self.zones[z]["rule"] == "N" and self.zones[z]["dst"] == 3600
                  and self.zones[z]["part"] == p] for p in ("A", "B")}
        for p in ("A", "B"):
            if not dz[p]:
                z = next(z for z in self.zone_names if self.zones[z]["part"] == p)
                self.zones[z].update(rule="N", dst=3600)
                dz[p] = [z]
        self.dz = dz
        for i, (code, *_rest) in enumerate(VOLUMES):
            part = "A" if code in ("ENG02", "LAB01", "HR01", "MKT01", "FIN01", "ARC01") else "B"
            h = hosts_by_part[part][(i * 7 + 3) % len(hosts_by_part[part])]
            self.hosts[h]["zone"] = dz[part][i % len(dz[part])]
            self.vol_host[code] = h
        # host aliases for uid tokens (ini): alias -> canonical host
        self.host_alias = {}
        canon_hosts = sorted(self.hosts)
        for i in range(self.N):
            h = canon_hosts[(i * 13) % len(canon_hosts)]
            a = f"{h.split('-')[0].upper()}{r.randrange(100000):05d}"
            while a in self.host_alias:
                a = f"{h.split('-')[0].upper()}{r.randrange(100000):05d}"
            self.host_alias[a] = h
        # clock incidents (rev7 Appendix D, adopted): host, from, to, skew seconds
        self.incidents = []

    # local-time conversion with the explicit table (ECS 4.3)
    def zone_offset_at(self, zone: str, t_utc: int) -> int:
        for s, e, off, _d in self.tz_segments[zone]:
            if s <= t_utc < e:
                return off
        return self.zones[zone]["std"]

    def local_to_utc(self, zone: str, local: int) -> int:
        """ECS 4.3: one reading -> it; two readings (fall-back) -> the standard-time one
        (smaller offset); no reading (spring-forward gap) -> the standard offset."""
        cands = []
        for s, e, off, _d in self.tz_segments[zone]:
            u = local - off
            if s <= u < e:
                cands.append(off)
        if not cands:
            return local - self.zones[zone]["std"]
        return local - min(cands)

    def utc_to_local(self, zone: str, t: int) -> int:
        return t + self.zone_offset_at(zone, t)


    # ---------------------------------------------------------------- tickets
    def _tickets(self):
        self.tickets = {}
        self.ticket_rows = []
        self.ticket_n = 1000

    def ticket(self, approved: bool = True, decided: int | None = None, kind: str = "plain") -> str:
        """Register a change ticket. kind: plain | late | revoked | sentinel | rejected."""
        r = self.rng
        self.ticket_n += r.randrange(1, 9)
        tid = f"CHG-{self.ticket_n:06d}"
        when = decided if decided is not None else self.win_start - r.randrange(DAY, 300 * DAY)
        if kind == "late":       # approved, but only at/after window.end -> not in effect
            revs = [(1, "APPROVED", self.win_end + (0 if r.random() < 0.5 else r.randrange(1, 9) * 3600))]
        elif kind == "revoked":  # approved then withdrawn in a later revision
            revs = [(1, "APPROVED", when), (2, "WITHDRAWN", when + DAY)]
        elif kind == "reinstated":  # rejected, then approved on review
            revs = [(1, "REJECTED", when), (2, "APPROVED", when + 2 * DAY)]
        elif kind == "sentinel":  # decided date never recorded
            revs = [(1, "APPROVED", None)]
        elif approved:
            revs = [(1, "PENDING", when - DAY), (2, "APPROVED", when)] if r.random() < 0.3 else [(1, "APPROVED", when)]
        else:
            revs = [(1, r.choice(["REJECTED", "PENDING", "WITHDRAWN"]), when)]
        self.tickets[tid] = revs
        rows = [{"ticket": tid, "rev": rv, "state": st, "decided": dc} for rv, st, dc in revs]
        self.ticket_rows.extend(rows)
        self.last_ticket_row = rows[-1]
        return tid

    def old_ticket(self) -> str:
        if not self.tickets:
            return self.ticket(True)
        keys = self.__dict__.setdefault("_tkeys", [])
        if len(keys) != len(self.tickets):
            keys[:] = list(self.tickets)
        return self.rng.choice(keys)

    def ticket_ok(self, tid: str | None) -> bool:
        if not tid or tid not in self.tickets:
            return False
        rev, state, decided = max(self.tickets[tid])
        return state == "APPROVED" and decided is not None and decided < self.win_end

    # ---------------------------------------------------------------- principals
    def _principals(self):
        r = self.rng
        NP = max(self.N, 300)
        self.principals = {}
        seen = set()
        for i in range(NP):
            while True:
                acct = f"{r.choice(FIRST)}.{r.choice(LAST)}{r.randrange(100) if r.random() < 0.6 else ''}"
                if acct not in seen:
                    seen.add(acct)
                    break
            pid = f"P{i + 1:07d}"
            self.principals[pid] = {"account": acct, "status": "active" if r.random() < 0.95 else "disabled"}
        self.pids = sorted(self.principals)
        # merges: chains over a subset
        self.merges = []   # rows: merge_id, from, to, effective, status, rev, part
        mfrom = r.sample(self.pids, max(40, NP // 9))
        targets = [p for p in self.pids if p not in set(mfrom)]
        self.merge_effective = {}
        for k, p in enumerate(mfrom):
            to = r.choice(targets) if k % 7 else (mfrom[k - 1] if k else r.choice(targets))
            if to == p:
                to = r.choice(targets)
            eff = self.win_start - r.randrange(DAY, 900 * DAY)
            part = "A" if k % 2 == 0 else "B"
            mid = f"MRG-{k + 1:05d}"
            self.merges.append({"merge_id": mid, "from": p, "to": to, "effective": eff, "status": "applied",
                                "rev": 1, "part": part})
            self.merge_effective[p] = to
        # avoid cycles
        for p in list(self.merge_effective):
            seenc = {p}
            q = self.merge_effective[p]
            while q in self.merge_effective:
                if q in seenc:
                    del self.merge_effective[p]
                    for m in self.merges:
                        if m["from"] == p:
                            m["status"] = "reverted"
                    break
                seenc.add(q)
                q = self.merge_effective[q]
        # namespaces and token rows (row dicts carry truth pid after normalisation)
        self.tok = {ns: {} for ns in TOKEN_FILES}   # ns -> norm token -> pid
        self.tok_rows = {ns: [] for ns in TOKEN_FILES}
        self.tok_by_pid = {ns: {} for ns in TOKEN_FILES}
        doms = {"CORP": (21, 1001), "ENG": (21, 2002), "FIN": (21, 3003), "HR": (21, 4004)}
        self.sid_dom = {d: f"S-1-5-21-{r.randrange(10**9)}-{r.randrange(10**9)}-{v[1]}" for d, v in doms.items()}
        n = self.N
        canon_hosts = sorted(self.hosts)
        for i in range(n):
            dom = ["CORP", "ENG", "FIN", "HR"][i % 4]
            pid = self.pids[(i * 7) % len(self.pids)]
            sid = f"{self.sid_dom[dom]}-{1000 + i}"
            self._add_tok("sid", sid, pid, domain=dom)
        for i in range(n):
            pid = self.pids[(i * 11 + 3) % len(self.pids)]
            host = canon_hosts[(i * 17) % len(canon_hosts)]
            uid = 1000 + (i * 37) % 60000
            self._add_tok("uid", f"uid:{host}:{uid}", pid, host=host, uid=uid)
        for ns, mult, fmt in (("corp", 13, "CORP\\{}"), ("email", 19, "{}@corp.example"),
                              ("svc", 23, "svc-{}"), ("mf", 29, "{}")):
            for i in range(n):
                pid = self.pids[(i * mult + 5) % len(self.pids)]
                acct = self.principals[pid]["account"]
                if ns == "corp":
                    tok = f"CORP\\{acct.replace('.', '')[:14]}{i % 97}"
                elif ns == "email":
                    tok = f"{acct}.{i % 89}@corp.example" if i % 3 == 0 else f"{acct}{i}@corp.example"
                elif ns == "svc":
                    tok = f"svc-{r.choice(WORDS)}-{i:05d}"
                else:
                    tok = f"MF{i:05d}"[:7]
                self._add_tok(ns, tok.lower() if ns in ("email", "svc") else (tok.upper() if ns == "mf" else self._norm_dom_login(tok)), pid)
        for i in range(n):
            pid = self.pids[(i * 31 + 7) % len(self.pids)]
            dom = LEGACY_DOMAINS[i % len(LEGACY_DOMAINS)]
            self._add_tok("legacy", f"{dom}\\{self.principals[pid]['account'].split('.')[0]}{i}", pid, domain=dom)
        for i in range(n):
            pid = self.pids[(i * 41 + 9) % len(self.pids)]
            self._add_tok("oldcorp", f"OLDCORP\\o{self.principals[pid]['account'].split('.')[1][:6]}{i}", pid)
        for i in range(n):
            pid = self.pids[(i * 43 + 11) % len(self.pids)]
            self._add_tok("s3", g_hex(r, 256), pid)
        # SID history (only in principal_directory.xlsx): old SID -> current SID
        self.sid_history = {}
        sids = list(self.tok["sid"])
        for i in range(n):
            old = f"S-1-5-21-{r.randrange(10**9)}-{r.randrange(10**9)}-9{i:04d}-{500 + i}"
            self.sid_history[old] = sids[(i * 3) % len(sids)]
        # stale account names in the 2025 directory (decoy mirror, about 5% differ)
        self.stale_accounts = {}
        for pid in r.sample(self.pids, max(10, len(self.pids) // 20)):
            self.stale_accounts[pid] = self.principals[pid]["account"].replace(".", "_") + "old"
        self.dir_only_pids = [f"P{len(self.pids) + 1 + i:07d}" for i in range(max(10, n // 50))]

    def _norm_dom_login(self, tok: str) -> str:
        dom, _, login = tok.partition("\\")
        return f"{dom.upper()}\\{login.lower()}"

    def _add_tok(self, ns, norm, pid, **extra):
        self.tok[ns][norm] = pid
        row = {"token": norm, "pid": pid, **extra}
        self.tok_rows[ns].append(row)
        self.tok_by_pid[ns].setdefault(pid, []).append(norm)

    def add_merge(self, frm, to, eff, part, tag):
        rev = 1 + max([m["rev"] for m in self.merges if m["from"] == frm] or [0])
        m = {"merge_id": f"MRG-{tag}{len(self.merges):05d}", "from": frm, "to": to, "effective": eff,
             "status": "applied", "rev": rev, "part": part}
        self.merges.append(m)
        return m

    def resolve_pid(self, pid: str) -> str | None:
        """Follow merges effective strictly before window.end; None when unknown."""
        if pid not in self.principals:
            return None
        seenc = set()
        while pid in self.merge_effective_now and pid not in seenc:
            seenc.add(pid)
            pid = self.merge_effective_now[pid]
        return pid

    # ---------------------------------------------------------------- aliases
    def _aliases(self):
        r = self.rng
        n = self.N
        self.alias_rows = {p: [] for p in ALIAS_FILE}
        self.tops = {v[0]: [] for v in VOLUMES}   # volume -> list of top dicts (effective aliases)
        part_vols = {p: [v[0] for v in VOLUMES if p in v[4]] for p in ALIAS_FILE}
        self.serials = {}  # serial -> volume (CMDB crosswalk, decoy volumes_cmdb.json)
        for code, *_ in VOLUMES:
            for k in range(3):
                self.serials[f"VS-{r.randrange(16**6):06X}"] = code
        for k in range(max(n - 36, 10)):
            self.serials[f"VS-{r.randrange(16**6):06X}"] = r.choice(["RETIRED", "ARC00", "TST09"])
        self.vol_serial = {}
        for s, v in self.serials.items():
            if v in VOL and v not in self.vol_serial:
                self.vol_serial[v] = s
        aid = 0
        for part, vols in part_vols.items():
            if not vols:
                continue
            per = max((2 * n if part == "B" else n) // len(vols), 4)
            for vi, vol in enumerate(vols):
                stem = VOL[vol][3]
                for k in range(per):
                    aid += 1
                    num = len(self.tops[vol]) + 1
                    prefix = f"/{stem}-{num:04d}/"
                    root = self._alias_root(part, vol, num, r)
                    vref = f"serial:{self.vol_serial[vol]}" if part in ("C", "D") else vol
                    row = {"alias_id": f"AL{aid:06d}", "root": root, "volume": vref, "prefix": prefix,
                           "rev": 1, "status": "active", "part": part}
                    self.alias_rows[part].append(row)
                    self.tops[vol].append({"root": root, "prefix": prefix, "part": part, "state": "ok",
                                           "row": row})
        for k in range(OBJ_TOPS if not self.small else 30):
            b = f"bkt-{r.choice(WORDS)}-{k:04d}"
            self.tops["OBJ01"].append({"root": f"s3://{b}/", "prefix": f"/{b}/", "part": "S", "state": "ok",
                                       "row": None})
        for part in ALIAS_FILE:
            while len(self.alias_rows[part]) < n:
                aid += 1
                vol = r.choice([v for v in part_vols[part]] or ["FIN01"])
                num = len(self.tops[vol]) + 1
                root = self._alias_root(part, vol, num, r)
                prefix = f"/{VOL[vol][3]}-{num:04d}/"
                vref = f"serial:{self.vol_serial[vol]}" if part in ("C", "D") else vol
                row = {"alias_id": f"AL{aid:06d}", "root": root, "volume": vref, "prefix": prefix,
                       "rev": 1, "status": "active", "part": part}
                self.alias_rows[part].append(row)
                self.tops[vol].append({"root": root, "prefix": prefix, "part": part, "state": "ok", "row": row})

    def _alias_root(self, part, vol, num, r):
        low = vol.lower()
        if part == "A":
            return f"\\\\nas-{low}\\s{num:04x}{r.choice('abcdef')}\\"
        if part == "B":
            srv = "mkt-fs" if vol == "MKT01" else "hr-fs"
            return f"smb://{srv}/{r.choice(WORDS).title()}{num:04d}/"
        if part == "C":
            return f"\\\\corp.example\\dfs\\{low}\\{r.choice(WORDS)}{num:04d}\\"
        if part == "D":
            return f"\\\\oldnas01\\{low}\\{r.choice(WORDS)}-{num:04d}\\"
        if part == "E":
            if vol == "ARC01":
                return f"/ltfs/T{num:05d}L8/"
            return f"/exports/{low}/{r.choice(WORDS)}{num:04d}/"
        if vol == "RND01":
            return f"/mnt/cold/rnd01/{r.choice(WORDS)}{num:04d}/"
        return f"nfs://{low}-nfs/{r.choice(WORDS)}{num:04d}/"

    # ---------------------------------------------------------------- extensions, rules
    def _exts_rules(self):
        r = self.rng
        n = self.N
        letters = "abcdefghijklmnopqrstuvwxyz"
        pool = set()
        base_exts = ["txt", "pdf", "docx", "xlsx", "pptx", "jpg", "png", "tif", "dwg", "dxf", "step",
                     "py", "c", "h", "java", "tmp", "log", "bak", "zip", "tar.gz", "tgz", "mov",
                     "mp4", "wav", "eml", "msg", "pst", "db", "sqlite", "csv", "cfg", "ini", "yaml",
                     "vmdk", "qcow2", "iso", "nii.gz", "fits", "shp", "geojson", "ttf", "html", "css"]
        fam_of = {"txt": "DOC", "pdf": "DOC", "docx": "DOC", "xlsx": "SHT", "pptx": "PRS", "jpg": "IMG",
                  "png": "IMG", "tif": "IMG", "dwg": "CAD", "dxf": "CAD", "step": "CAD", "py": "SRC",
                  "c": "SRC", "h": "SRC", "java": "SRC", "tmp": "TMP", "log": "LOG", "bak": "BAK",
                  "zip": "ARC", "tar.gz": "ARC", "tgz": "ARC", "mov": "MED", "mp4": "MED", "wav": "MED",
                  "eml": "MAIL", "msg": "MAIL", "pst": "MAIL", "db": "DBF", "sqlite": "DBF", "csv": "SHT",
                  "cfg": "CFG", "ini": "CFG", "yaml": "CFG", "vmdk": "VMI", "qcow2": "VMI", "iso": "VMI",
                  "nii.gz": "SCI", "fits": "SCI", "shp": "GEO", "geojson": "GEO", "ttf": "FNT",
                  "html": "WEB", "css": "WEB"}
        while len(pool) < n * 7 + 200:
            k = r.choice([2, 3, 3, 4])
            e = "".join(r.choice(letters) for _ in range(k))
            if r.random() < 0.08:
                e = e + "." + r.choice(["gz", "zst", "xz", "bz2"])
            if e not in fam_of:
                pool.add(e)
        pool = sorted(pool)
        r.shuffle(pool)
        self.ext_rows = {p: [] for p in EXT_PRECEDENCE}
        self.ext_truth = {}
        idx = 0
        for pi, part in enumerate(EXT_PRECEDENCE):
            size = 2 * n if part == "B" else n
            mine = pool[idx: idx + size - (len(base_exts) if pi == 4 else 0)]
            idx += len(mine)
            if part == "E":
                mine = base_exts + mine
            for e in mine:
                fam = fam_of.get(e) or r.choice(FAMILIES)
                self.ext_rows[part].append({"ext": e, "family": fam, "rev": 1, "status": "active", "part": part})
        self.all_exts = [row["ext"] for p in EXT_PRECEDENCE for row in self.ext_rows[p]]
        self.common_exts = base_exts
        # classes (retention-schedule r2)
        self.classes = dict(CLASSES)
        # rules
        self.rules_v3 = []
        self.rules_overlay = []
        seq = 0
        for pat, cls in [("*.tmp", "temp"), ("*.bak", "backup"), ("*~", "temp"), ("~$*", "temp"),
                         ("*.log", "logs"), ("Thumbs.db", "temp"), ("scratch/", "scratch"),
                         ("*.core", "temp")]:
            seq += 10
            self.rules_v3.append({"seq": seq, "scope": "*", "pattern": pat, "class": cls, "status": "active"})
        for fam, cls in FAMILY_CLASS_RULES.items():
            seq += 10
            self.rules_v3.append({"seq": seq, "scope": "*", "pattern": f"family:{fam}", "class": cls,
                                  "status": "active"})
        vols = [v[0] for v in VOLUMES]
        k = 0
        while len(self.rules_v3) < n:
            vol = vols[k % len(vols)]
            k += 1
            tops = self.tops[vol]
            top = tops[(k * 7) % len(tops)]["prefix"].strip("/")
            kind = k % 6
            if kind == 0:
                pat, cls = f"/{top}/build/", "build"
            elif kind == 1:
                pat, cls = f"/{top}/**/tmp/", "temp"
            elif kind == 2:
                pat, cls = f"/{top}/archive/**/*.pdf", "records"
            elif kind == 3:
                pat, cls = f"/{top}/media/*", "media"
            elif kind == 4:
                pat, cls = f"/{top}/keep/", "standard"
            else:
                pat, cls = f"/{top}/logs/*.gz", "logs"
            seq += 10
            self.rules_v3.append({"seq": seq, "scope": vol if k % 3 else "*", "pattern": pat, "class": cls,
                                  "status": "active"})
        oseq = 0
        k = 0
        while len(self.rules_overlay) < n:
            vol = vols[(k * 5) % len(vols)]
            k += 1
            tops = self.tops[vol]
            top = tops[(k * 11) % len(tops)]["prefix"].strip("/")
            kind = k % 5
            if kind == 0:
                pat, cls = f"/{top}/close/**", "records"
            elif kind == 1:
                pat, cls = f"/{top}/scratch/keep*/", "standard"
            elif kind == 2:
                pat, cls = f"/{top}/**/*.log", "standard"
            elif kind == 3:
                pat, cls = f"/{top}/data/*.csv", "records"
            else:
                pat, cls = f"/{top}/tmp/*.lock", "temp"
            oseq += 5
            self.rules_overlay.append({"seq": oseq, "scope": vol, "pattern": pat, "class": cls})

    # ---------------------------------------------------------------- batches
    def _batches(self):
        r = self.rng
        n = self.N
        self.batch_rows = {p: [] for p in BATCH_FILES}
        self.batches = {}
        unit_choices = ["B", "KiB", "KB", "blk512", "blk4096", "MiB"]
        bid = 0
        for part in BATCH_FILES:
            for i in range(n):
                bid += 1
                b = f"B{part}{bid:06d}"
                unit = r.choice(unit_choices)
                cap = self.win_start - r.randrange(3600, 120 * DAY)
                row = {"batch": b, "unit": unit, "captured": cap, "part": part}
                self.batch_rows[part].append(row)
                self.batches[b] = {"unit": unit, "captured": cap, "part": part}
        self.batch_ids = sorted(self.batches)

    def batch_unit(self, b):
        return self.batches[b]["unit"]

    # ---------------------------------------------------------------- configuration layers
    def _config(self):
        r = self.rng
        n = self.N
        prev_q = g_iso(self.prev_start), g_iso(self.win_start)
        cur_q = g_iso(self.win_start), g_iso(self.win_end)
        self.cfg_layers = {10: [], 20: [], 30: [], 40: []}

        def put(layer, key, value, profile="*", final=False, ticket=None, oid=None, unit=None):
            self.cfg_layers[layer].append({"key": key, "value": value, "profile": profile, "final": final,
                                           "ticket": ticket, "oid": oid, "unit": unit})

        put(10, "window.start", prev_q[0])
        put(10, "window.end", prev_q[1])
        put(10, "purge.enabled", False)
        put(10, "store.block_size", 4096)
        put(10, "vol.RND01.case", "insensitive")
        put(20, "window.start", cur_q[0])
        put(20, "window.end", cur_q[1], final=True)
        put(20, "purge.enabled", True)
        put(20, "purge.enabled", False, profile="dev")
        put(20, "store.block_size", 65536, final=True)
        put(20, "store.block_size", 16384, profile="dev")
        put(20, "vol.RND01.case", "sensitive")
        put(30, "vol.LAB01.zone", self.hosts[self.vol_host["LAB01"]]["zone"])
        zone_override = self.dz["B"][-1]
        put(30, "vol.OPS01.zone", zone_override)
        self.oid = 0

        def override(key, value, approved=True, kind="plain", profile="*", unit=None):
            self.oid += 1
            oid = f"OVR-{self.oid:05d}"
            t = self.ticket(approved=approved, kind=kind)
            put(40, key, value, profile=profile, ticket=t, oid=oid, unit=unit)
            return oid

        override("window.end", g_iso(self.win_end + DAY), approved=True)
        override("store.block_size", 131072, approved=True, unit="B")
        override("purge.enabled", False, approved=False)
        self.ovr_zone = override("vol.ENG02.zone", self.zone_names[3], approved=True)
        override("vol.HR01.zone", self.zone_names[5], kind="late")
        self.ovr_revocable = override("vol.FIN02.zone", self.zone_names[7], approved=True)
        self.revocations = [{"oid": self.ovr_revocable, "ticket": self.ticket(True)},
                            {"oid": self.ovr_zone, "ticket": self.ticket(False)}]
        # subtree exemptions: key subtree.<VOL>:<prefix>.<flag>
        vols = [v[0] for v in VOLUMES]
        self.subtree_keys = []
        for layer in (10, 20, 30, 40):
            cnt = 0
            k = 0
            seen_keys = {x["key"] for x in self.cfg_layers[layer]}
            while cnt < n:
                k += 1
                vol = vols[(k * 3 + layer) % len(vols)]
                tops = self.tops[vol]
                top = tops[(k * 13 + layer) % len(tops)]["prefix"]
                sub = r.choice(["", "scratch/", "tmp/", "build/", "logs/", "archive/", "keep/"])
                flag = r.choice(["purge_exempt", "archive_exempt"])
                key = f"subtree.{vol}:{top}{sub}.{flag}"
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                val = r.random() < 0.6
                if layer == 40:
                    override(key, val, approved=r.random() < 0.7,
                             kind=r.choice(["plain", "plain", "plain", "late", "revoked", "reinstated", "sentinel"]))
                else:
                    put(layer, key, val, profile="dev" if r.random() < 0.05 else "*",
                        final=(layer == 20 and r.random() < 0.05))
                cnt += 1

    def cfg_plant(self):
        if not hasattr(self, "_cfg_plant"):
            self._cfg_plant = self.effective_config("prod")
        return self._cfg_plant

    def effective_config(self, profile: str) -> dict:
        locked = set()
        eff = {}
        revoked = {x["oid"] for x in self.revocations if self.ticket_ok(x["ticket"])}
        for layer in (10, 20, 30, 40):
            rows = self.cfg_layers[layer]
            newly_locked = set()
            for pass_profile in ("*", profile):
                for row in rows:
                    if row["profile"] != pass_profile:
                        continue
                    if row["key"] in locked:
                        continue
                    if layer == 40 and (not self.ticket_ok(row["ticket"]) or row["oid"] in revoked):
                        continue
                    eff[row["key"]] = row["value"]
                    if row["final"]:
                        newly_locked.add(row["key"])
            locked |= newly_locked
        return dict(sorted(eff.items()))

    # ---------------------------------------------------------------- contents
    def _contents(self):
        self.contents = []          # list of dicts sha256, md5, sha1, size
        self.content_by_sha = {}
        self.xwalk_rows = {p: [] for p in XWALK_FILE}
        self.xwalk = {p: {} for p in XWALK_FILE}

    def new_content(self, size: int | None = None, reuse: float = 0.07) -> dict:
        r = self.rng
        if self.contents and r.random() < reuse:
            return r.choice(self.contents[-4000:])
        if size is None:
            roll = r.random()
            if roll < 0.02:
                size = 0
            elif roll < 0.025:
                size = r.randrange(2 ** 41, 2 ** 42)
            else:
                size = int(2 ** (r.random() * 26 + 6))
        if size in (9999, 9999000, 10238976, 5119488, 40955904, 10484711424):
            size += 1
        c = {"sha256": g_hex(r, 256), "md5": g_hex(r, 128), "sha1": g_hex(r, 160), "size": size}
        self.contents.append(c)
        self.content_by_sha[c["sha256"]] = c
        return c

    # ---------------------------------------------------------------- authority
    def _authority(self):
        r = self.rng
        n = self.N
        self.runs = []
        self.snapshot = {}
        for code, *_ in VOLUMES:
            self.snapshot[code] = self.win_start + r.randrange(2 * DAY, 20 * DAY)
        self.self_mode = {f: "full" for f in INVENTORY_FILES}
        for f in ("inv_eng01_q3_part2.db", "inv_mkt01_supplement.xlsx", "rnd01_cold_listing.pdf"):
            self.self_mode[f] = "continuation"
        self.self_mode["inv_fin01_q3_r2.csv"] = "dryrun"
        self.self_mode["inv_eng01_q3_deep.jsonl"] = "deep-scan"
        self.self_mode["arc01_ltfs_index.db"] = "ltfs-shadow"
        rid = 0
        for f, vol in INVENTORY_FILES.items():
            rid += 1
            comp = self.snapshot[vol] if self.self_mode[f] == "full" else self.snapshot[vol] + r.randrange(60, 7200)
            if f in DECOYS:
                comp = self.snapshot[vol] + r.randrange(DAY, 5 * DAY)   # newer than the real export
            self.runs.append({"run_id": f"RUN-{rid:05d}", "file": f, "volume": vol,
                              "kind": "full" if f in DECOYS else self.self_mode[f], "completed": comp,
                              "status": "complete", "superseded_by": ""})
        # older runs, superseded
        while len(self.runs) < n:
            rid += 1
            vol = r.choice(list(VOL))
            old = f"inv_{vol.lower()}_{r.choice(['2025q1', '2025q2', '2025q3', '2025q4', '2026q1'])}.csv"
            self.runs.append({"run_id": f"RUN-{rid:05d}", "file": old, "volume": vol,
                              "kind": r.choice(["full", "continuation", "dryrun"]),
                              "completed": self.prev_start - r.randrange(DAY, 700 * DAY),
                              "status": r.choice(["complete", "failed", "complete"]),
                              "superseded_by": f"RUN-{r.randrange(1, rid):05d}"})
        self.scope_overrides = []
        self.ratification = []

    # ---------------------------------------------------------------- source records
    def _usable_tops(self, vol, parts):
        cache = self.__dict__.setdefault("_tops_cache", {})
        key = (vol, parts)
        if key not in cache:
            tops = [t for t in self.tops[vol] if t["state"] == "ok" and t["part"] in parts]
            cache[key] = tops or [t for t in self.tops[vol] if t["state"] == "ok"]
        return cache[key]

    def _name(self, vol, ext=None, special=None):
        r = self.rng
        self.name_seq = getattr(self, "name_seq", 0) + 1
        w = r.choice(WORDS)
        if r.random() < 0.12:
            w = r.choice(UNI_WORDS)
        if r.random() < 0.3:
            w = w.title()
        sep = r.choice(["_", "-", " ", "_"])
        ext = ext or (r.choice(self.common_exts) if r.random() < 0.7 else r.choice(self.all_exts))
        base = f"{w}{sep}{self.name_seq:06d}"
        if special:
            base = f"{w}{special}{self.name_seq:06d}"
        return f"{base}.{ext}"

    def _sub(self):
        r = self.rng
        sub = r.choice(SUBDIRS)
        if r.random() < 0.35:
            sub += "/" + r.choice(SUBDIRS + [r.choice(WORDS)])
        return sub

    def mk_rec(self, file, vol, kind="inv", top=None, rest=None, content=None, mtime=None,
               pid=None, ns=None, batch=None, file_id=None, nlink=1, tags=(), cs_prefix=None, insert=None):
        r = self.rng
        parts = FILE_PARTS[file]
        if top is None:
            top = r.choice(self._usable_tops(vol, parts))
        if rest is None:
            rest = self._sub() + "/" + self._name(vol)
        content = content or self.new_content()
        if mtime is None:
            hi = self.snapshot[vol] - 3600
            mtime = r.randrange(g_epoch(2005, 1, 1), hi) if r.random() < 0.9 else r.randrange(hi - 400 * DAY, hi)
        if pid is None:
            ns = ns or r.choice(SOURCE_OWNER[file].split("|"))
            pids = list(self.tok_by_pid[ns])
            pid = r.choice(pids)
        if ns is None:
            ns = SOURCE_OWNER[file].split("|")[0]
        toks = self.tok_by_pid[ns].get(pid)
        if not toks:
            pid = r.choice(list(self.tok_by_pid[ns]))
            toks = self.tok_by_pid[ns][pid]
        token = r.choice(toks)
        if batch is None:
            batch = r.choice(self.batch_ids)
        rec = {"rec_id": self.new_rec_id(file), "file": file, "kind": kind, "vol": vol,
               "root": top["root"], "top": top, "rest": rest, "content": content,
               "hash": self._hash_repr(file, content), "size": ("bytes", content["size"]),
               "time": ("utc", mtime), "owner": (ns, token), "file_id": file_id, "nlink": nlink,
               "batch": batch, "flags": {}, "tags": set(tags), "mtime_intent": mtime}
        if file in BATCH_UNIT_SOURCES:
            rec["size"] = ("unit", content["size"])
        if insert is None:
            self.rows[file].append(rec)
        else:
            self.rows[file].insert(insert, rec)
        self.recs.append(rec)
        self.rec_by_id[rec["rec_id"]] = rec
        return rec

    def _hash_repr(self, file, content):
        alg = SOURCE_HASH[file]
        if alg != "sha256" and self.rng.random() < 0.7:
            return ("sha256", content["sha256"])
        if alg == "sha256":
            return ("sha256", content["sha256"])
        if alg in ("md5", "md5b64"):
            self._need_xwalk(file, "md5", content["md5"], content)
            return (alg, content["md5"])
        if alg == "etag":
            if self.rng.random() < 0.15:
                et = f"{content['md5']}-{self.rng.randrange(2, 40)}"
            else:
                et = content["md5"]
            self._need_xwalk(file, "md5", et, content)
            return ("etag", et)
        self._need_xwalk(file, "sha1", content["sha1"], content)
        return ("sha1", content["sha1"])

    def _need_xwalk(self, file, alg, digest, content):
        vol = INVENTORY_FILES.get(file) or JOURNAL_FILES.get(file)
        part = XWALK_FOR_VOLUME[alg][vol]
        if digest not in self.xwalk[part]:
            self.xwalk[part][digest] = content["sha256"]
            self.xwalk_rows[part].append({"digest": digest, "sha256": content["sha256"], "status": "ok",
                                          "rev": 1, "alg": alg, "origin": vol})

    def _entries(self):
        r = self.rng
        n = self.N
        self.merge_effective_now = dict(self.merge_effective)
        plan = {
            "inv_eng01_q3.csv": n, "inv_eng01_q3_part2.db": n, "inv_eng02_q3.txt": n,
            "inv_mkt01_q3.jsonl": n, "inv_mkt01_supplement.xlsx": 2 * n, "inv_fin01_q3.parquet": n,
            "inv_fin02_q3.tsv": n, "arc01_tape_catalog.txt": n, "inv_obj01_q3_r2.csv": n,
            "inv_hr01_q3.xlsx": 2 * n, "inv_lab01_q3.jsonl": n, "inv_ops01_q3.tsv": n,
            "inv_rnd01_q3.json": n, "rnd01_cold_listing.pdf": n, "inv_leg01_q3.xml": n,
        }
        for file, count in plan.items():
            vol = INVENTORY_FILES[file]
            fid_ok = file in ("inv_eng01_q3.csv", "inv_eng01_q3_part2.db", "inv_fin01_q3.parquet",
                              "inv_ops01_q3.tsv")
            fid_seq = r.randrange(10**6)
            for i in range(count):
                fid_seq += r.randrange(1, 50)
                rec = self.mk_rec(file, vol, file_id=(f"{fid_seq:x}" if fid_ok else None))
                if file == "arc01_tape_catalog.txt":
                    rec["file_id"] = f"{fid_seq:x}"
            # hardlink groups
            if fid_ok or file == "arc01_tape_catalog.txt":
                rows = self.rows[file]
                for g in range(max(3, count // 400)):
                    a = rows[r.randrange(len(rows))]
                    k = r.choice([2, 2, 3])
                    for _ in range(k - 1):
                        b = self.mk_rec(file, vol, top=a["top"], content=a["content"], mtime=a["mtime_intent"],
                                        file_id=a["file_id"], nlink=k, insert=r.randrange(len(rows)),
                                        tags={"C3", "hardlink"})
                        b["owner"] = a["owner"]
                        b["batch"] = a["batch"]
                    a["nlink"] = k
                    a["tags"] |= {"C3", "hardlink"}
        self._mirror_decoys()

    def _mirror_decoys(self):
        """Decoy exports copy the real export they shadow, agreeing on about 95% of rows."""
        r = self.rng
        for decoy, src in (("inv_fin01_q3_r2.csv", "inv_fin01_q3.parquet"),
                           ("inv_eng01_q3_deep.jsonl", "inv_eng01_q3.csv"),
                           ("arc01_ltfs_index.db", "arc01_tape_catalog.txt")):
            vol = INVENTORY_FILES[decoy]
            for i, s in enumerate(self.rows[src][: self.N]):
                rec = self.mk_rec(decoy, vol, top=s["top"], rest=s["rest"], content=s["content"],
                                  mtime=s["mtime_intent"], file_id=s["file_id"], nlink=s["nlink"])
                rec["owner"] = s["owner"]
                rec["batch"] = s["batch"]
                rec["mirror_of"] = s["rec_id"]
                if r.random() < 0.05:
                    rec["content"] = self.new_content(reuse=0)
                    rec["hash"] = self._hash_repr(decoy, rec["content"])
                    rec["tags"].add("T16")
                    s["tags"].add("T16")
                    s["tags"].add(f"D:{decoy}")
                    self.trap(decoy, rec["rec_id"], "T16", "ECS 3.2 self-declared run mode", f"decoy:{decoy}",
                              [s["rec_id"]], "pull")

