def g_exact_div(num: int, den: int) -> str:
    """Exact decimal string of num/den where den has only factors 2 and 5."""
    q, rem = divmod(num, den)
    if rem == 0:
        return str(q)
    digits = []
    while rem and len(digits) < 40:
        rem *= 10
        d, rem = divmod(rem, den)
        digits.append(str(d))
    return f"{q}." + "".join(digits)


def g_glob_regex(pat: str) -> str:
    out = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if pat.startswith("**/", i):
            out.append("(?:.*/)?")
            i += 3
            continue
        if pat.startswith("/**", i) and i + 3 == len(pat):
            out.append("(?:/.*)?")
            i += 3
            continue
        if pat.startswith("**", i):
            out.append(".*")
            i += 2
            continue
        if c == "*":
            out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        else:
            out.append(re_escape(c))
        i += 1
    return "".join(out)


def re_escape(c: str) -> str:
    return "\\" + c if c in ".^$+{}[]|()\\" else c


import re as _re  # noqa: E402


class GenRules:
    """Retention rule matcher over canonical paths (ECS section 7)."""

    def __init__(self, rules):
        self.global_rules = []
        self.by_top = {}
        for order, rule in enumerate(rules):
            pat = rule["pattern"]
            entry = (order, rule, self._compile(pat))
            first = pat.lstrip("/").split("/", 1)[0] if ("/" in pat.rstrip("/") and not pat.startswith("family:")) else None
            if first and "*" not in first and "?" not in first:
                self.by_top.setdefault(first, []).append(entry)
            else:
                self.global_rules.append(entry)

    @staticmethod
    def _compile(pat):
        if pat.startswith("family:"):
            return ("family", pat[7:])
        dir_only = pat.endswith("/")
        body = pat[:-1] if dir_only else pat
        anchored = "/" in body
        body = body.lstrip("/")
        return ("glob", _re.compile(g_glob_regex(body) + r"\Z"), anchored, dir_only,
                _re.compile(g_glob_regex(body.lower()) + r"\Z"))

    def classify(self, vol, path, family, ci):
        segs = path.strip("/").split("/")
        cands = self.global_rules + self.by_top.get(segs[0], [])
        cands.sort(key=lambda e: e[0])
        cls = "standard"
        rel = "/".join(segs)
        for _order, rule, comp in cands:
            if rule["scope"] not in ("*", vol):
                continue
            if comp[0] == "family":
                if family == comp[1]:
                    cls = rule["class"]
                continue
            _, rx, anchored, dir_only, rx_low = comp
            if ci:
                rx = rx_low
            hit = False
            if dir_only:
                dirs = segs[:-1]
                if anchored:
                    hit = any(rx.match("/".join(dirs[:k])) for k in range(1, len(dirs) + 1))
                else:
                    hit = any(rx.match(d) for d in dirs)
            else:
                hit = bool(rx.match(rel if anchored else segs[-1]))
            if hit:
                cls = rule["class"]
        return cls


class GenMore:
    # ---------------------------------------------------------------- raw path construction
    def raw_path(self, rec):
        top, rest, vol = rec["top"], rec["rest"], rec["vol"]
        root = rec.get("root_variant") or top["root"]
        if top["part"] == "S":
            key = rest
            enc = "".join(ch if (ch.isalnum() and ch.isascii()) or ch in "-_.~/" else
                          "".join(f"%{b:02X}" for b in ch.encode("utf-8")) for ch in key)
            return root + enc
        if vol == "MKT01":
            rest = unicodedata.normalize("NFD", rest)
        if root.startswith("\\\\"):
            return root + rest.replace("/", "\\")
        return root + rest

    # ---------------------------------------------------------------- journals
    def _journals(self):
        r = self.rng
        n = self.N
        self.events = []
        live = {}
        for rec in self.recs:
            if rec["kind"] == "inv" and rec["file"] not in DECOYS:
                live.setdefault(rec["vol"], []).append(rec)
        self.mkt_gap = None
        seq_base = {}
        for jfile, vol in JOURNAL_FILES.items():
            if jfile == "journal_mkt01_q3_b.log":
                continue
            pool = list(live.get(vol, []))
            r.shuffle(pool)
            alive = pool[: max(50, len(pool) // 2)]
            dead = []
            seq = r.randrange(1000, 90000) if vol != "OBJ01" else r.randrange(16**10, 16**11)
            seq_base[jfile] = seq
            snap = self.snapshot[vol]
            span = self.win_end - snap
            ts = snap + r.randrange(60, 3600)
            count = n + n // 20 + 10 if vol == "MKT01" else n
            for i in range(count):
                seq += r.randrange(1, 4) if vol != "OBJ01" else r.randrange(1, 16**4)
                ts += max(1, int(span / (count + 5) * r.uniform(0.2, 1.8)))
                ts_ev = min(ts, self.win_end - 30)
                roll = r.random()
                if roll < 0.04:
                    ts_ev = snap - r.randrange(60, 30 * DAY)
                elif roll < 0.07:
                    ts_ev = self.win_end + r.randrange(0, 20 * DAY)
                elif roll < 0.10:
                    ts_ev = ts_ev - r.randrange(60, 6 * 3600)
                opr = r.random()
                ev = None
                if vol == "OBJ01":
                    op = "CREATE" if opr < 0.55 or not alive else "DELETE"
                elif opr < 0.36 and alive:
                    op = "MODIFY"
                elif opr < 0.54:
                    op = "CREATE"
                elif opr < 0.66 and alive:
                    op = "RENAME"
                elif opr < 0.76 and alive:
                    op = "DELETE"
                elif opr < 0.81 and dead:
                    op = "RESTORE"
                elif opr < 0.85:
                    op = "ORPHAN"
                else:
                    op = "MODIFY" if alive else "CREATE"
                if op == "CREATE" and vol == "OBJ01" and alive and r.random() < 0.3:
                    tgt = r.choice(alive)
                    ev = self.mk_event(jfile, vol, "CREATE", seq, ts_ev, top=tgt["top"], rest=tgt["rest"])
                elif op == "CREATE":
                    top = r.choice(self._usable_tops(vol, FILE_PARTS[jfile]))
                    ev = self.mk_event(jfile, vol, "CREATE", seq, ts_ev, top=top, rest=self._sub() + "/" + self._name(vol))
                    alive.append(ev)
                elif op == "MODIFY":
                    tgt = r.choice(alive)
                    ev = self.mk_event(jfile, vol, "MODIFY", seq, ts_ev, top=tgt["top"], rest=tgt["rest"])
                elif op == "RENAME":
                    tgt = r.choice(alive)
                    newtop = tgt["top"] if r.random() < 0.7 else r.choice(self._usable_tops(vol, FILE_PARTS[jfile]))
                    newrest = (tgt["rest"].rsplit("/", 1)[0] + "/" + self._name(vol)) if r.random() < 0.85 else r.choice(alive)["rest"]
                    ev = self.mk_event(jfile, vol, "RENAME", seq, ts_ev, top=tgt["top"], rest=tgt["rest"],
                                       newtop=newtop, newrest=newrest)
                    alive.remove(tgt)
                    alive.append({"top": newtop, "rest": newrest})
                elif op == "DELETE":
                    tgt = alive.pop(r.randrange(len(alive)))
                    ev = self.mk_event(jfile, vol, "DELETE", seq, ts_ev, top=tgt["top"], rest=tgt["rest"])
                    dead.append(tgt)
                elif op == "RESTORE":
                    tgt = dead.pop(r.randrange(len(dead)))
                    ev = self.mk_event(jfile, vol, "RESTORE", seq, ts_ev, top=tgt["top"], rest=tgt["rest"])
                    alive.append(tgt)
                else:
                    top = r.choice(self._usable_tops(vol, FILE_PARTS[jfile]))
                    ev = self.mk_event(jfile, vol, "MODIFY", seq, ts_ev, top=top,
                                       rest=self._sub() + "/" + self._name(vol))
                if vol == "OBJ01" and op == "DELETE" and r.random() < 0.3:
                    ev["s3_marker"] = True
            if vol == "MKT01":
                evs = self.rows[jfile]
                a = len(evs) // 2
                b = a + max(4, len(evs) // 25)
                self.mkt_gap = (evs[a]["seq"], evs[b]["seq"])
                self.mkt_gap_events = evs[a:b + 1]
                self.rows[jfile] = evs[:a] + evs[b + 1:]
        self._replica_journal()

    def mk_event(self, jfile, vol, op, seq, ts, top, rest, newtop=None, newrest=None):
        r = self.rng
        ev = {"rec_id": self.new_rec_id(jfile), "file": jfile, "kind": "jrn", "vol": vol, "op": op,
              "seq": seq, "ts": ts, "top": top, "rest": rest, "root": top["root"], "newtop": newtop,
              "newrest": newrest, "flags": {}, "tags": set(), "host": self.vol_host[vol], "file_id": None,
              "nlink": 1, "batch": r.choice(self.batch_ids)}
        if op in ("CREATE", "MODIFY"):
            c = self.new_content()
            ev["content"] = c
            ev["hash"] = self._hash_repr(jfile, c)
            ev["size"] = ("bytes", c["size"])
        if op == "CREATE":
            ns = r.choice(SOURCE_OWNER[jfile].split("|"))
            pid = r.choice(list(self.tok_by_pid[ns]))
            ev["owner"] = (ns, r.choice(self.tok_by_pid[ns][pid]))
        if jfile in HOST_JOURNALS and r.random() < 0.15:
            ev["host"] = r.choice(sorted(self.hosts))
        self.rows[jfile].append(ev)
        self.recs.append(ev)
        self.rec_by_id[ev["rec_id"]] = ev
        return ev

    def _replica_journal(self):
        r = self.rng
        prim = "journal_mkt01_q3.log"
        rep = "journal_mkt01_q3_b.log"
        merged = sorted(self.rows[prim] + self.mkt_gap_events, key=lambda e: e["seq"])
        for e in merged:
            ev = dict(e)
            ev["rec_id"] = self.new_rec_id(rep)
            ev["file"] = rep
            ev["tags"] = set()
            ev["flags"] = {}
            ev["mirror_of"] = e["rec_id"]
            if e in self.mkt_gap_events:
                self.recs.remove(e)
                del self.rec_by_id[e["rec_id"]]
                ev["tags"] |= {"D:journal_mkt01_q3_b.log", "C5"}
            elif r.random() < 0.05 and ev["op"] in ("MODIFY", "CREATE"):
                ev["content"] = self.new_content(reuse=0)
                ev["hash"] = self._hash_repr(rep, ev["content"])
                ev["size"] = ("bytes", ev["content"]["size"])
                ev["tags"].add("T16")
                e["tags"] |= {"T16", "D:journal_mkt01_q3_b.log"}
                self.trap(rep, ev["rec_id"], "T16", "runbook: replica authoritative only inside the gap",
                          "decoy:journal_mkt01_q3_b.log", [e["rec_id"]], "pull")
            self.rows[rep].append(ev)
            self.recs.append(ev)
            self.rec_by_id[ev["rec_id"]] = ev

    # ---------------------------------------------------------------- resolution (truth side)
    def _alias_index(self):
        idx = {}
        for part, rows in self.alias_rows.items():
            for row in rows:
                root = row["root"]
                ci = not root.startswith("/")
                key = root.replace("\\", "/")
                key = key.lower() if ci else key
                cur = idx.get(key)
                if cur is None or row["rev"] > cur["rev"]:
                    idx[key] = row
        self.alias_idx = idx

    def _cs_index(self):
        self.cs_idx = {}
        for vol, rows in self.cs_rows.items():
            best = {}
            for row in rows:
                k = row["prefix"].lower()
                if k not in best or row["rev"] > best[k]["rev"]:
                    best[k] = row
            self.cs_idx[vol] = sorted((k for k, v in best.items() if v["status"] == "active"), key=len, reverse=True)

    def resolve_path(self, raw, cfg):
        if raw.startswith("s3://"):
            body = raw[5:]
            bucket, _, key = body.partition("/")
            raw_bytes = bytearray()
            i = 0
            while i < len(key):
                if key[i] == "%" and i + 2 < len(key) + 1:
                    raw_bytes.append(int(key[i + 1:i + 3], 16))
                    i += 3
                else:
                    raw_bytes += key[i].encode("utf-8")
                    i += 1
            k = raw_bytes.decode("utf-8")
            return "OBJ01", unicodedata.normalize("NFC", f"/{bucket}/{k}")
        win = raw.startswith("\\\\")
        norm = raw.replace("\\", "/") if win else raw
        ci_style = not norm.startswith("/") or norm.startswith("//")
        best = None
        for j, ch in enumerate(norm):
            if ch == "/":
                cand = norm[: j + 1]
                key = cand.lower() if ci_style else cand
                if key in self.alias_idx:
                    best = (j + 1, self.alias_idx[key])
        if best is None:
            return None, None
        cut, row = best
        if row["status"] != "active":
            return None, None
        vol = row["volume"]
        if vol.startswith("serial:"):
            vol = self.serials.get(vol[7:])
            if vol not in VOL:
                return None, None
        segs = []
        for s in norm[cut:].split("/"):
            if s in ("", "."):
                continue
            if s == "..":
                if not segs:
                    return None, None
                segs.pop()
                continue
            segs.append(unicodedata.normalize("NFC", s))
        full = row["prefix"] + "/".join(segs)
        if self.vol_case(vol, cfg) == "insensitive":
            low = g_lower(full)
            for k in self.cs_idx.get(vol, []):
                if low.startswith(k):
                    return vol, (low[: len(k)] + full[len(k):]).rstrip("/")
            return vol, low.rstrip("/")
        return vol, full.rstrip("/")

    def vol_case(self, vol, cfg):
        c = VOL[vol][2]
        if c == "config":
            return cfg.get(f"vol.{vol}.case", "sensitive")
        return c

    def vol_zone(self, vol, cfg):
        return cfg.get(f"vol.{vol}.zone") or self.hosts[self.vol_host[vol]]["zone"]

    def resolve_hash(self, rec):
        h = rec.get("hash")
        if h is None or h[0] == "sentinel":
            return None
        alg, dig = h
        if alg == "sha256":
            return dig.lower()
        base = "md5" if alg in ("md5", "md5b64", "etag") else "sha1"
        part = XWALK_FOR_VOLUME[base][rec["vol"]]
        row = self.xwalk_eff[part].get(dig.lower())
        return row

    def _xwalk_index(self):
        self.xwalk_eff = {}
        for part, rows in self.xwalk_rows.items():
            best = {}
            for row in rows:
                k = row["digest"].lower()
                if part == "sha1V" and row["origin"] != "ARC01":
                    continue
                if k not in best or row["rev"] > best[k]["rev"]:
                    best[k] = row
            self.xwalk_eff[part] = {k: v["sha256"] for k, v in best.items() if v["status"] == "ok"}

    def resolve_owner(self, rec):
        o = rec.get("owner")
        if o is None or o[0] == "sentinel":
            return None
        ns, tok = o
        if ns == "sid" and tok in self.sid_history:
            tok = self.sid_history[tok]
        pid = self.tok_eff[ns].get(tok)
        if pid is None:
            return None
        final = self.resolve_pid(pid)
        if final is None:
            return None
        return self.principals[final]["account"]

    def _tok_index(self):
        self.tok_eff = {}
        for ns, rows in self.tok_rows.items():
            best = {}
            for row in rows:
                if row.get("status", "active") != "active":
                    continue
                if ns == "oldcorp" and not row["token"].startswith("OLDCORP\\"):
                    continue
                k = row["token"]
                vf = row.get("valid_from", self.prev_start - 400 * DAY)
                if k not in best or vf > best[k][0]:
                    best[k] = (vf, row["pid"])
            self.tok_eff[ns] = {k: v[1] for k, v in best.items()}

    def time_repr(self, rec, cfg):
        """Raw time text for the record's source dialect (deterministic per record)."""
        if "time_raw" in rec:
            return rec["time_raw"]
        file = rec["file"]
        t = rec["ts"] if rec["kind"] == "jrn" else rec["time"][1]
        if rec["kind"] == "jrn" and rec.get("skew"):
            t += rec["skew"]
        dial = TIME_DIALECT[file]
        h = int(hashlib.sha256(rec["rec_id"].encode()).hexdigest()[:8], 16)
        zone = self.vol_zone(rec["vol"], cfg)
        if dial == "filetime":
            out = str((t + 11644473600) * 10**7 + h % 10**7)
        elif dial == "epoch_ms":
            out = str(t * 1000 + h % 1000)
        elif dial == "epoch_ns":
            out = str(t * 10**9 + h % 10**9)
        elif dial == "epoch_s":
            out = str(t)
        elif dial == "epoch_frac":
            out = f"{t}.{h % 1000:03d}"
        elif dial == "iso_z":
            out = g_iso(t)
        elif dial == "iso_ms":
            out = g_iso(t)[:-1] + f".{h % 1000:03d}Z"
        elif dial in ("iso_offset", "iso_mixed", "rfc2822"):
            if dial == "iso_mixed" and h % 4:
                out = g_iso(t)[:-1] + f".{h % 1000:03d}Z"
            else:
                off = [-7, -5, -4, 0, 1, 2, 5.5, 9, -3.5][h % 9]
                offs = int(off * 3600)
                loc = t + offs
                sign = "+" if offs >= 0 else "-"
                hh, mm = divmod(abs(offs) // 60, 60)
                if dial == "rfc2822":
                    y, mo, d, H, M, S = g_parts(loc)
                    wd = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][g_weekday(loc // DAY)]
                    mon = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][mo - 1]
                    out = f"{wd}, {d:02d} {mon} {y} {H:02d}:{M:02d}:{S:02d} {sign}{hh:02d}{mm:02d}"
                else:
                    out = g_local_str(loc, "T") + f"{sign}{hh:02d}:{mm:02d}"
        elif dial == "local":
            out = g_local_str(self.utc_to_local(zone, t))
        elif dial == "local_dmy":
            y, mo, d, H, M, S = g_parts(self.utc_to_local(zone, t))
            out = f"{d:02d}.{mo:02d}.{y:04d} {H:02d}:{M:02d}:{S:02d}"
        elif dial == "local_tzq":
            off = self.zone_offset_at(zone, t)
            if h % 3 == 0:
                out = g_local_str(t + off) + "|null"
            else:
                out = g_local_str(t + off) + f"|{off // 900}"
        elif dial == "julian":
            y, mo, d, H, M, S = g_parts(t)
            doy = t // DAY - g_days_from_civil(y, 1, 1) + 1
            out = f"{y:04d}{doy:03d} {H:02d}{M:02d}{S:02d}"
        elif dial == "excel1900_local":
            loc = self.utc_to_local(zone, t)
            serial = (loc - g_epoch(1899, 12, 30)) / DAY
            out = f"{serial:.10f}"
        elif dial == "excel1904_utc":
            serial = (t - g_epoch(1904, 1, 1)) / DAY
            out = f"{serial:.10f}"
        else:
            raise ValueError(dial)
        rec["time_raw"] = out
        return out

    def time_parse(self, rec, raw, cfg):
        dial = TIME_DIALECT[rec["file"]]
        zone = self.vol_zone(rec["vol"], cfg)
        if raw in ("SENTINEL0", "SENTINEL60"):
            return None
        if dial == "filetime":
            return (int(raw) - 116444736000000000) // 10**7
        if dial == "epoch_ms":
            return int(raw) // 1000
        if dial == "epoch_ns":
            return int(raw) // 10**9
        if dial == "epoch_s":
            return int(raw)
        if dial == "epoch_frac":
            return int(raw.split(".")[0])
        if dial in ("iso_z", "iso_ms", "iso_offset", "iso_mixed"):
            y, mo, d = int(raw[0:4]), int(raw[5:7]), int(raw[8:10])
            H, M, S = int(raw[11:13]), int(raw[14:16]), int(raw[17:19])
            base = g_epoch(y, mo, d, H, M, S)
            tail = raw[19:]
            if tail.startswith("."):
                tail = tail[4:]
            if tail in ("Z", ""):
                return base
            sign = 1 if tail[0] == "+" else -1
            return base - sign * (int(tail[1:3]) * 3600 + int(tail[4:6]) * 60)
        if dial == "rfc2822":
            parts = raw.split()
            d, mon, y = int(parts[1]), parts[2], int(parts[3])
            mo = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"].index(mon) + 1
            H, M, S = (int(x) for x in parts[4].split(":"))
            z = parts[5]
            sign = 1 if z[0] == "+" else -1
            return g_epoch(y, mo, d, H, M, S) - sign * (int(z[1:3]) * 3600 + int(z[3:5]) * 60)
        if dial in ("local", "local_dmy", "local_tzq"):
            q = None
            if dial == "local_tzq":
                raw, q = raw.split("|")
            if dial == "local_dmy":
                d, mo, y = int(raw[0:2]), int(raw[3:5]), int(raw[6:10])
                H, M, S = int(raw[11:13]), int(raw[14:16]), int(raw[17:19])
            else:
                y, mo, d = int(raw[0:4]), int(raw[5:7]), int(raw[8:10])
                H, M, S = int(raw[11:13]), int(raw[14:16]), int(raw[17:19])
            loc = g_epoch(y, mo, d, H, M, S)
            if q not in (None, "null"):
                return loc - int(q) * 900
            return self.local_to_utc(zone, loc)
        if dial == "julian":
            y, doy = int(raw[0:4]), int(raw[4:7])
            H, M, S = int(raw[8:10]), int(raw[10:12]), int(raw[12:14])
            return (g_days_from_civil(y, 1, 1) + doy - 1) * DAY + H * 3600 + M * 60 + S
        if dial == "excel1900_local":
            secs = g_round_serial(raw)
            return self.local_to_utc(zone, g_epoch(1899, 12, 30) + secs)
        if dial == "excel1904_utc":
            return g_epoch(1904, 1, 1) + g_round_serial(raw)
        raise ValueError(dial)

    def size_value(self, rec):
        """Logical bytes of a record (None when unknown); the renderer writes size_raw."""
        s = rec.get("size")
        if s is None:
            return None
        kind = s[0]
        if kind in ("sentinel", "na"):
            return None
        if kind == "kb4":
            num = int(s[1].replace(".", ""))
            return g_half_even(num, 10)
        return s[1]

    def size_repr(self, rec):
        if "size_raw" in rec:
            return rec["size_raw"]
        s = rec.get("size")
        file = rec["file"]
        dial = SIZE_DIALECT.get(file, "int")
        if s is None:
            out = ""
        elif s[0] == "sentinel":
            out = s[1]
        elif s[0] == "na":
            out = "N/A"
        elif s[0] == "kb4":
            ip, fp = s[1].split(".")
            out = f"{int(ip):,}".replace(",", ".") + "," + fp
        elif s[0] == "unit" or dial == "unit":
            unit = UNITS[self.batch_eff_unit(rec["batch"])]
            out = g_exact_div(s[1], unit)
        elif dial == "kib":
            out = g_exact_div(s[1], 1024)
        elif dial == "kb4de":
            ip, _, fp = g_exact_div(s[1], 1000).partition(".")
            out = f"{int(ip):,}".replace(",", ".") + ("," + fp if fp else "")
        elif dial == "grouped":
            out = f"{s[1]:,}" if s[1] >= 10**6 and int(rec["rec_id"][-2:]) % 3 == 0 else str(s[1])
        elif dial == "spaced":
            sep = [" ", ".", "\u202f", "'"][int(rec["rec_id"][-1]) % 4]
            out = f"{s[1]:,}".replace(",", sep)
        elif dial == "xmlunit":
            out = str(s[1])
        else:
            out = str(s[1])
        rec["size_raw"] = out
        return out

    def batch_eff_unit(self, b):
        return self.batches[b]["unit"]

    def batch_eff_captured(self, b):
        return self.batches[b]["captured"]

    def _index_all(self):
        self._alias_index()
        self._cs_index()
        self._xwalk_index()
        self._tok_index()
        self.merge_effective_now = {}
        best = {}
        for m in self.merges:
            if m["from"] not in best or m["rev"] > best[m["from"]]["rev"]:
                best[m["from"]] = m
        for p, m in best.items():
            if m["status"] == "applied" and m["effective"] < self.win_end:
                self.merge_effective_now[p] = m["to"]
        ext_eff = {}
        for part in reversed(EXT_PRECEDENCE):
            bestx = {}
            for row in self.ext_rows[part]:
                k = row["ext"].lower()
                if k not in bestx or row["rev"] > bestx[k]["rev"]:
                    bestx[k] = row
            for k, row in bestx.items():
                fam = row.get("family_eff", row["family"])
                if row["status"] == "active" and fam != "N/A":
                    ext_eff[k] = fam
                elif k in ext_eff and row["status"] != "active":
                    pass
        self.ext_eff = ext_eff
        withdrawn = {w["seq"] for w in self.v4_withdrawals if self.ticket_ok(w["ticket"])}
        rules = [x for x in sorted(self.rules_v3, key=lambda x: x["seq"])
                 if x["status"] == "active" and x["seq"] not in withdrawn]
        rules += sorted(self.rules_overlay, key=lambda x: x["seq"])
        self.matcher = GenRules(rules)

    def family_of(self, name):
        low = name.lower()
        if low.startswith(".") and low.count(".") == 1:
            return None
        parts = low.split(".")
        for k in range(1, len(parts)):
            cand = ".".join(parts[k:])
            if cand in self.ext_eff:
                return self.ext_eff[cand]
        return None

    def errata_for(self, rec_id):
        return self.errata_eff.get(rec_id, {})

    def _errata_index(self):
        withdrawn = {w["errata_id"] for w in self.errata_withdrawals if self.ticket_ok(w["ticket"])}
        best = {}
        for part, rows in self.errata_rows.items():
            for row in rows:
                if row["errata_id"] in withdrawn or not self.ticket_ok(row["ticket"]):
                    continue
                k = (row["rec_id"], row["field"])
                if k not in best or row["rev"] > best[k]["rev"]:
                    best[k] = row
        self.errata_eff = {}
        for (rid, field), row in best.items():
            self.errata_eff.setdefault(rid, {})[field] = row["value"]

    def _void_index(self):
        best = {}
        for part, rows in self.void_rows.items():
            for row in rows:
                k = row["rec_id"]
                if k not in best or row["rev"] > best[k]["rev"]:
                    best[k] = row
        eff = {k for k, row in best.items() if row["status"] == "active" and self.ticket_ok(row["ticket"])}
        eff -= {x["rec_id"] for x in self.reinstatements if self.ticket_ok(x["ticket"])}
        # the audit letter applies to finance volumes only; an identifier of any other export has no effect
        eff |= {x for x in self.audit_exclusions if self.rec_by_id.get(x, {}).get("vol") in ("FIN01", "FIN02")}
        self.void_eff = eff

    def hold_covers(self, vol, path, ws, we):
        for h in self._hold_idx.get((vol, path.strip("/").split("/")[0]), ()):
            p = h["prefix"].rstrip("/")
            if not (path == p or path.startswith(p + "/")):
                continue
            if h["from"] < we and (h["to"] is None or h["to"] > ws):
                return True
        return False

    def _hold_index(self):
        released = {x["hold_id"] for x in self.hold_releases
                    if self.ticket_ok(x["ticket"]) and x["released"] < self.win_end}
        closed = {m for m, st in self.matters.items() if st == "closed"}
        self.holds_eff = {}
        for part, rows in self.hold_rows.items():
            for h in rows:
                if h["status"] != "active" or h["hold_id"] in released or h.get("matter") in closed:
                    continue
                self.holds_eff.setdefault(h["volume"], []).append(h)

    @staticmethod
    def under(path, prefix):
        p = prefix.rstrip("/")
        return path == p or path.startswith(p + "/")

    def subtree_flag(self, cfg, vol, path, flag):
        best = None
        for prefix, val in self._sub_idx.get((flag, vol, path.strip("/").split("/")[0]), ()):
            if self.under(path, prefix):
                if best is None or len(prefix) > len(best[0]):
                    best = (prefix, val)
        return bool(best and best[1])

    def _evaluate(self, profile):
        cfg = self.effective_config(profile)
        ws = self.parse_cfg_time(cfg["window.start"])
        we = self.parse_cfg_time(cfg["window.end"])
        bs = int(cfg["store.block_size"])
        approved_ovr = [o for o in self.scope_overrides if self.ticket_ok(o["ticket"])]
        ovr_idx = {}
        for o in approved_ovr:
            ovr_idx.setdefault((o["volume"], o["prefix"].strip("/").split("/")[0]), []).append(o)
        self._sub_idx = {}
        for key, val in cfg.items():
            if key.startswith("subtree."):
                body, _, flag = key.rpartition(".")
                v, _, prefix = body[8:].partition(":")
                self._sub_idx.setdefault((flag, v, prefix.strip("/").split("/")[0]), []).append((prefix, val))
        self._hold_idx = {}
        for vol, hs in self.holds_eff.items():
            for h in hs:
                self._hold_idx.setdefault((vol, h["prefix"].strip("/").split("/")[0]), []).append(h)
        outcome = {}
        valid_inv = []
        events = []
        for rec in self.recs:
            res = self._resolve(rec, cfg)
            reason = None
            f = rec["file"]
            cpath = res["path"]
            if rec["kind"] == "inv":
                near = ovr_idx.get((res["vol"], cpath.strip("/").split("/")[0]), ()) if cpath else ()
                if self.self_mode[f] not in ("full", "continuation"):
                    if not (cpath and any(o["file"] == f and self.under(cpath, o["prefix"]) for o in near)):
                        reason = "OUT_OF_AUTHORITY"
                elif cpath and any(o["file"] != f and self.under(cpath, o["prefix"]) for o in near):
                    reason = "SUPERSEDED_SCOPE"
            elif f == "journal_mkt01_q3_b.log":
                if not (self.mkt_gap[0] <= rec["seq"] <= self.mkt_gap[1]):
                    reason = "OUT_OF_AUTHORITY"
            if reason is None and rec["rec_id"] in self.void_eff:
                reason = "VOIDED"
            if reason is None and rec["flags"].get("na"):
                reason = "NOT_A_FILE"
            if reason is None and rec["kind"] == "jrn":
                if res["ts"] < self.snapshot[rec["vol"]]:
                    reason = "STALE_EVENT"
                elif res["ts"] >= we:
                    reason = "DEFERRED_EVENT"
            needs = {"inv": ("size", "hash", "owner"), "CREATE": ("size", "hash", "owner"),
                     "MODIFY": ("size", "hash")}.get(rec["kind"] if rec["kind"] == "inv" else rec["op"], ())
            if reason is None and (cpath is None or (rec["kind"] == "jrn" and rec["op"] == "RENAME" and res["newpath"] is None)):
                reason = "PATH_UNRESOLVED"
            if reason is None and "size" in needs and res["bytes"] is None:
                reason = "SIZE_UNKNOWN"
            if reason is None and "hash" in needs and res["sha"] is None:
                reason = "HASH_UNRESOLVED"
            if reason is None and "owner" in needs and res["owner"] is None:
                reason = "OWNER_UNRESOLVED"
            if reason:
                outcome[rec["rec_id"]] = ("X", reason)
                continue
            if rec["kind"] == "inv":
                valid_inv.append((rec, res))
            else:
                events.append((rec, res))
        state = {}
        for rec, res in valid_inv:
            key = (res["vol"], res["path"])
            cur = state.get(key)
            cand = (self.batch_eff_captured(rec["batch"]), rec["rec_id"])
            if cur is None:
                state[key] = (cand, rec, res)
            elif cand > cur[0]:
                outcome[cur[1]["rec_id"]] = ("X", "DUPLICATE_PATH")
                state[key] = (cand, rec, res)
            else:
                outcome[rec["rec_id"]] = ("X", "DUPLICATE_PATH")
        live = {}
        for key, (_c, rec, res) in state.items():
            live[key] = {"vol": res["vol"], "path": res["path"], "sha": res["sha"], "bytes": res["bytes"],
                         "mtime": res["mtime"], "owner": res["owner"], "origin": rec["rec_id"],
                         "file_id": self.hardlink_id(rec, res), "nlink": rec["nlink"]}
        deleted = {}
        events.sort(key=lambda e: (e[1]["vol"], e[0]["seq"]))
        for rec, res in events:
            key = (res["vol"], res["path"])
            op = rec["op"]
            if op == "CREATE":
                if key in live:
                    outcome[live[key]["origin"]] = ("X", "REPLACED")
                live[key] = {"vol": res["vol"], "path": res["path"], "sha": res["sha"], "bytes": res["bytes"],
                             "mtime": res["ts"], "owner": res["owner"], "origin": rec["rec_id"],
                             "file_id": None, "nlink": 1}
            elif op == "MODIFY":
                if key not in live:
                    outcome[rec["rec_id"]] = ("X", "ORPHAN_EVENT")
                    continue
                e = live[key]
                e["sha"], e["bytes"], e["mtime"] = res["sha"], res["bytes"], res["ts"]
            elif op == "RENAME":
                nkey = (res["vol"], res["newpath"])
                if key not in live or nkey == key:
                    outcome[rec["rec_id"]] = ("X", "ORPHAN_EVENT")
                    continue
                e = live.pop(key)
                if nkey in live:
                    outcome[live[nkey]["origin"]] = ("X", "REPLACED")
                e["path"] = res["newpath"]
                live[nkey] = e
            elif op == "DELETE":
                if key not in live:
                    outcome[rec["rec_id"]] = ("X", "ORPHAN_EVENT")
                    continue
                e = live.pop(key)
                outcome[e["origin"]] = ("X", "DELETED")
                deleted.setdefault(key, []).append(e)
            elif op == "RESTORE":
                if key in live or not deleted.get(key):
                    outcome[rec["rec_id"]] = ("X", "ORPHAN_EVENT")
                    continue
                e = deleted[key].pop()
                outcome.pop(e["origin"], None)
                live[key] = e
        groups = {}
        for key, e in live.items():
            if e["file_id"] and e["nlink"] > 1:
                groups.setdefault((e["vol"], e["file_id"]), []).append(key)
        for gkeys in groups.values():
            if len(gkeys) < 2:
                continue
            gkeys.sort(key=lambda k: k[1])
            for k in gkeys[1:]:
                outcome[live[k]["origin"]] = ("X", "HARDLINK_ALIAS")
                del live[k]
        entries = []
        for key in sorted(live):
            e = live[key]
            name = e["path"].rsplit("/", 1)[-1]
            ci = self.vol_case(e["vol"], cfg) == "insensitive"
            cls = self.matcher.classify(e["vol"], e["path"], self.family_of(name), ci)
            max_age, arch = self.classes[cls]
            age = (we - e["mtime"]) // DAY
            held = self.hold_covers(e["vol"], e["path"], ws, we)
            if (cfg.get("purge.enabled") and max_age is not None and e["vol"] not in NO_PURGE_VOLUMES and age > max_age and not held
                    and not self.subtree_flag(cfg, e["vol"], e["path"], "purge_exempt")):
                outcome[e["origin"]] = ("X", "PURGED")
                continue
            action = "keep"
            if arch is not None and age >= arch and not self.subtree_flag(cfg, e["vol"], e["path"], "archive_exempt"):
                action = "archive"
            e = dict(e)
            e["class"] = cls
            e["action"] = action
            entries.append(e)
        return {"cfg": cfg, "entries": entries, "outcome": outcome, "bs": bs, "we": we, "ws": ws}

    def hardlink_id(self, rec, res):
        if rec["file"] == "arc01_tape_catalog.txt":
            return self.ltfs_fid.get(res["path"])
        return rec["file_id"]

    @staticmethod
    def parse_cfg_time(s):
        return g_epoch(int(s[0:4]), int(s[5:7]), int(s[8:10]), int(s[11:13]), int(s[14:16]), int(s[17:19]))

    def _resolve(self, rec, cfg):
        if "raw_path" not in rec:
            rec["raw_path"] = self.raw_path(rec)
        vol, cpath = self.resolve_path(rec["raw_path"], cfg)
        if vol is not None and vol != rec["vol"]:
            vol, cpath = None, None
        res = {"vol": vol, "path": cpath, "newpath": None}
        if rec["kind"] == "jrn" and rec["op"] == "RENAME":
            if "raw_newpath" not in rec:
                rec["raw_newpath"] = self.raw_path({"top": rec["newtop"], "rest": rec["newrest"], "vol": rec["vol"],
                                                    "root_variant": rec.get("newroot_variant")})
            v2, p2 = self.resolve_path(rec["raw_newpath"], cfg)
            res["newpath"] = p2 if v2 == vol else None
        err = self.errata_for(rec["rec_id"])
        res["bytes"] = int(err["bytes"]) if "bytes" in err else self.size_value(rec)
        res["sha"] = err["sha256"] if "sha256" in err else self.resolve_hash(rec)
        res["owner"] = err["owner"] if "owner" in err else self.resolve_owner(rec)
        if rec["kind"] == "inv":
            raw = self.time_repr(rec, cfg)
            t = self.time_parse(rec, raw, cfg)
            if t is None:
                t = self.batch_eff_captured(rec["batch"])
            if "mtime" in err:
                t = self.parse_cfg_time(err["mtime"])
            res["mtime"] = t
        else:
            raw = self.time_repr(rec, cfg)
            t = self.time_parse(rec, raw, cfg)
            for inc in self.inc_by_host.get(rec.get("host"), ()):
                if inc["from"] <= t < inc["to"] and rec["file"] in HOST_JOURNALS:
                    t -= inc["skew"]
                    break
            res["ts"] = t
        return res

    def _refs_init(self):
        self.cs_rows = {"ENG02": [], "LEG01": []}
        self.v4_withdrawals = []
        self.errata_rows = {p: [] for p in ERRATA_FILES}
        self.errata_withdrawals = []
        self.void_rows = {p: [] for p in VOID_FILES}
        self.reinstatements = []
        self.audit_exclusions = []
        self.hold_rows = {p: [] for p in HOLD_FILES}
        self.hold_releases = []
        self.matters = {}
        self.incidents = []
        self.incidents_eff = []
        self.ltfs_fid = {}
        self.store_rows = {p: [] for p in STORE_FILES}
        self.batch_conflicts = []
        self.ext_corrections = []
        self.hold_seq = 0
        self.err_seq = 0
        self.void_seq = 0
        for vol in ("ENG02", "LEG01"):
            tops = self.tops[vol]
            for i in range(self.N):
                t = tops[i % len(tops)]["prefix"]
                self.cs_rows[vol].append({"prefix": f"{t}wsl{i:05d}/", "status": "active", "rev": 1,
                                          "vol": vol, "ticket": self.old_ticket()})

    def add_void(self, rec_id, part=None, approved=True, status="active", rev=1):
        rev += max([v["rev"] for rows in self.void_rows.values() for v in rows if v["rec_id"] == rec_id] or [0])
        self.void_seq += 1
        part = part or self.rng.choice(list(VOID_FILES))
        row = {"void_id": f"VD-{self.void_seq:06d}", "rec_id": rec_id, "ticket": self.ticket(approved),
               "status": status, "rev": rev, "part": part, "reason": self.rng.choice(
                   ["duplicate capture", "export fault", "legal instruction", "test row", "operator error"])}
        self.void_rows[part].append(row)
        self.last_row = row
        return row

    def add_errata(self, rec_id, field, value, rev=1, approved=True, part=None, kind="plain"):
        key = (rec_id, field)
        base = self.__dict__.setdefault("_err_base", {})
        if key not in base or getattr(self, "_err_call", None) != (key, self._err_depth()):
            base[key] = max([x["rev"] for rows in self.errata_rows.values() for x in rows
                             if (x["rec_id"], x["field"]) == key] + [x.get("rev", 0) for x in self.d15_rows
                                                                     if (x["rec_id"], x["field"]) == key] or [0])
            self._err_call = (key, self._err_depth())
        rev += base[key]
        self.err_seq += 1
        part = part or self.rng.choice(list(ERRATA_FILES))
        row = {"errata_id": f"ER-{self.err_seq:06d}", "rec_id": rec_id, "field": field, "value": value,
               "rev": rev, "ticket": self.ticket(approved, kind=kind), "part": part}
        self.errata_rows[part].append(row)
        self.last_row = row
        return row

    def _err_depth(self):
        return self.trap_seq

    def add_hold(self, vol, prefix, frm, to, part=None, status="active", matter=None):
        self.hold_seq += 1
        part = part or self.rng.choice(list(HOLD_FILES))
        if matter is None:
            matter = f"M-{self.rng.randrange(10**5):05d}"
        self.matters.setdefault(matter, "open")
        row = {"hold_id": f"LH-{self.hold_seq:06d}", "volume": vol, "prefix": prefix, "from": frm, "to": to,
               "status": status, "part": part, "matter": matter}
        self.hold_rows[part].append(row)
        self.last_row = row
        return row

    def _schedule(self, nrows, decoy):
        r = self.rng
        bands = max(1, -(-nrows // 500))
        pos = []
        for b in range(bands):
            lo = b * 500
            hi = min(nrows, lo + 500)
            pos.append(r.randrange(lo, hi))
        target = r.randint(26, 32) if decoy else r.randint(12, 18)
        target = max(target, bands)
        if not decoy:
            target = min(target, 20)
        while len(pos) < target:
            pos.append(r.randrange(nrows))
        return sorted(pos)

    def _plant(self):
        from_kinds = TRAP_KINDS
        for file in FILE_NAMES:
            kinds = from_kinds.get(file)
            if not kinds:
                continue
            rows = self._trap_rows(file)
            if not rows:
                continue
            slots = self._schedule(max(len(rows), self.expected_rows(file)), file in DECOYS)
            used_fams = []
            kinds = list(kinds)
            self.rng.shuffle(kinds)
            for i, p0 in enumerate(slots):
              for attempt in range(6):
                p = (p0 + attempt * 37) % len(rows)
                order = kinds[i % len(kinds):] + kinds[: i % len(kinds)]
                done = False
                for kname in order:
                    fn = getattr(self, "k_" + kname)
                    self.last_row = None
                    got = fn(file, rows[min(p, len(rows) - 1)], p)
                    if got:
                        fam, rule, recs = got
                        loc = rows[min(p, len(rows) - 1)]
                        locator = loc.get("rec_id") if isinstance(loc, dict) and "rec_id" in loc else f"row {p + 1}"
                        test = f"decoy:{file}" if file in DECOYS else f"family:{fam}"
                        self.trap(file, locator, fam, rule, test, recs)
                        for rid in recs:
                            if rid in self.rec_by_id:
                                self.rec_by_id[rid]["tags"].add(fam)
                                if file in DECOYS:
                                    self.rec_by_id[rid]["tags"].add(f"D:{file}")
                        used_fams.append(fam)
                        obj = self.last_row if self.last_row is not None else rows[min(p, len(rows) - 1)]
                        self.trap_objs.setdefault(file, []).append(obj)
                        done = True
                        break
                if done:
                    break

    def expected_rows(self, file):
        if file in ("inv_hr01_q3.xlsx", "inv_mkt01_supplement.xlsx", "alias_remap_sharepoint.xlsx",
                    "ext_families_b.xlsx", "holds_matter_index.xlsx", "authority_matrix.xlsx", "principal_sid_map.xlsx"):
            return 2 * self.N
        return self.N

    def _trap_rows(self, file):
        role = FILE_ROLE[file]
        if file in INVENTORY_FILES or file in JOURNAL_FILES:
            return self.rows[file]
        return self.ref_rows_for(file)

    # consumers: an in-scope export row that depends on a trapped reference row
    def consumer(self, vol, top=None, part=None, **kw):
        cands = [f for f, v in INVENTORY_FILES.items() if v == vol and f not in DECOYS
                 and (part is None or part in FILE_PARTS[f])]
        if top is not None:
            cands = [f for f in cands if top["part"] in FILE_PARTS[f]] or cands
        cands = [f for f in cands if f not in ("inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx")]
        if not cands:
            return None
        file = self.rng.choice(sorted(cands))
        return self.mk_rec(file, vol, top=top, **kw)

    def top_of(self, alias_row):
        for t in self.tops[alias_row["volume"] if alias_row["volume"] in VOL else self.alias_vol(alias_row)]:
            if t["row"] is alias_row:
                return t
        return None

    def alias_vol(self, row):
        v = row["volume"]
        if v.startswith("serial:"):
            return self.serials.get(v[7:], "RETIRED")
        return v

    # ---- reference-table trap kinds -------------------------------------------------
    def k_alias_rev(self, file, row, p):
        vol = self.alias_vol(row)
        if vol not in VOL or row["rev"] != 1 or row.get("trapped"):
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        new = dict(row, rev=2, prefix=row["prefix"].rstrip("/") + "-r2/", alias_id=row["alias_id"] + "b")
        self.alias_rows[row["part"]].insert(p + 1, new)
        top["prefix"] = new["prefix"]
        top["row"] = new
        c = self.consumer(vol, top=top)
        return ("T7", "ECS 5.2 highest alias revision wins", [c["rec_id"]]) if c else None

    def k_alias_retired(self, file, row, p):
        vol = self.alias_vol(row)
        if vol not in VOL or row.get("trapped"):
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        c = self.consumer(vol, top=top)
        if not c:
            return None
        new = dict(row, rev=row["rev"] + 1, status="retired", alias_id=row["alias_id"] + "x")
        self.alias_rows[row["part"]].insert(p + 1, new)
        top["state"] = "retired"
        self._tops_cache = {}
        return ("T6", "ECS 5.2 retired alias root resolves nothing", [c["rec_id"]])

    def k_alias_case(self, file, row, p):
        vol = self.alias_vol(row)
        if vol not in VOL or row.get("trapped") or row["root"].startswith("/"):
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        c = self.consumer(vol, top=top)
        if not c:
            return None
        c["root_variant"] = row["root"].upper() if c["rec_id"][-1] in "02468" else row["root"].swapcase()
        return ("T1", "ECS 5.2 UNC/SMB roots compare case-insensitively", [c["rec_id"]])

    def k_alias_nest(self, file, row, p):
        vol = self.alias_vol(row)
        if vol not in VOL or row.get("trapped"):
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        sep = "\\" if row["root"].startswith("\\\\") else "/"
        nested_root = row["root"] + "cad" + sep
        new = dict(row, root=nested_root, prefix=f"/{VOL[vol][3]}-cad-{row['alias_id'][-5:]}/",
                   alias_id=row["alias_id"] + "n")
        self.alias_rows[row["part"]].insert(p + 1, new)
        ntop = {"root": nested_root, "prefix": new["prefix"], "part": row["part"], "state": "nested", "row": new}
        c1 = self.consumer(vol, top=ntop, rest=self._sub() + "/" + self._name(vol))
        c2 = self.consumer(vol, top=top, rest="cadence/" + self._name(vol))
        if not c1 or not c2:
            return None
        return ("T11", "ECS 5.2 longest alias root on a separator boundary", [c1["rec_id"], c2["rec_id"]])

    def k_alias_serial(self, file, row, p):
        if not row["volume"].startswith("serial:") or row.get("trapped"):
            return None
        vol = self.alias_vol(row)
        if vol not in VOL:
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        c = self.consumer(vol, top=top)
        if not c:
            return None
        dead = next(s for s, v in sorted(self.serials.items()) if v == "RETIRED")
        new = dict(row, rev=row["rev"] + 1, volume=f"serial:{dead}", alias_id=row["alias_id"] + "s")
        self.alias_rows[row["part"]].insert(p + 1, new)
        top["state"] = "dead"
        self._tops_cache = {}
        return ("T13", "ECS 5.2 volume serials resolve through the CMDB crosswalk; retired serials resolve nothing",
                [c["rec_id"]])

    def k_ext_rev(self, file, row, p):
        if row.get("trapped") or row["part"] == "E":
            return None
        row["trapped"] = True
        new = dict(row, rev=2, family=self.rng.choice([f for f in FAMILY_CLASS_RULES if f != row["family"]]))
        self.ext_rows[row["part"]].insert(p + 1, new)
        vol = self.rng.choice(["ENG01", "FIN01", "OPS01", "LAB01"])
        c = self.consumer(vol, rest=self._sub() + "/" + self._name(vol, ext=row["ext"]),
                          mtime=self.win_end - 900 * DAY)
        return ("T7", "ECS 7.2 highest family-table revision wins", [c["rec_id"]]) if c else None

    def k_ext_na(self, file, row, p):
        if row.get("trapped") or row["part"] == "E":
            return None
        row["trapped"] = True
        nxt = EXT_PRECEDENCE[EXT_PRECEDENCE.index(row["part"]) + 1]
        if nxt == "B":
            nxt = "C"
        row2 = {"ext": row["ext"], "family": "TMP", "rev": 1, "status": "active", "part": nxt}
        self.ext_rows[nxt].append(row2)
        row["family"] = "N/A"
        vol = self.rng.choice(["ENG02", "FIN02", "OPS01", "HR01"])
        c = self.consumer(vol, rest="src/" + self._name(vol, ext=row["ext"]), mtime=self.win_end - 60 * DAY)
        return ("T5", "ECS 7.2 family N/A defers to the next table", [c["rec_id"]]) if c else None

    def k_ext_retired(self, file, row, p):
        if row.get("trapped") or row["part"] == "E":
            return None
        row["trapped"] = True
        row2 = {"ext": row["ext"], "family": "LOG", "rev": 1, "status": "active", "part": "E"}
        self.ext_rows["E"].append(row2)
        self.ext_rows[row["part"]].insert(p + 1, dict(row, rev=row["rev"] + 1, status="retired"))
        vol = self.rng.choice(["ENG01", "OPS01", "LAB01"])
        c = self.consumer(vol, rest="data/" + self._name(vol, ext=row["ext"]), mtime=self.win_end - 400 * DAY)
        return ("T6", "ECS 7.2 retired family rows are skipped", [c["rec_id"]]) if c else None

    def k_ext_case(self, file, row, p):
        if row.get("trapped") or row["part"] == "E":
            return None
        row["trapped"] = True
        row["ext"] = row["ext"].upper()
        vol = self.rng.choice(["FIN01", "OPS01", "OBJ01", "HR01"])
        c = self.consumer(vol, rest="tmp/" + self._name(vol, ext=row["ext"].lower()), mtime=self.win_end - 45 * DAY)
        return ("T1", "ECS 7.2 extensions compare in lowercase", [c["rec_id"]]) if c else None

    def k_tok_dup(self, file, row, p, ns=None):
        if row.get("trapped") or "pid" not in row:
            return None
        ns = ns or self.file_ns(file)
        if ns is None:
            return None
        row["trapped"] = True
        other = self.rng.choice(self.pids)
        row["valid_from"] = self.win_start - 400 * DAY
        new = {"token": row["token"], "pid": other, "valid_from": self.next_valid_from(ns, row["token"]), **{
            k: v for k, v in row.items() if k not in ("token", "pid", "valid_from", "trapped")}}
        self.tok_rows[ns].insert(p + 1, new)
        vol = self.ns_volume(ns)
        c = self.consumer(vol, pid=row["pid"], ns=ns)
        if not c:
            return None
        c["owner"] = (ns, row["token"])
        return ("T7", "ECS 5.4 latest valid_from wins for a repeated token", [c["rec_id"]])

    def k_tok_revoked(self, file, row, p, ns=None):
        if row.get("trapped") or "pid" not in row:
            return None
        ns = ns or self.file_ns(file)
        if ns is None:
            return None
        row["trapped"] = True
        row["status"] = "revoked"
        vol = self.ns_volume(ns)
        c = self.consumer(vol, pid=row["pid"], ns=ns)
        if not c:
            return None
        c["owner"] = (ns, row["token"])
        return ("T6", "ECS 5.4 revoked token rows are ignored", [c["rec_id"]])

    def k_tok_merge(self, file, row, p, ns=None):
        if row.get("trapped") or "pid" not in row:
            return None
        ns = ns or self.file_ns(file)
        if ns is None:
            return None
        row["trapped"] = True
        a = row["pid"]
        b, c2 = self.rng.sample([x for x in self.pids if x != a], 2)
        part = self.rng.choice("AB")
        for frm, to, eff in ((a, b, self.win_start - 200 * DAY), (b, c2, self.win_end - DAY)):
            self.add_merge(frm, to, eff, part, "T")
            part = "B" if part == "A" else "A"
        vol = self.ns_volume(ns)
        c = self.consumer(vol, pid=a, ns=ns)
        if not c:
            return None
        c["owner"] = (ns, row["token"])
        return ("T13", "ECS 5.5 follow the merge chain to its end", [c["rec_id"]])

    def k_tok_stale(self, file, row, p, ns=None):
        if row.get("trapped") or "pid" not in row:
            return None
        ns = ns or self.file_ns(file)
        if ns is None:
            return None
        row["trapped"] = True
        row["pid"] = self.rng.choice(self.dir_only_pids)
        vol = self.ns_volume(ns)
        c = self.consumer(vol, ns=ns)
        if not c:
            return None
        c["owner"] = (ns, row["token"])
        return ("T13", "ECS 5.4 principal ids must exist in the principal register", [c["rec_id"]])

    def k_tok_var(self, file, row, p, ns=None):
        if row.get("trapped") or "pid" not in row:
            return None
        ns = ns or self.file_ns(file)
        if ns is None:
            return None
        row["trapped"] = True
        row["render_variant"] = True
        vol = self.ns_volume(ns)
        c = self.consumer(vol, pid=row["pid"], ns=ns)
        if not c:
            return None
        c["owner"] = (ns, row["token"])
        c["tok_variant"] = True
        return ("T1", "ECS 5.3 token normalisation", [c["rec_id"]])

    def next_valid_from(self, ns, token):
        vals = [x.get("valid_from", self.prev_start - 400 * DAY) for x in self.tok_rows[ns] if x["token"] == token]
        return max(vals + [self.win_start - 60 * DAY]) + DAY

    def file_ns(self, file):
        for ns, f in TOKEN_FILES.items():
            if f == file:
                return ns
        return None

    def ns_volume(self, ns):
        for f, spec in SOURCE_OWNER.items():
            if f in INVENTORY_FILES and f not in DECOYS and ns in spec.split("|") and f not in (
                    "inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx"):
                return INVENTORY_FILES[f]
        return "ENG01"

    def k_merge_revert(self, file, row, p):
        if row.get("trapped") or "from" not in row or row["from"] not in self.merge_effective:
            return None
        row["trapped"] = True
        a = row["from"]
        m = self.add_merge(a, row["to"], row["effective"], "B" if row["part"] == "A" else "A", "R")
        m["status"] = "reverted"
        ns = "uid"
        toks = self.tok_by_pid[ns].get(a) or []
        if not toks:
            ns = "email"
            toks = self.tok_by_pid[ns].get(a) or []
        if not toks:
            return None
        c = self.consumer(self.ns_volume(ns), pid=a, ns=ns)
        return ("T7", "ECS 5.5 latest merge revision wins; reverted merges do not apply", [c["rec_id"]]) if c else None

    def k_merge_boundary(self, file, row, p):
        if row.get("trapped") or "from" not in row:
            return None
        row["trapped"] = True
        a = row["from"]
        row["effective"] = self.win_end
        ns = "email"
        toks = self.tok_by_pid[ns].get(a) or []
        if not toks:
            ns = "uid"
            toks = self.tok_by_pid[ns].get(a) or []
        if not toks:
            return None
        c = self.consumer(self.ns_volume(ns), pid=a, ns=ns)
        return ("T11", "ECS 5.5 merges apply only when effective strictly before window.end", [c["rec_id"]]) if c else None

    def k_alias_retire_inplace(self, file, row, p):
        vol = self.alias_vol(row)
        if vol not in VOL or row.get("trapped"):
            return None
        top = self.top_of(row)
        if top is None:
            return None
        row["trapped"] = True
        c = self.consumer(vol, top=top)
        if not c:
            return None
        row["status"] = "retired"
        top["state"] = "retired"
        self._tops_cache = {}
        return ("T6", "ECS 5.2 retired alias root resolves nothing", [c["rec_id"]])

    def k_csdir(self, file, row, p):
        if row.get("trapped") or "prefix" not in row or "vol" not in row:
            return None
        row["trapped"] = True
        vol = row["vol"]
        top = next((t for t in self.tops[vol] if row["prefix"].startswith(t["prefix"]) and t["state"] == "ok"), None)
        if top is None:
            return None
        sub = row["prefix"][len(top["prefix"]):]
        nm = self._name(vol)
        a = self.consumer(vol, top=top, rest=sub + "Make" + nm)
        b = self.consumer(vol, top=top, rest=sub + "make" + nm)
        if not a or not b:
            return None
        return ("T1", "ECS 5.3 case-sensitive subtrees keep case below the listed prefix", [a["rec_id"], b["rec_id"]])

    def k_csdir_retired(self, file, row, p):
        if row.get("trapped") or "prefix" not in row:
            return None
        row["trapped"] = True
        row["status"] = "retired"
        vol = row["vol"]
        top = next((t for t in self.tops[vol] if row["prefix"].startswith(t["prefix"]) and t["state"] == "ok"), None)
        if top is None:
            return None
        sub = row["prefix"][len(top["prefix"]):]
        nm = self._name(vol)
        a = self.consumer(vol, top=top, rest=sub + "Data" + nm)
        b = self.consumer(vol, top=top, rest=sub + "DATA" + nm)
        if not a or not b:
            return None
        return ("T6", "ECS 5.3 retired case-sensitive entries no longer apply", [a["rec_id"], b["rec_id"]])

    def k_batch_unit(self, file, row, p):
        if row.get("trapped") or "unit" not in row:
            return None
        row["trapped"] = True
        row["unit"] = self.rng.choice(["MiB", "blk4096", "KB"])
        self.batches[row["batch"]]["unit"] = row["unit"]
        src = self.rng.choice(sorted(f for f in BATCH_UNIT_SOURCES if f not in DECOYS and f not in (
            "inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx")))
        c = self.mk_rec(src, INVENTORY_FILES[src], batch=row["batch"])
        return ("T2", "ECS 6.1 size unit comes from the export batch", [c["rec_id"]])

    def k_batch_conflict(self, file, row, p):
        if row.get("trapped") or "unit" not in row or row["part"] == "D":
            return None
        row["trapped"] = True
        newu = self.rng.choice([u for u in UNITS if u != row["unit"]])
        self.batch_conflicts.append({"batch": row["batch"], "unit": newu, "captured": row["captured"], "part": "D"})
        self.batches[row["batch"]]["unit"] = newu
        src = self.rng.choice(sorted(f for f in BATCH_UNIT_SOURCES if f not in DECOYS and f not in (
            "inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx")))
        c = self.mk_rec(src, INVENTORY_FILES[src], batch=row["batch"])
        return ("T14", "units-bulletin.pdf corrections override the batch registers", [c["rec_id"]])

    def k_batch_capture(self, file, row, p):
        if row.get("trapped") or "unit" not in row:
            return None
        row["trapped"] = True
        vol = self.rng.choice(["ENG01", "OPS01", "FIN02", "LAB01"])
        a = self.consumer(vol)
        if not a:
            return None
        b = self.consumer(vol, top=a["top"], rest=a["rest"], batch=row["batch"])
        if not b:
            return None
        self.batches[row["batch"]]["captured"] = self.batch_eff_captured(a["batch"]) + 1
        row["captured"] = self.batches[row["batch"]]["captured"]
        return ("T11", "ECS 6.4 duplicate canonical paths: the later batch capture wins", [a["rec_id"], b["rec_id"]])

    def k_xwalk_conflict(self, file, row, p):
        if row.get("trapped") or "digest" not in row:
            return None
        mypart = {v: k for k, v in XWALK_FILE.items()}[file]
        others = [q for q in XWALK_FILE if q != mypart and q[:3] == mypart[:3] and q != "sha1V"]
        if not others:
            return None
        row["trapped"] = True
        q = self.rng.choice(others)
        self.xwalk_rows[q].append(dict(row, sha256=g_hex(self.rng, 256), part=q, origin="other"))
        recs = [x["rec_id"] for x in self.recs if x.get("hash") and x["hash"][1] == row["digest"]][:3]
        return ("T13", "ECS 6.2 the crosswalk partition assigned to the volume wins", recs) if recs else None

    def k_xwalk_revoked(self, file, row, p):
        if row.get("trapped") or "digest" not in row or file == "hash_index_master.parquet":
            return None
        recs = [x["rec_id"] for x in self.recs if x.get("hash") and x["hash"][1] == row["digest"]
                and x["file"] not in DECOYS][:3]
        if not recs:
            return None
        row["trapped"] = True
        self.xwalk_rows[{v: k for k, v in XWALK_FILE.items()}[file]].append(dict(row, rev=2, status="revoked"))
        return ("T6", "ECS 6.2 revoked crosswalk rows are ignored", recs)

    def k_xwalk_case(self, file, row, p):
        if row.get("trapped") or "digest" not in row:
            return None
        recs = [x["rec_id"] for x in self.recs if x.get("hash") and x["hash"][1] == row["digest"]][:3]
        if not recs:
            return None
        row["trapped"] = True
        row["render_upper"] = True
        return ("T1", "ECS 6.2 digests compare in lowercase hex", recs)

    def k_hold_window(self, file, row, p):
        part = {v: k for k, v in HOLD_FILES.items()}.get(file)
        if part is None:
            return None
        vol = self.rng.choice(["ENG01", "LEG01", "FIN02", "OPS01", "LAB01"])
        c = self.consumer(vol, rest="scratch/" + self._name(vol, ext="tmp"), mtime=self.win_end - 400 * DAY)
        if not c:
            return None
        pre = c["top"]["prefix"].rstrip("/")
        mode = self.rng.randrange(3)
        frm, to = (self.win_start - 90 * DAY, self.win_start) if mode == 0 else (
            (self.win_end, None) if mode == 1 else (self.win_end - DAY, self.win_end + 30 * DAY))
        self.add_hold(c["vol"], pre, frm, to, part=part)
        return ("T11", "ECS 7.5 a hold applies when its window overlaps [window.start, window.end)", [c["rec_id"]])

    def k_hold_prefix(self, file, row, p):
        part = {v: k for k, v in HOLD_FILES.items()}.get(file)
        if part is None:
            return None
        vol = self.rng.choice(["ENG01", "FIN01", "OPS01", "HR01"])
        c = self.consumer(vol, rest="scratch/" + self._name(vol, ext="tmp"), mtime=self.win_end - 400 * DAY)
        if not c:
            return None
        pre = c["top"]["prefix"] + "scratc"
        self.add_hold(c["vol"], pre, self.win_start - 10 * DAY, None, part=part)
        return ("T11", "ECS 7.5 hold prefixes match whole path segments", [c["rec_id"]])

    def k_hold_release(self, file, row, p):
        vol = self.rng.choice(["ENG02", "LEG01", "FIN02"])
        c = self.consumer(vol, rest="scratch/" + self._name(vol, ext="bak"), mtime=self.win_end - 700 * DAY)
        if not c:
            return None
        h = self.add_hold(c["vol"], c["top"]["prefix"].rstrip("/"), self.win_start - 50 * DAY, None)
        kind = self.rng.choice(["plain", "late", "reject"])
        t = self.ticket(approved=kind != "reject", kind="late" if kind == "late" else "plain")
        self.hold_releases.append({"hold_id": h["hold_id"], "released": self.win_end - 5 * DAY, "ticket": t})
        return ("T6", "legal-hold-memo-q3.docx releases end a hold when their ticket is approved", [c["rec_id"]])

    def k_hold_matter(self, file, row, p):
        vol = self.rng.choice(["ENG01", "OPS01", "LAB01"])
        c = self.consumer(vol, rest="tmp/" + self._name(vol, ext="tmp"), mtime=self.win_end - 300 * DAY)
        if not c:
            return None
        m = f"M-{self.rng.randrange(10**5, 2 * 10**5)}"
        self.add_hold(c["vol"], c["top"]["prefix"].rstrip("/"), self.win_start - 9 * DAY, None, part="B", matter=m)
        self.matters[m] = "closed"
        return ("T13", "holds_matter_index.xlsx: holds of closed matters are inactive", [c["rec_id"]])

    def k_ticket_rev(self, file, row, p):
        vol = self.rng.choice(["ENG01", "FIN02", "LEG01"])
        c = self.consumer(vol)
        if not c:
            return None
        kind = self.rng.choice(["revoked", "reinstated", "sentinel", "late"])
        t = self.ticket(kind=kind)
        self.void_seq += 1
        vrev = 1 + max([v["rev"] for rows in self.void_rows.values() for v in rows if v["rec_id"] == c["rec_id"]] or [0])
        self.void_rows["A"].append({"void_id": f"VD-{self.void_seq:06d}", "rec_id": c["rec_id"], "ticket": t,
                                    "status": "active", "rev": vrev, "part": "A", "reason": "operator error"})
        fam = {"revoked": "T7", "reinstated": "T7", "sentinel": "T5", "late": "T11"}[kind]
        self.last_row = self.last_ticket_row if file == "change_tickets.csv" else self.void_rows["A"][-1]
        return (fam, "ECS 2.4 ticket state is its highest revision, decided strictly before window.end", [c["rec_id"]])

    def k_void(self, file, row, p):
        part = {v: k for k, v in VOID_FILES.items()}.get(file)
        vol = self.rng.choice([v[0] for v in VOLUMES if v[0] != "OBJ01"])
        c = self.consumer(vol)
        if not c:
            return None
        mode = self.rng.randrange(3)
        if mode == 0:
            self.add_void(c["rec_id"], part=part)
            return ("T6", "ECS 3.4 active approved voids remove the record", [c["rec_id"]])
        if mode == 1:
            self.add_void(c["rec_id"], part=part)
            self.add_void(c["rec_id"], part="B" if part == "A" else "A", status="cancelled", rev=2)
            return ("T7", "ECS 3.4 the highest void revision decides", [c["rec_id"]])
        self.add_void(c["rec_id"], part=part, approved=False)
        return ("T6", "ECS 3.4 voids need an approved ticket", [c["rec_id"]])

    def k_errata(self, file, row, p):
        part = {v: k for k, v in ERRATA_FILES.items()}.get(file)
        vol = self.rng.choice([v[0] for v in VOLUMES])
        c = self.consumer(vol)
        if not c:
            return None
        field = self.rng.choice(["bytes", "mtime", "owner", "sha256"])
        good = {"bytes": str(self.rng.randrange(1, 10**7)), "mtime": g_iso(self.win_start - self.rng.randrange(DAY, 99 * DAY)),
                "owner": self.principals[self.rng.choice(self.pids)]["account"], "sha256": g_hex(self.rng, 256)}[field]
        bad = {"bytes": "0", "mtime": g_iso(self.win_end + DAY), "owner": "unknown", "sha256": "0" * 64}[field]
        mode = self.rng.randrange(3)
        if mode == 0:
            self.add_errata(c["rec_id"], field, bad, rev=1, part=part)
            self.add_errata(c["rec_id"], field, good, rev=2, part=part)
        elif mode == 1:
            self.add_errata(c["rec_id"], field, good, rev=1, part=part)
            self.add_errata(c["rec_id"], field, bad, rev=2, approved=False, part=part)
        else:
            self.add_errata(c["rec_id"], field, good, rev=3, part=part)
            self.add_errata(c["rec_id"], field, bad, rev=2, part=self.rng.choice(list(ERRATA_FILES)))
        return ("T7", "ECS 3.5 highest approved errata revision per record and field", [c["rec_id"]])

    def k_errata_sentinel(self, file, row, p):
        part = {v: k for k, v in ERRATA_FILES.items()}.get(file)
        src = self.rng.choice(["inv_eng01_q3.csv", "inv_lab01_q3.jsonl", "inv_mkt01_q3.jsonl"])
        c = self.mk_rec(src, INVENTORY_FILES[src])
        c["size"] = ("sentinel", {"inv_eng01_q3.csv": "-1"}.get(src, ""))
        self.add_errata(c["rec_id"], "bytes", str(c["content"]["size"]), part=part)
        return ("T5", "ECS 6.1 unknown sizes may be supplied by errata", [c["rec_id"]])

    # ---- export-row trap kinds ------------------------------------------------------
    def _ok_rec(self, rec):
        return rec.get("kind") == "inv" and not rec.get("trapped") and "rest" in rec

    def k_casedup(self, file, rec, p, inplace=False):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        rest = rec["rest"]
        head, _, nm = rest.rpartition("/")
        variant = head + "/" + (nm.swapcase() if nm.swapcase() != nm else nm.upper() + "X")
        if inplace:
            rows = self.rows[file]
            other = rows[(p + 7) % len(rows)]
            if other.get("trapped") or other.get("kind") != "inv":
                return None
            other["trapped"] = True
            other["top"], other["rest"], other["root"] = rec["top"], variant, rec["top"]["root"]
            return ("T1", "ECS 5.3 case folding on case-insensitive volumes", [rec["rec_id"], other["rec_id"]])
        twin = self.mk_rec(file, rec["vol"], top=rec["top"], rest=variant, insert=p + 1)
        return ("T1", "ECS 5.3 case folding on case-insensitive volumes; ECS 6.4 duplicates",
                [rec["rec_id"], twin["rec_id"]])

    def k_eszett(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        vol = rec["vol"]
        if VOL[vol][2] != "insensitive":
            return None
        rec["trapped"] = True
        head = rec["rest"].rpartition("/")[0]
        rec["rest"] = head + f"/STRAẞE {self.name_seq:06d}.pdf"
        twin = self.consumer(vol, top=rec["top"], rest=head + f"/strasse {self.name_seq:06d}.pdf")
        return ("T1", "ECS 5.3 simple lowercase, not full case folding", [rec["rec_id"]] + ([twin["rec_id"]] if twin else []))

    def k_nfd(self, file, rec, p):
        if not self._ok_rec(rec) or VOL[rec["vol"]][2] != "sensitive" or rec["top"]["part"] == "S":
            return None
        rec["trapped"] = True
        head = rec["rest"].rpartition("/")[0]
        nm = f"Résumé café {self.name_seq:06d}.docx"
        rec["rest"] = head + "/" + nm
        twin = self.mk_rec(file, rec["vol"], top=rec["top"], rest=head + "/" + unicodedata.normalize("NFD", nm),
                           insert=p + 1)
        return ("T1", "ECS 5.3 every path is NFC-normalised before comparison", [rec["rec_id"], twin["rec_id"]])

    def k_hashcase(self, file, rec, p):
        if not self._ok_rec(rec) or rec["hash"][0] not in ("sha256", "md5", "sha1", "etag"):
            return None
        rec["trapped"] = True
        rec["hash_upper"] = True
        return ("T1", "ECS 6.2 digests compare in lowercase hex", [rec["rec_id"]])

    def k_tokvar(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        rec["tok_variant"] = True
        return ("T1", "ECS 5.3 owner token normalisation", [rec["rec_id"]])

    def k_unitrow(self, file, rec, p):
        if not self._ok_rec(rec) or file not in BATCH_UNIT_SOURCES:
            return None
        rec["trapped"] = True
        b = self.rng.choice([x for x in self.batch_ids if self.batches[x]["unit"] in ("MiB", "blk4096", "KiB")])
        rec["batch"] = b
        return ("T2", "ECS 6.1 size unit comes from the export batch", [rec["rec_id"]])

    def k_time(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        dial = TIME_DIALECT[file]
        rec["trapped"] = True
        y = self.rng.choice([2019, 2021, 2023, 2024])
        cfg = self.cfg_plant()
        zone = self.vol_zone(rec["vol"], cfg)
        if dial in ("local", "local_dmy", "local_tzq", "excel1900_local"):
            z = self.zones[zone]
            if z["rule"] == "N":
                fb = g_nth_sunday(y, 11, 1) * DAY + 3600 + 1800 - z["std"]
            elif z["rule"] == "S":
                fb = g_nth_sunday(y, 4, 1) * DAY + 2 * 3600 + 1800 - z["std"]
            else:
                fb = g_epoch(2024, 2, 29, 12)
            rec["time"] = ("utc", fb - z["dst"] if self.rng.random() < 0.5 else fb)
        elif dial == "julian":
            rec["time"] = ("utc", g_epoch(2024, 12, 31, 23, 59, 58))
        else:
            rec["time"] = ("utc", g_epoch(2024, 2, 29, 23, 59, 59))
        return ("T3", "ECS 4.2/4.3 timestamp dialects and the zone tables", [rec["rec_id"]])

    def k_excel_sentinel(self, file, rec, p):
        if not self._ok_rec(rec) or TIME_DIALECT[file] != "excel1900_local":
            return None
        rec["trapped"] = True
        rec["time_raw"] = self.rng.choice(["SENTINEL0", "SENTINEL60"])
        return ("T3", "ECS 4.2 Excel serials 0 and 60 mean not captured: use the batch capture time", [rec["rec_id"]])

    def k_locale(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        dial = SIZE_DIALECT.get(file)
        if dial == "kb4de":
            rec["trapped"] = True
            v = self.rng.randrange(10**4, 10**9)
            s = f"{v // 10000}.{v % 10000:04d}"
            rec["size"] = ("kb4", s)
            rec["content"] = dict(self.new_content(reuse=0), size=g_half_even(v, 10))
            rec["hash"] = self._hash_repr(file, rec["content"])
            return ("T4", "ECS 6.1 de-DE numerals in OPS01 exports", [rec["rec_id"]])
        if dial in ("grouped", "spaced", "kib", "xmlunit"):
            rec["trapped"] = True
            big = self.rng.randrange(10**7, 10**11)
            rec["content"] = dict(self.new_content(reuse=0), size=0 if dial == "kib" and self.rng.random() < 0.4 else big)
            rec["hash"] = self._hash_repr(file, rec["content"])
            rec["size"] = ("bytes", rec["content"]["size"])
            if dial == "kib" and rec["content"]["size"] == 0:
                rec["size_raw"] = "-0"
            if dial == "grouped":
                rec["size_raw"] = f"{big:,}"
            if dial == "xmlunit":
                rec["xml_kib"] = True
            return ("T4", "ECS 6.1 grouping separators and signed zero", [rec["rec_id"]])
        return None

    def k_round(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        dial = SIZE_DIALECT.get(file)
        rec["trapped"] = True
        if dial == "kb4de":
            v = self.rng.randrange(10**4, 10**8) * 10 + 5
            s = f"{v // 10000}.{v % 10000:04d}"
            rec["size"] = ("kb4", s)
            rec["content"] = dict(self.new_content(reuse=0), size=g_half_even(v, 10))
            rec["hash"] = self._hash_repr(file, rec["content"])
            return ("T12", "ECS 6.1 half-even rounding of KB values", [rec["rec_id"]])
        if dial in ("kib", "unit"):
            sz = 2**53 + self.rng.randrange(1, 999) * 2 + 1
            rec["content"] = dict(self.new_content(reuse=0), size=sz)
            rec["hash"] = self._hash_repr(file, rec["content"])
            rec["size"] = (rec["size"][0], sz)
            return ("T12", "ECS 6.1 sizes are exact decimals; binary floats lose bytes", [rec["rec_id"]])
        if TIME_DIALECT[file] in ("epoch_ms", "epoch_ns", "filetime"):
            rec["time"] = ("utc", -self.rng.randrange(DAY, 300 * DAY))
            return ("T12", "ECS 4.2 sub-second values floor toward the past", [rec["rec_id"]])
        rec["trapped"] = False
        return None

    def k_sent_size(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        sent = {"inv_eng01_q3.csv": "-1", "inv_eng02_q3.txt": "?", "inv_hr01_q3.xlsx": "9999",
                "inv_fin02_q3.tsv": "", "inv_rnd01_q3.json": "", "inv_lab01_q3.jsonl": "",
                "inv_mkt01_q3.jsonl": "", "inv_eng01_q3_part2.db": "", "inv_obj01_q3_r2.csv": "-1",
                "inv_leg01_q3.xml": "", "arc01_tape_catalog.txt": "*******", "inv_fin01_q3.parquet": "",
                "rnd01_cold_listing.pdf": "-", "inv_ops01_q3.tsv": "-", "inv_mkt01_supplement.xlsx": ""}.get(file)
        if sent is None:
            return None
        rec["trapped"] = True
        rec["size"] = ("sentinel", sent)
        return ("T5", "source-register.md sentinel table: unknown size", [rec["rec_id"]])

    def k_sent_hash(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        rec["hash"] = ("sentinel", "0" * {"sha256": 64, "md5": 32, "md5b64": 32, "etag": 32, "sha1": 40}[SOURCE_HASH[file]])
        return ("T5", "source-register.md sentinel table: all-zero digest means not computed", [rec["rec_id"]])

    def k_sent_owner(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        ns = rec["owner"][0]
        sent = {"sid": "S-1-0-0", "uid": "uid:{h}:65534", "email": "nobody@corp.example", "corp": "CORP\\-",
                "oldcorp": "OLDCORP\\-", "legacy": "-", "s3": "0" * 64, "svc": "svc-none", "mf": "MF?????"}[ns]
        if "{h}" in sent:
            sent = sent.format(h=self.vol_host[rec["vol"]])
        rec["trapped"] = True
        rec["owner"] = ("sentinel", sent)
        return ("T5", "source-register.md sentinel table: owner not captured", [rec["rec_id"]])

    def k_rowvoid(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        self.add_void(rec["rec_id"])
        return ("T6", "ECS 3.4 voided records", [rec["rec_id"]])

    def k_rowerrata(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        self.add_errata(rec["rec_id"], "bytes", str(rec["content"]["size"] + 4096), rev=2)
        self.add_errata(rec["rec_id"], "bytes", "1", rev=1)
        return ("T7", "ECS 3.5 errata revisions", [rec["rec_id"]])

    def k_hdr(self, file, rec, p):
        if not self._ok_rec(rec) and rec.get("kind") != "jrn":
            return None
        if self.meta[file].get("drift_row") is not None:
            return None
        rec["trapped"] = True
        self.meta[file]["drift_row"] = rec
        return ("T8", "source-register.md: header/layout records may change mid-file", [rec["rec_id"]])

    def k_delim(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        head = rec["rest"].rpartition("/")[0]
        vol = rec["vol"]
        chars = [", ", '"', "; "]
        if VOL[vol][1] not in ("ntfs", "exfat", "hfsplus") and rec["top"]["part"] != "S":
            chars += ["\t", "|", "\\"]
            if file in ("inv_fin02_q3.tsv", "inv_fin01_q3.parquet", "inv_ops01_q3.tsv"):
                chars.append("\n")
        ch = self.rng.choice(chars)
        rec["rest"] = head + f"/q{ch}r {self.name_seq:06d}{ch}x.txt"
        self.name_seq += 1
        return ("T9", "embedded delimiters must survive the format's quoting rules", [rec["rec_id"]])

    def k_enc(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        head = rec["rest"].rpartition("/")[0]
        rec["rest"] = head + f"/Façade Zürich {self.name_seq:06d}.pdf"
        self.name_seq += 1
        rec["enc_trap"] = True
        return ("T10", "source-register.md encoding notes", [rec["rec_id"]])

    def k_age(self, file, rec, p):
        if not self._ok_rec(rec) or rec["vol"] == "ARC01":
            return None
        rec["trapped"] = True
        rec["rest"] = rec["rest"].rpartition("/")[0] + f"/edge {self.name_seq:06d}.tmp"
        self.name_seq += 1
        rec["time"] = ("utc", self.win_end - self.rng.choice([7, 8]) * DAY + self.rng.choice([0, 1, -1]))
        return ("T11", "ECS 7.4 purge when age_days > max age; age floors", [rec["rec_id"]])

    def k_outlier(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        rec["trapped"] = True
        mode = self.rng.randrange(4)
        if mode == 0:
            rec["content"] = dict(self.new_content(reuse=0), size=4398046511104 + self.rng.randrange(10**6))
        elif mode == 1:
            rec["content"] = dict(self.new_content(reuse=0), size=0)
        elif mode == 2:
            rec["time"] = ("utc", g_epoch(1996, 1, 1, 0, 0, 0))
        else:
            rec["time"] = ("utc", g_epoch(2030, 6, 1, 12, 0, 0))
        if mode < 2:
            rec["hash"] = self._hash_repr(file, rec["content"])
            rec["size"] = (rec["size"][0], rec["content"]["size"])
        return ("T15", "ECS 6.6 extreme but valid values are kept", [rec["rec_id"]])

    def k_fkmerge(self, file, rec, p):
        if not self._ok_rec(rec) or rec["owner"][0] == "sentinel":
            return None
        ns, tok = rec["owner"]
        pid = self.tok[ns].get(tok)
        if pid is None:
            return None
        rec["trapped"] = True
        b = self.rng.choice([x for x in self.pids if x != pid and x not in self.merge_effective])
        self.add_merge(pid, b, self.win_start + 3 * DAY, self.rng.choice("AB"), "X")
        return ("T13", "ECS 5.5 merged principals resolve to the surviving account", [rec["rec_id"]])

    def k_prose(self, file, rec, p):
        if not self._ok_rec(rec):
            return None
        vol = rec["vol"]
        head = rec["rest"].rpartition("/")[0]
        rule = PROSE_RULES.get(vol)
        if rule is None:
            return None
        rec["trapped"] = True
        if vol in ("FIN01", "FIN02"):
            self.audit_exclusions.append(rec["rec_id"])
            self.audit_rows.append({"rec_id": rec["rec_id"]})
            return ("T14", "audit-scope-letter-fin.pdf exclusions", [rec["rec_id"]])
        rec["rest"] = head + "/" + rule[0].format(n=self.name_seq)
        self.name_seq += 1
        rec["flags"]["na"] = True
        return ("T14", f"ops-runbook.md: {rule[1]}", [rec["rec_id"]])

    def k_na(self, file, rec, p):
        if not self._ok_rec(rec) or file not in ("inv_ops01_q3.tsv", "inv_obj01_q3_r2.csv", "arc01_tape_catalog.txt"):
            return None
        rec["trapped"] = True
        rec["flags"]["na"] = True
        if file == "inv_ops01_q3.tsv":
            rec["size"] = ("na",)
        return ("T5", "source-register.md: placeholder rows are not files", [rec["rec_id"]])

    def k_jorder(self, file, ev, p):
        rows = self.rows[file]
        if ev.get("kind") != "jrn" or ev.get("trapped") or p + 1 >= len(rows):
            return None
        nxt = rows[p + 1]
        if nxt.get("trapped"):
            return None
        ev["trapped"] = nxt["trapped"] = True
        nxt["ts"], ev["ts"] = ev["ts"], max(nxt["ts"], ev["ts"]) + 1
        return ("T3", "ECS 8.2 events apply in sequence order, not timestamp order", [ev["rec_id"], nxt["rec_id"]])

    def k_jboundary(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped"):
            return None
        ev["trapped"] = True
        mode = self.rng.randrange(3)
        ev["ts"] = {0: self.snapshot[ev["vol"]], 1: self.win_end, 2: self.win_end - 1}[mode]
        if mode == 0:
            ev["ts"] -= self.rng.choice([0, 1])
        return ("T11", "ECS 8.1 events in [snapshot, window.end) apply", [ev["rec_id"]])

    def k_jincident(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or file not in HOST_JOURNALS:
            return None
        ev["trapped"] = True
        host = ev["host"]
        skew = self.rng.choice([3600, 5400, 7200])
        ev["ts"] = self.win_end - self.rng.randrange(60, skew - 60)
        ev["skew"] = skew
        self.incidents.append({"host": host, "from": ev["ts"] - 3 * 3600, "to": ev["ts"] + skew + 3 * 3600,
                               "skew": skew, "adopted": True})
        ev["tags"].add("D:ECS-annex-hosts-rev7.pdf")
        return ("T3", "ECS-annex-hosts-rev7.pdf Appendix D clock incidents (adopted)", [ev["rec_id"]])

    def k_jorphan(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] != "MODIFY":
            return None
        ev["trapped"] = True
        ev["rest"] = ev["rest"].rpartition("/")[0] + f"/ghost {self.name_seq:06d}.dat"
        self.name_seq += 1
        return ("T13", "ECS 8.3 events on a path that is not live are orphans", [ev["rec_id"]])

    def k_jcase(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or VOL[ev["vol"]][2] != "insensitive" or ev["top"]["root"].startswith("/"):
            return None
        ev["trapped"] = True
        ev["root_variant"] = ev["top"]["root"].upper()
        return ("T1", "ECS 5.2 roots compare case-insensitively", [ev["rec_id"]])

    def k_jsent(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] not in ("CREATE", "MODIFY"):
            return None
        ev["trapped"] = True
        ev["hash"] = ("sentinel", "0" * {"sha256": 64, "md5": 32, "md5b64": 32, "etag": 32, "sha1": 40}[SOURCE_HASH[file]])
        return ("T5", "source-register.md sentinel table: all-zero digest", [ev["rec_id"]])

    def k_jdelim(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] != "CREATE":
            return None
        ev["trapped"] = True
        ev["rest"] = ev["rest"].rpartition("/")[0] + f'/say "hi", there {self.name_seq:06d}.txt'
        self.name_seq += 1
        return ("T9", "quoted path fields with embedded quotes and commas", [ev["rec_id"]])

    def k_jenc(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] != "CREATE":
            return None
        ev["trapped"] = True
        ev["rest"] = ev["rest"].rpartition("/")[0] + f"/Ångström Ünal {self.name_seq:06d}.pdf"
        self.name_seq += 1
        ev["enc_trap"] = True
        return ("T10", "source-register.md encoding notes", [ev["rec_id"]])

    def k_jlocale(self, file, ev, p):
        dial = SIZE_DIALECT.get(file)
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] not in ("CREATE", "MODIFY") or dial not in (
                "kb4de", "dotted", "spaced"):
            return None
        ev["trapped"] = True
        if dial == "kb4de":
            v = self.rng.randrange(10**4, 10**9)
            ev["size"] = ("kb4", f"{v // 10000}.{v % 10000:04d}")
            ev["content"] = dict(self.new_content(reuse=0), size=g_half_even(v, 10))
            ev["hash"] = self._hash_repr(file, ev["content"])
        else:
            big = self.rng.randrange(10**6, 10**11)
            ev["content"] = dict(self.new_content(reuse=0), size=big)
            ev["hash"] = self._hash_repr(file, ev["content"])
            ev["size"] = ("bytes", big)
        return ("T4", "source-register.md numeral conventions per journal", [ev["rec_id"]])

    def k_jround(self, file, ev, p):
        dial = TIME_DIALECT[file]
        if ev.get("kind") != "jrn" or ev.get("trapped") or dial not in ("epoch_frac", "epoch_ms", "filetime", "iso_ms"):
            return None
        ev["trapped"] = True
        ev["ts"] = self.win_end - 1
        t = ev["ts"]
        ev["time_raw"] = {"epoch_frac": f"{t}.999", "epoch_ms": str(t * 1000 + 999),
                          "filetime": str((t + 11644473600) * 10**7 + 9999999),
                          "iso_ms": g_iso(t)[:-1] + ".999Z"}[dial]
        return ("T12", "ECS 4.2 sub-second parts floor; they never round up", [ev["rec_id"]])

    def k_joutlier(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] != "CREATE":
            return None
        ev["trapped"] = True
        ev["content"] = dict(self.new_content(reuse=0), size=self.rng.choice([0, 4398046511104 + self.rng.randrange(10**6)]))
        ev["hash"] = self._hash_repr(file, ev["content"])
        ev["size"] = ("bytes", ev["content"]["size"])
        return ("T15", "ECS 6.6 extreme but valid sizes are kept", [ev["rec_id"]])

    def k_excel_round(self, file, rec, p):
        if not self._ok_rec(rec) or TIME_DIALECT[file] not in ("excel1900_local", "excel1904_utc"):
            return None
        rec["trapped"] = True
        rec["excel_nudge"] = True
        return ("T12", "ECS 4.2 Excel serials round to the nearest second", [rec["rec_id"]])

    def k_tz_fmt(self, file, row, p):
        rows = self._trap_rows(file)
        cfg0 = self.cfg_plant()
        vz = {self.vol_zone(INVENTORY_FILES[s], cfg0) for s in ("inv_eng02_q3.txt", "inv_ops01_q3.tsv", "rnd01_cold_listing.pdf")}
        cands = [x for x in rows if x["zone"] in vz and not x.get("trapped") and x["from"] > g_epoch(1997, 1, 1)
                 and x["off"] % 3600 == 0]
        if not cands:
            return None
        row = self.rng.choice(cands)
        row["trapped"] = True
        row["off_hhmm"] = True
        self.last_row = row
        recs = self.tz_consumer(row)
        return ("T4", "tz tables: offsets written as +hh:mm equal the seconds column", recs) if recs else None

    def k_cfg_num(self, file, row, p):
        if self.meta[file].get("num_trap"):
            return None
        layer = {v: k for k, v in CONFIG_FILES.items()}[file]
        target = next((x for x in self.cfg_layers[layer] if x["key"] == "store.block_size"), None)
        if target is None:
            fake = {"key": "store.block_size", "value": 8192, "profile": "qa", "final": False, "ticket": self.ticket(True),
                    "oid": f"OVR-N{layer}", "unit": None}
            self.cfg_layers[layer].append(fake)
            target = fake
        self.meta[file]["num_trap"] = True
        target["num_form"] = True
        self.last_row = target
        self.trap(file, "store.block_size", "T4" if layer != 40 else "T2", "ECS 2.2 numeric spellings per layer format",
                  "concept:C9", [])
        return None

    def k_errata_num(self, file, row, p):
        part = {v: k for k, v in ERRATA_FILES.items()}.get(file)
        vol = self.rng.choice(["ENG01", "FIN02", "OPS01", "LEG01"])
        c = self.consumer(vol)
        if not c:
            return None
        e = self.add_errata(c["rec_id"], "bytes", str(c["content"]["size"] * 3 + 1000000), part=part)
        e["grouped"] = True
        return ("T4", "ECS 3.5 errata byte values may carry grouping separators", [c["rec_id"]])

    def k_jhdr(self, file, ev, p):
        return self.k_hdr(file, ev, p)

    # ---- decoy trap kinds -------------------------------------------------------------
    def k_d_override(self, file, rec, p):
        if rec.get("kind") != "inv" or rec.get("trapped"):
            return None
        rec["trapped"] = True
        sub = rec["rest"].split("/")[0]
        prefix = rec["top"]["prefix"] + sub
        mode = self.rng.randrange(4)
        t = self.ticket(approved=mode != 1)
        self.scope_overrides.append({"override_id": f"SO-{len(self.scope_overrides) + 1:05d}", "file": file,
                                     "volume": rec["vol"], "prefix": prefix + ("x" if mode == 2 else ""),
                                     "ticket": t})
        src = self.rec_by_id.get(rec.get("mirror_of"))
        recs = [rec["rec_id"]] + ([src["rec_id"]] if src else [])
        if mode == 3 and src:
            rec["content"] = self.new_content(reuse=0)
            rec["hash"] = self._hash_repr(file, rec["content"])
            rec["size"] = (rec["size"][0], rec["content"]["size"])
        for rid in recs:
            self.rec_by_id[rid]["tags"].add(f"D:{file}")
        fam = ["T14", "T6", "T11", "T16"][mode]
        return (fam, "authority_matrix.xlsx scope overrides with approved tickets", recs)

    def k_d_errata(self, file, rec, p):
        if rec.get("kind") not in ("inv", "jrn") or rec.get("trapped"):
            return None
        rec["trapped"] = True
        self.add_errata(rec["rec_id"], "bytes", "77", part="A")
        return ("T13", "ECS 3.5 errata never revive a record outside authority", [rec["rec_id"]])

    def k_d_void(self, file, rec, p):
        if rec.get("kind") not in ("inv", "jrn") or rec.get("trapped") or not rec.get("mirror_of"):
            return None
        src = self.rec_by_id.get(rec["mirror_of"])
        if not src:
            return None
        rec["trapped"] = True
        self.add_void(rec["rec_id"])
        return ("T6", "voids keyed to decoy rows do not touch the real export", [rec["rec_id"], src["rec_id"]])

    def k_d_newer(self, file, rec, p):
        if rec.get("kind") != "inv" or rec.get("trapped") or not rec.get("mirror_of"):
            return None
        src = self.rec_by_id.get(rec["mirror_of"])
        if not src:
            return None
        rec["trapped"] = True
        b = self.rng.choice(self.batch_ids)
        self.batches[b]["captured"] = self.win_end - DAY
        for part_rows in self.batch_rows.values():
            for brow in part_rows:
                if brow["batch"] == b:
                    brow["captured"] = self.win_end - DAY
        rec["batch"] = b
        return ("T7", "a newer capture in a non-authoritative export never wins a duplicate", [rec["rec_id"], src["rec_id"]])

    def k_d_fixed(self, file, rec, p):
        if rec.get("kind") != "inv" or rec.get("trapped") or not rec.get("mirror_of"):
            return None
        src = self.rec_by_id.get(rec["mirror_of"])
        if not src or src.get("trapped"):
            return None
        rec["trapped"] = src["trapped"] = True
        src["size"] = ("sentinel", {"inv_fin01_q3.parquet": "", "inv_eng01_q3.csv": "-1",
                                    "arc01_tape_catalog.txt": "*******"}.get(src["file"], ""))
        return ("T5", "the real export's unknown size stays unknown; the decoy's value is not evidence",
                [rec["rec_id"], src["rec_id"]])

    def k_d_push(self, file, rec, p):
        if rec.get("trapped"):
            return None
        rec["trapped"] = True
        fam = self.rng.choice(["T8", "T10", "T5"])
        if fam == "T8":
            self.meta[file].setdefault("drifts", []).append(rec["rec_id"])
        elif fam == "T10":
            rec["enc_trap"] = True
        else:
            rec["push_sentinel"] = True
        return (fam, "decoy format damage does not change its authority status", [rec["rec_id"]])

    def k_d_jerrata(self, file, ev, p):
        if (ev.get("kind") != "jrn" or ev.get("trapped") or ev["op"] not in ("CREATE", "MODIFY")
                or not (self.mkt_gap[0] <= ev["seq"] <= self.mkt_gap[1])):
            return None
        ev["trapped"] = True
        self.add_errata(ev["rec_id"], "bytes", "1", rev=1)
        self.add_errata(ev["rec_id"], "bytes", str(ev["content"]["size"] + 4096), rev=2)
        return ("T7", "errata revisions apply to replica events inside the authoritative gap", [ev["rec_id"]])

    def k_d_jgap(self, file, ev, p):
        if ev.get("kind") != "jrn" or ev.get("trapped") or not (self.mkt_gap[0] <= ev["seq"] <= self.mkt_gap[1]):
            return None
        ev["trapped"] = True
        return ("T14", "ops-runbook.md: the replica is authoritative inside the primary journal gap", [ev["rec_id"]])

    def ref_rows_for(self, file):
        special = {
            "principal_directory.xlsx": lambda: self.d02_hist + self.d02_dir,
            "hash_index_master.parquet": lambda: self.xwalk_rows["sha1V"],
            "retention_rules_v4.toml": lambda: self.d04_rows,
            "volumes_cmdb.json": lambda: self.d05_rows,
            "void_register_q3_r2.xml": lambda: self.void_rows["A"],
            "retention-schedule-2026-r3.docx": lambda: self.ext_rows["C"],
            "retention-schedule-2026-r2.docx": lambda: self.ext_rows["C"],
            "ECS-annex-hosts-rev7.pdf": lambda: self.host_rows["B"],
            "principal_map_ldap.html": lambda: self.tok_rows["oldcorp"],
            "site-policy-v2.yaml": lambda: self.cfg_layers[20],
            "errata_register_q3_r2.tsv": lambda: self.errata_rows["A"],
            "host_aliases.ini": lambda: self.hostalias_rows,
            "authority_matrix.xlsx": lambda: self.runs,
            "change_tickets.csv": lambda: self.ticket_rows,
        }
        if file in special:
            return special[file]()
        role = FILE_ROLE[file]
        kind, _, arg = role.partition(":")
        if kind == "alias":
            return self.alias_rows[arg]
        if kind == "ext":
            return self.ext_rows[arg]
        if kind == "tok":
            return self.tok_rows[arg]
        if kind == "xwalk":
            return self.xwalk_rows[arg]
        if kind == "batches":
            return self.batch_rows[arg]
        if kind == "csdirs":
            return self.cs_rows[arg]
        if kind == "merges":
            return [m for m in self.merges if m["part"] == arg]
        if kind == "tz":
            return self.tz_rows[arg]
        if kind == "hosts":
            return self.host_rows[arg]
        if kind == "config":
            return self.cfg_layers[int(arg)]
        if kind == "rules":
            return self.rules_v3 if arg == "v3" else self.rules_overlay
        if kind in ("voids", "errata", "holds", "store"):
            return self.pad_rows(file)
        if file == "tool.zip":
            return self.ext_rows["E"]
        if file == "volumes.yaml":
            return self.alias_rows["E"]
        if file == "ECS-standard.md":
            return self.alias_rows["F"]
        if file == "source-register.md":
            return self.host_rows["A"]
        if file == "ops-runbook.md":
            return [m for m in self.merges if m["part"] == "B"]
        if file == "hostalias" or file == "host_aliases.ini":
            return self.hostalias_rows
        if file in ("change_tickets.csv", "authority_matrix.xlsx", "retention-schedule-2026-r2.docx",
                    "legal-hold-memo-q3.docx", "audit-scope-letter-fin.pdf"):
            return self.placeholder_rows(file)
        return self.placeholder_rows(file)

    def placeholder_rows(self, file):
        key = "_ph_" + file
        if not hasattr(self, key):
            setattr(self, key, [{"ph": i} for i in range(self.N)])
        return getattr(self, key)

    def pad_rows(self, file):
        return self.placeholder_rows(file)

    def ref_consumer(self, file, row):
        role = FILE_ROLE[file]
        kind = role.split(":")[0]
        r = self.rng
        if kind == "alias" or file in ("volumes.yaml", "ECS-standard.md"):
            vol = self.alias_vol(row)
            top = self.top_of(row) if vol in VOL else None
            if top is None or top["state"] != "ok":
                return None
            c = self.consumer(vol, top=top)
            return [c["rec_id"]] if c else None
        if kind == "ext" or file == "tool.zip":
            if row.get("family") in (None, "N/A") or row.get("status") != "active":
                return None
            vol = r.choice(["ENG01", "FIN01", "OPS01", "LAB01", "FIN02"])
            c = self.consumer(vol, rest="docs/" + self._name(vol, ext=row["ext"].lower()))
            return [c["rec_id"]] if c else None
        if kind == "tok":
            ns = role.split(":")[1]
            if "pid" not in row or row.get("status", "active") != "active":
                return None
            c = self.consumer(self.ns_volume(ns), ns=ns, pid=row["pid"])
            if not c:
                return None
            c["owner"] = (ns, row["token"])
            return [c["rec_id"]]
        if kind == "xwalk":
            ids = [x["rec_id"] for x in self.recs if x.get("hash") and x["hash"][1] == row.get("digest")][:2]
            return ids or None
        if kind == "batches":
            src = r.choice(sorted(f for f in BATCH_UNIT_SOURCES if f not in DECOYS and f not in (
                "inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx")))
            c = self.mk_rec(src, INVENTORY_FILES[src], batch=row["batch"])
            return [c["rec_id"]]
        if kind == "csdirs":
            vol = row["vol"]
            top = next((t for t in self.tops[vol] if row["prefix"].startswith(t["prefix"]) and t["state"] == "ok"), None)
            if top is None:
                return None
            c = self.consumer(vol, top=top, rest=row["prefix"][len(top["prefix"]):] + "Mixed" + self._name(vol))
            return [c["rec_id"]] if c else None
        if kind == "merges" or file == "ops-runbook.md":
            a = row.get("from")
            for ns in ("uid", "email", "sid", "corp"):
                if self.tok_by_pid[ns].get(a):
                    c = self.consumer(self.ns_volume(ns), ns=ns, pid=a)
                    return [c["rec_id"]] if c else None
            return None
        if kind == "tz":
            return self.tz_consumer(row)
        if kind == "hosts" or file == "source-register.md":
            vols = [v for v, h in self.vol_host.items() if h == row.get("host")]
            if not vols:
                return None
            c = self.consumer(vols[0])
            return [c["rec_id"]] if c else None
        if file == "host_aliases.ini":
            return self.hostalias_consumer(row)
        if kind == "config":
            return self.cfg_consumer(row)
        if kind == "rules":
            return self.rule_consumer(row)
        return None

    def tz_consumer(self, row):
        rows = self.tz_rows[self.zones[row["zone"]]["part"]]
        cfg0 = self.cfg_plant()
        vz = {self.vol_zone(INVENTORY_FILES[s], cfg0) for s in ("inv_eng02_q3.txt", "inv_ops01_q3.tsv", "rnd01_cold_listing.pdf", "inv_lab01_q3.jsonl")}
        if row["zone"] not in vz:
            cands = [x for x in rows if x["zone"] in vz and not x.get("trapped") and x["from"] > g_epoch(1997, 1, 1)]
            if not cands:
                return None
            row = self.rng.choice(cands)
            self.last_row = row
        zone = row["zone"]
        cfg = self.cfg_plant()
        for src in ("inv_eng02_q3.txt", "inv_ops01_q3.tsv", "rnd01_cold_listing.pdf", "inv_lab01_q3.jsonl"):
            vol = INVENTORY_FILES[src]
            if self.vol_zone(vol, cfg) == zone:
                t = row["from"] + 1800 if row["from"] > g_epoch(1996, 1, 1) else g_epoch(2001, 1, 1)
                c = self.mk_rec(src, vol, mtime=t)
                return [c["rec_id"]]
        return None

    def hostalias_consumer(self, row):
        host = row["host"]
        uid = 70000 + len(self.tok_rows["uid"])
        pid = self.rng.choice(self.pids)
        self._add_tok("uid", f"uid:{host}:{uid}", pid, host=host, uid=uid)
        c = self.consumer("FIN01", ns="uid", pid=pid)
        if not c:
            return None
        c["owner"] = ("uid", f"uid:{host}:{uid}")
        c["uid_alias"] = row["alias"]
        return [c["rec_id"]]

    def cfg_consumer(self, row):
        key = row["key"]
        if not key.startswith("subtree."):
            return None
        body, _, flag = key.rpartition(".")
        vol, _, prefix = body[8:].partition(":")
        if vol == "ARC01":
            return None
        top = next((t for t in self.tops[vol] if prefix.startswith(t["prefix"]) and t["state"] == "ok"), None)
        if top is None:
            return None
        sub = prefix[len(top["prefix"]):]
        if flag == "purge_exempt":
            c = self.consumer(vol, top=top, rest=sub + self._name(vol, ext="tmp"), mtime=self.win_end - 500 * DAY)
        else:
            c = self.consumer(vol, top=top, rest=sub + self._name(vol, ext="eml"), mtime=self.win_end - 900 * DAY)
        return [c["rec_id"]] if c else None

    def rule_consumer(self, row):
        pat = row["pattern"]
        vol = row["scope"] if row["scope"] != "*" else None
        if pat.startswith("family:") or not pat.startswith("/"):
            vol = vol or self.rng.choice(["ENG01", "FIN01", "OPS01"])
            fam_ext = {"family:TMP": "tmp", "family:LOG": "log", "family:BAK": "bak", "family:MED": "mov",
                       "family:MAIL": "eml", "family:DBF": "db"}
            ext = fam_ext.get(pat)
            name = self._name(vol, ext=ext) if ext else pat.replace("*", "x" + str(self.name_seq)).replace("/", "")
            c = self.consumer(vol, rest="src/" + name, mtime=self.win_end - 800 * DAY)
            return [c["rec_id"]] if c else None
        top_name = pat.strip("/").split("/")[0]
        if vol is None:
            for v in VOL:
                if any(t["prefix"] == f"/{top_name}/" for t in self.tops[v]):
                    vol = v
                    break
        if vol is None:
            return None
        top = next((t for t in self.tops[vol] if t["prefix"] == f"/{top_name}/" and t["state"] == "ok"), None)
        if top is None:
            return None
        rest = pat.strip("/").split("/", 1)[1] if "/" in pat.strip("/") else ""
        rest = rest.replace("**/", "deep/").replace("/**", "/inner").replace("**", "deep").replace("*", f"m{self.name_seq}")
        self.name_seq += 1
        if pat.endswith("/") or rest.endswith("/"):
            rest = rest.rstrip("/") + "/" + self._name(vol, ext="tmp")
        if "." not in rest.rsplit("/", 1)[-1]:
            rest += ".tmp"
        c = self.consumer(vol, top=top, rest=rest, mtime=self.win_end - 800 * DAY)
        return [c["rec_id"]] if c else None

    def _ref_flag(self, file, row, flag):
        if row.get(flag) or row.get("trapped"):
            return None
        self.last_row = None
        recs = self.ref_consumer(file, row)
        if not recs:
            return None
        target = self.last_row if self.last_row is not None else row
        target[flag] = True
        self.last_row = target
        return recs

    def k_ref_hdr(self, file, row, p):
        if self.meta[file].get("drift_row") is not None or not isinstance(row, dict):
            return None
        rows = self._trap_rows(file)
        nxt = rows[(p + 1) % len(rows)]
        self.last_row = None
        recs = self.ref_consumer(file, nxt)
        if not recs:
            return None
        target = self.last_row if self.last_row is not None else nxt
        self.meta[file]["drift_row"] = target
        self.last_row = target
        return ("T8", "header and column order may change mid-table; follow the latest header", recs)

    def k_ref_enc(self, file, row, p):
        recs = self._ref_flag(file, row, "enc_trap")
        return ("T10", "ECS 2.3 text is NFC-normalised before comparison; declared encodings apply", recs) if recs else None

    def k_ref_delim(self, file, row, p):
        recs = self._ref_flag(file, row, "delim_trap")
        return ("T9", "free-text columns may contain the format's delimiter", recs) if recs else None

    def k_ref_case(self, file, row, p):
        recs = self._ref_flag(file, row, "case_trap")
        return ("T1", "ECS 2.3 key normalisation (case, whitespace, padding)", recs) if recs else None

    def k_tz_dst(self, file, row, p):
        rows = self._trap_rows(file)
        cfg0 = self.cfg_plant()
        vz = {self.vol_zone(INVENTORY_FILES[s], cfg0) for s in ("inv_eng02_q3.txt", "inv_ops01_q3.tsv", "rnd01_cold_listing.pdf")}
        cands = [x for x in rows if x["zone"] in vz and x.get("dst") == 1 and not x.get("trapped") and x["from"] > g_epoch(1997, 1, 1)]
        if not cands:
            return None
        row = self.rng.choice(cands)
        self.last_row = row
        zone = row["zone"]
        cfg = self.cfg_plant()
        for src in ("inv_eng02_q3.txt", "inv_ops01_q3.tsv", "rnd01_cold_listing.pdf"):
            vol = INVENTORY_FILES[src]
            if self.vol_zone(vol, cfg) != zone:
                continue
            row["trapped"] = True
            z = self.zones[zone]
            t = row["to"] - z["dst"] // 2 if self.rng.random() < 0.5 else row["from"] + 60
            c = self.mk_rec(src, vol, mtime=t)
            return ("T3", "ECS 4.3 fall-back ambiguity reads as standard time; gaps read with the standard offset",
                    [c["rec_id"]])
        return None

    def k_cfg_final(self, file, row, p):
        if row.get("trapped") or not row["key"].startswith("subtree."):
            return None
        recs = self.cfg_consumer(row)
        if not recs:
            return None
        row["trapped"] = True
        layer = {v: k for k, v in CONFIG_FILES.items()}[file]
        if layer < 40:
            if any(x["key"] == row["key"] for x in self.cfg_layers[40]):
                return None
            row["final"] = True
            self.cfg_layers[40].append({"key": row["key"], "value": not row["value"], "profile": "*", "final": False,
                                        "ticket": self.ticket(True), "oid": f"OVR-F{p:05d}", "unit": None})
            return ("T7", "ECS 2.2 a final key in a lower layer blocks later layers", recs)
        row["value"] = not row["value"]
        return ("T11", "ECS 2.2 overrides apply only with tickets approved strictly before window.end", recs)

    def k_cfg_bool(self, file, row, p):
        if row.get("trapped") or not isinstance(row.get("value"), bool):
            return None
        recs = self.cfg_consumer(row)
        if not recs:
            return None
        row["trapped"] = True
        row["bool_form"] = self.rng.choice(["yes", "no", "on", "off", "1", "0"]) if file != "estate-defaults.toml" else None
        if row["bool_form"]:
            row["value"] = row["bool_form"] in ("yes", "on", "1")
        return ("T5", "ECS 2.2 boolean spellings per layer format", recs)

    def k_rule_last(self, file, row, p):
        if row.get("trapped") or not row["pattern"].startswith("/"):
            return None
        recs = self.rule_consumer(row)
        if not recs:
            return None
        row["trapped"] = True
        return ("T7", "ECS 7.3 the last matching rule decides", recs)

    def k_rule_withdrawn(self, file, row, p):
        if row.get("trapped") or file != "retention_rules_v3.yaml" or row["class"] == "standard":
            return None
        recs = self.rule_consumer(row)
        if not recs:
            return None
        row["trapped"] = True
        row["status"] = "withdrawn"
        return ("T6", "ECS 7.3 withdrawn rules never match", recs)

    def k_rule_dir(self, file, row, p):
        if row.get("trapped") or not row["pattern"].endswith("/") or not row["pattern"].startswith("/"):
            return None
        top_name = row["pattern"].strip("/").split("/")[0]
        vol = next((v for v in VOL if any(t["prefix"] == f"/{top_name}/" for t in self.tops[v])), None)
        if vol is None:
            return None
        top = next(t for t in self.tops[vol] if t["prefix"] == f"/{top_name}/")
        if top["state"] != "ok":
            return None
        last = row["pattern"].rstrip("/").rsplit("/", 1)[-1]
        c = self.consumer(vol, top=top, rest=f"{last}x/" + self._name(vol, ext="tmp"), mtime=self.win_end - 900 * DAY)
        if not c:
            return None
        row["trapped"] = True
        return ("T11", "ECS 7.3 directory patterns match whole segments", [c["rec_id"]])

    def _ref_tables(self):
        self.tz_rows = {"A": [], "B": []}
        for name in self.zone_names:
            z = self.zones[name]
            for s, e, off, d in self.tz_segments[name]:
                self.tz_rows[z["part"]].append({"zone": name, "from": s, "to": e, "off": off, "dst": d})
        self.host_rows = {"A": [], "B": []}
        for h in sorted(self.hosts):
            self.host_rows[self.hosts[h]["part"]].append({"host": h, "zone": self.hosts[h]["zone"]})
        self.hostalias_rows = [{"alias": a, "host": h} for a, h in sorted(self.host_alias.items())]
        self.d02_hist = [{"old": o, "new": n, "migrated": self.win_start - self.rng.randrange(DAY, 800 * DAY), "rev": 1}
                         for o, n in sorted(self.sid_history.items())]
        self.d02_dir = [{"pid": p, "account": self.stale_accounts.get(p, self.principals[p]["account"]),
                         "status": "active"} for p in self.pids] + [
            {"pid": p, "account": f"ghost.{p[-4:]}", "status": "active"} for p in self.dir_only_pids]
        self.d05_rows = [{"serial": s, "volume": v, "status": "active" if v in VOL else "retired"}
                         for s, v in sorted(self.serials.items())]
        self.d04_rows = [dict(x) for x in self.rules_v3]
        self.d13_rows = []
        self.d15_rows = []
        self.d07_rows = []
        self.d10_rows = [{"cls": c, "max": v[0], "arch": v[1]} for c, v in CLASSES.items()]
        self.d12_rows = []

    def k_d02_hist(self, file, row, p):
        if row.get("trapped") or "old" not in row:
            return None
        row["trapped"] = True
        pid = self.tok["sid"].get(row["new"])
        if pid is None:
            return None
        mode = self.rng.randrange(2)
        if mode == 1:
            other = self.rng.choice(list(self.tok["sid"]))
            self.d02_hist.insert(p + 1, dict(row, new=other, migrated=row["migrated"] + DAY, rev=2))
            self.sid_history[row["old"]] = other
            pid = self.tok["sid"][other]
        c = self.consumer("ENG01", ns="sid", pid=pid)
        if not c:
            return None
        c["owner"] = ("sid", row["old"])
        self.last_row = row
        return ("T13" if mode == 0 else "T7", "principal_directory.xlsx sid_history is the only SID-history crosswalk",
                [c["rec_id"]])

    def k_d02_stale(self, file, row, p):
        if row.get("trapped") or "pid" not in row or row["pid"] not in self.principals:
            return None
        row["trapped"] = True
        row["account"] = self.principals[row["pid"]]["account"].replace(".", "_") + "old"
        mode = self.rng.randrange(2)
        if mode == 1:
            row["status"] = "deleted"
        for ns in ("sid", "email", "uid"):
            if self.tok_by_pid[ns].get(row["pid"]):
                c = self.consumer(self.ns_volume(ns), ns=ns, pid=row["pid"])
                if c:
                    self.last_row = row
                    return ("T16" if mode == 0 else "T6", "account names come from the principal register, not the 2025 directory",
                            [c["rec_id"]])
        return None

    def k_d05_serial(self, file, row, p):
        rows_c = [a for part in ("C", "D") for a in self.alias_rows[part]
                  if a["volume"].startswith("serial:") and not a.get("trapped") and self.alias_vol(a) in VOL]
        if not rows_c:
            return None
        a = self.rng.choice(rows_c)
        top = self.top_of(a)
        if top is None or top["state"] != "ok":
            return None
        a["trapped"] = True
        vol = self.alias_vol(a)
        c = self.consumer(vol, top=top)
        if not c:
            return None
        drow = next(x for x in self.d05_rows if x["serial"] == a["volume"][7:])
        cyc = self.meta[file].get("d05", 0)
        self.meta[file]["d05"] = cyc + 1
        mode = cyc % 4
        fam = ["T13", "T16", "T7", "T6"][mode]
        if mode == 1:
            rnd = self.consumer("RND01", rest=self._sub() + f"/MixedCase Report {self.name_seq:06d}.PDF")
            self.name_seq += 1
            if rnd is None:
                return None
            self.last_row = drow
            return ("T16", "volumes_cmdb.json is not authoritative for file-system types", [rnd["rec_id"]])
        elif mode == 2:
            drow["rev_noise"] = True
        elif mode == 3:
            dead = f"VS-{self.rng.randrange(16**6):06X}"
            self.serials[dead] = "RETIRED"
            drow = {"serial": dead, "volume": vol, "status": "retired"}
            self.d05_rows.append(drow)
            a["volume"] = "serial:" + dead
            top["state"] = "dead"
            self._tops_cache = {}
        self.last_row = drow
        return (fam, "volumes_cmdb.json serials are the only serial crosswalk", [c["rec_id"]])

    def k_d04(self, file, row, p):
        if row.get("trapped") or "seq" not in row:
            return None
        src = next((x for x in self.rules_v3 if x["seq"] == row["seq"]), None)
        if src is None or src["status"] != "active" or not src["pattern"].startswith("/"):
            return None
        recs = self.rule_consumer(src)
        if not recs:
            return None
        row["trapped"] = True
        self.last_row = row
        mode = self.rng.randrange(4)
        if mode == 0:
            row["class"] = "temp" if src["class"] != "temp" else "records"
            return ("T16", "retention_rules_v4.toml is not ratified; its classes are not in force", recs)
        if mode == 1:
            self.v4_withdrawals.append({"seq": src["seq"], "ticket": self.ticket(True)})
            return ("T6", "retention_rules_v4.toml withdrawals with approved tickets remove v3 rules", recs)
        if mode == 2:
            self.v4_withdrawals.append({"seq": src["seq"], "ticket": self.ticket(False)})
            return ("T7", "withdrawals with unapproved tickets change nothing", recs)
        self.v4_withdrawals.append({"seq": src["seq"] + 3, "ticket": self.ticket(True)})
        return ("T13", "withdrawals naming no v3 rule are inert", recs)

    def k_d07(self, file, row, p):
        vol = self.rng.choice([v[0] for v in VOLUMES if v[0] != "OBJ01"])
        c = self.consumer(vol)
        if not c:
            return None
        mode = self.rng.randrange(4)
        v = self.add_void(c["rec_id"], part="A")
        if mode == 0:
            self.reinstatements.append({"rec_id": c["rec_id"], "ticket": self.ticket(True), "void_id": v["void_id"]})
            self.last_row = self.reinstatements[-1]
            fam = "T6"
        elif mode == 1:
            self.reinstatements.append({"rec_id": c["rec_id"], "ticket": self.ticket(False), "void_id": v["void_id"]})
            self.last_row = self.reinstatements[-1]
            fam = "T7"
        elif mode == 2:
            self.d07_rows.append({"void_id": v["void_id"], "rec_id": c["rec_id"], "status": "cancelled"})
            self.last_row = self.d07_rows[-1]
            fam = "T16"
        else:
            self.reinstatements.append({"rec_id": c["rec_id"] + "0", "ticket": self.ticket(True), "void_id": v["void_id"]})
            self.last_row = self.reinstatements[-1]
            fam = "T13"
        return (fam, "void_register_q3_r2.xml reinstatements are the only reinstatement evidence", [c["rec_id"]])

    def k_d10(self, file, row, p):
        vol = self.rng.choice(["ENG01", "OPS01", "FIN02"])
        mode = self.rng.randrange(4)
        ext = self.rng.choice([e["ext"] for e in self.ext_rows["A"] if e["status"] == "active" and e["family"] != "N/A"])
        arow = next(e for e in self.ext_rows["A"] if e["ext"] == ext)
        if mode == 0:
            arow["pending"] = True
            arow["family"] = "DOC"
            self.ext_corrections.append({"ext": ext, "family": "TMP", "applies": True})
            fam = "T13"
        elif mode == 1:
            self.ext_corrections.append({"ext": ext, "family": "TMP", "applies": False})
            fam = "T16"
        elif mode == 2:
            arow["pending"] = True
            self.ext_corrections.append({"ext": ext, "family": "BAK", "applies": True, "rev": 1})
            self.ext_corrections.append({"ext": ext, "family": "LOG", "applies": True, "rev": 2})
            fam = "T7"
        else:
            arow["pending"] = True
            arow["status"] = "retired"
            self.ext_corrections.append({"ext": ext, "family": "TMP", "applies": True})
            fam = "T6"
        c = self.consumer(vol, rest="src/" + self._name(vol, ext=ext), mtime=self.win_end - 300 * DAY)
        self.last_row = self.ext_corrections[-1]
        return (fam, "retention-schedule-2026-r3.docx Annex F corrections apply only to rows flagged pending",
                [c["rec_id"]]) if c else None

    def k_d11(self, file, row, p):
        jf = self.rng.choice(sorted(HOST_JOURNALS))
        evs = [e for e in self.rows[jf] if not e.get("trapped") and e["op"] in ("MODIFY", "DELETE")]
        if not evs:
            return None
        ev = self.rng.choice(evs)
        mode = self.rng.randrange(5)
        if mode == 4:
            other = [e for e in evs if e["host"] != self.vol_host[e["vol"]]]
            if not other:
                return None
            ev = self.rng.choice(other)
            ev["trapped"] = True
            ev["ts"] = self.win_end - 1800
            inc = {"host": self.vol_host[ev["vol"]], "from": ev["ts"] - 3600, "to": ev["ts"] + 3600, "skew": 3600,
                   "adopted": True}
            self.incidents.append(inc)
            self.last_row = inc
            return ("T13", "clock incidents follow the host recorded on the event, not the volume host", [ev["rec_id"]])
        ev["trapped"] = True
        skew = 3600
        ev["ts"] = self.win_end - 1800
        ev["skew"] = skew
        inc = {"host": ev["host"], "from": ev["ts"] - 3600, "to": ev["ts"] + skew + 3600, "skew": skew, "adopted": True}
        fam = "T3"
        if mode == 1:
            inc["adopted"] = False
            ev["skew"] = 0
            ev["ts"] = self.win_end + 600
            fam = "T6"
        elif mode == 2:
            self.incidents.append(dict(inc, skew=7200, rev=1))
            inc["rev"] = 2
            fam = "T7"
        elif mode == 3:
            self.host_rows_d11_diff = getattr(self, "host_rows_d11_diff", []) + [ev["host"]]
            fam = "T16"
        self.incidents.append(inc)
        self.last_row = inc
        return (fam, "ECS-annex-hosts-rev7.pdf Appendix D (adopted) clock incidents", [ev["rec_id"]])

    def k_d12(self, file, row, p):
        if row.get("trapped") or "pid" not in row:
            return None
        row["trapped"] = True
        mode = self.rng.randrange(4)
        if mode == 0:
            c = self.consumer("ENG02", ns="oldcorp", pid=row["pid"])
            fam = "T13"
        elif mode == 1:
            row["status"] = "revoked"
            c = self.consumer("ENG02", ns="oldcorp")
            fam = "T6"
        elif mode == 2:
            new = dict(row, pid=self.rng.choice(self.pids), valid_from=self.next_valid_from("oldcorp", row["token"]))
            new.pop("trapped", None)
            self.tok_rows["oldcorp"].insert(p + 1, new)
            c = self.consumer("ENG02", ns="oldcorp", pid=row["pid"])
            fam = "T7"
        else:
            lrow = self.rng.choice(self.tok_rows["legacy"])
            self.d12_rows.append({"token": lrow["token"], "pid": self.rng.choice(self.pids)})
            c = self.consumer("LEG01", ns="legacy", pid=lrow["pid"])
            if c:
                c["owner"] = ("legacy", lrow["token"])
            return ("T16", "principal_map_ldap.html rows outside OLDCORP are archive copies", [c["rec_id"]]) if c else None
        if not c:
            return None
        c["owner"] = ("oldcorp", row["token"])
        self.last_row = row
        return (fam, "principal_map_ldap.html is authoritative only for the OLDCORP domain", [c["rec_id"]])

    def k_d13(self, file, row, p):
        mode = self.rng.randrange(4)
        layer40 = [x for x in self.cfg_layers[40] if x["key"].startswith("subtree.") and self.ticket_ok(x["ticket"])
                   and not x.get("trapped")]
        if not layer40:
            return None
        ov = self.rng.choice(layer40)
        recs = self.cfg_consumer(ov)
        if not recs:
            return None
        ov["trapped"] = True
        if mode == 0:
            self.revocations.append({"oid": ov["oid"], "ticket": self.ticket(True)})
            fam = "T6"
        elif mode == 1:
            self.revocations.append({"oid": ov["oid"], "ticket": self.ticket(False)})
            fam = "T7"
        elif mode == 2:
            self.revocations.append({"oid": ov["oid"] + "9", "ticket": self.ticket(True)})
            fam = "T13"
        else:
            self.d13_rows.append({"key": ov["key"], "value": not ov["value"]})
            fam = "T16"
        self.last_row = self.revocations[-1] if mode < 3 else self.d13_rows[-1]
        return (fam, "site-policy-v2.yaml revocations are the only revocation evidence", recs)

    def k_d15(self, file, row, p):
        vol = self.rng.choice([v[0] for v in VOLUMES])
        c = self.consumer(vol)
        if not c:
            return None
        mode = self.rng.randrange(4)
        good = str(c["content"]["size"] + 512)
        e = self.add_errata(c["rec_id"], "bytes", good, part="A")
        if mode == 0:
            self.errata_withdrawals.append({"errata_id": e["errata_id"], "ticket": self.ticket(True)})
            fam = "T6"
        elif mode == 1:
            self.errata_withdrawals.append({"errata_id": e["errata_id"], "ticket": self.ticket(False)})
            fam = "T7"
        elif mode == 2:
            self.d15_rows.append({"rec_id": c["rec_id"], "field": "bytes", "value": "1", "rev": 9})
            fam = "T16"
        else:
            self.errata_withdrawals.append({"errata_id": e["errata_id"] + "7", "ticket": self.ticket(True)})
            fam = "T13"
        self.last_row = self.errata_withdrawals[-1] if mode != 2 else self.d15_rows[-1]
        return (fam, "errata_register_q3_r2.tsv withdrawals are the only withdrawal evidence", [c["rec_id"]])

    def k_d03(self, file, row, p):
        arc = [x for x in self.recs if x["file"] == "arc01_tape_catalog.txt" and not x.get("trapped")
               and x.get("hash") and x["hash"][0] == "sha1"]
        if not arc:
            return None
        rec = self.rng.choice(arc)
        rec["trapped"] = True
        mode = self.rng.randrange(4)
        dig = rec["hash"][1]
        if mode == 0:
            self.xwalk_rows["sha1V"].append({"digest": dig, "sha256": self.xwalk["sha1V"][dig], "status": "revoked",
                                             "rev": 2, "alg": "sha1", "origin": "ARC01"})
            fam = "T6"
        elif mode == 1:
            new = g_hex(self.rng, 256)
            self.xwalk_rows["sha1V"].append({"digest": dig, "sha256": new, "status": "ok", "rev": 3, "alg": "sha1",
                                             "origin": "ARC01"})
            fam = "T7"
        elif mode == 2:
            self.xwalk_rows["sha1V"].append({"digest": dig, "sha256": g_hex(self.rng, 256), "status": "ok", "rev": 5,
                                             "alg": "sha1", "origin": "FIN02"})
            fam = "T13"
        else:
            other = self.rng.choice([x for x in self.xwalk_rows["sha1A"]] or [None])
            if other is None:
                return None
            self.xwalk_rows["sha1V"].append(dict(other, sha256=g_hex(self.rng, 256), origin="FIN02"))
            fam = "T16"
            rec = next((x for x in self.recs if x.get("hash") and x["hash"][1] == other["digest"]), rec)
        self.last_row = self.xwalk_rows["sha1V"][-1]
        return (fam, "hash_index_master.parquet rows with origin ARC01 are authoritative", [rec["rec_id"]])

    def k_d09(self, file, row, p):
        return None

    def k_fmt(self, file, row, p):
        prim = PRIMARY_KIND.get(file)
        if prim is None:
            return None
        self.last_row = None
        got = getattr(self, "k_" + prim)(file, row, p)
        if not got or self.last_row is None:
            return None
        cyc = self.meta[file].get("fmt_cycle", 0)
        self.meta[file]["fmt_cycle"] = cyc + 1
        fam = ["T8", "T9", "T10", "T1"][cyc % 4]
        if fam == "T8" and self.meta[file].get("drift_row") is None:
            self.meta[file]["drift_row"] = self.last_row
        else:
            if fam == "T8":
                fam = ["T9", "T10", "T1"][cyc % 3]
            self.last_row[{"T9": "delim_trap", "T10": "enc_trap", "T1": "case_trap"}[fam]] = True
        return (fam, "format rules of the file (quoting, encoding noise, key normalisation, header changes)", got[2])

    def k_host(self, file, row, p):
        part = "A" if file == "source-register.md" else "B"
        hs = [h for h in self.vol_host.values() if self.hosts[h]["part"] == part]
        if not hs:
            return None
        h = self.rng.choice(hs)
        hrow = next(x for x in self.host_rows[part] if x["host"] == h)
        vol = next(v for v, hh in self.vol_host.items() if hh == h)
        src = {"ENG02": "inv_eng02_q3.txt", "OPS01": "inv_ops01_q3.tsv", "RND01": "rnd01_cold_listing.pdf"}.get(vol)
        if src is None:
            src = self.rng.choice(sorted(f for f, v in INVENTORY_FILES.items() if v == vol and f not in DECOYS and f not in (
                "inv_mkt01_supplement.xlsx", "inv_hr01_q3.xlsx")) or ["inv_eng02_q3.txt"])
            vol = INVENTORY_FILES[src]
        c = self.mk_rec(src, vol)
        self.last_row = hrow
        fam = "T3" if TIME_DIALECT[src].startswith("local") else "T13"
        return (fam, "volume host zones come from the host registers", [c["rec_id"]])

    def k_auth_snapshot(self, file, row, p):
        vol = self.rng.choice([v[0] for v in VOLUMES if v[0] != "MKT01"])
        jf = next((f for f, v in JOURNAL_FILES.items() if v == vol and f not in DECOYS), None)
        if jf is None:
            return None
        evs = [e for e in self.rows[jf] if not e.get("trapped")]
        if not evs:
            return None
        ev = self.rng.choice(evs)
        ev["trapped"] = True
        real = next(x for x in self.runs if INVENTORY_FILES.get(x["file"]) == vol and x["kind"] == "full"
                    and x["file"] not in DECOYS)
        fake = dict(real, run_id=real["run_id"] + "S", completed=real["completed"] - 2 * DAY,
                    superseded_by=real["run_id"])
        self.runs.append(fake)
        ev["ts"] = real["completed"] - DAY
        self.last_row = fake
        return ("T7", "authority_matrix.xlsx: superseded runs do not set the snapshot", [ev["rec_id"]])

    def k_audit(self, file, row, p):
        mode = self.rng.randrange(3)
        if mode == 0:
            vol = self.rng.choice(["FIN01", "FIN02"])
            c = self.consumer(vol)
            if not c:
                return None
            self.audit_exclusions.append(c["rec_id"])
            self.last_row = {"rec_id": c["rec_id"]}
            self.audit_rows.append(self.last_row)
            return ("T14", "audit-scope-letter-fin.pdf exclusions void FIN records", [c["rec_id"]])
        if mode == 1:
            decoys = [x for x in self.rows["inv_fin01_q3_r2.csv"] if not x.get("trapped")]
            d = self.rng.choice(decoys)
            src = self.rec_by_id.get(d.get("mirror_of"))
            self.audit_exclusions.append(d["rec_id"])
            self.last_row = {"rec_id": d["rec_id"]}
            self.audit_rows.append(self.last_row)
            return ("T13", "an exclusion naming a decoy row leaves the real row alone",
                    [d["rec_id"]] + ([src["rec_id"]] if src else []))
        c = self.consumer("FIN02")
        if not c:
            return None
        self.last_row = {"rec_id": c["rec_id"], "status": "withdrawn"}
        self.audit_rows.append(self.last_row)
        return ("T6", "withdrawn audit exclusions do not void", [c["rec_id"]])

    def k_class_boundary(self, file, row, p):
        vol = self.rng.choice(["ENG01", "OPS01", "LAB01", "FIN02"])
        days = self.rng.choice([30, 31, 90, 91, 180, 181])
        cls_ext = {30: "scratch", 31: "scratch", 90: "build", 91: "build", 180: "log", 181: "log"}[days]
        if cls_ext == "scratch":
            rest = "scratch/" + self._name(vol, ext="dat")
        elif cls_ext == "build":
            rest = "build/" + self._name(vol, ext="o")
            top = self.rng.choice(self._usable_tops(vol, "AEDBCF"))
            self.rules_overlay.append({"seq": 10**6 + len(self.rules_overlay), "scope": vol,
                                       "pattern": top["prefix"] + "build/", "class": "build"})
            c = self.consumer(vol, top=top, rest=rest, mtime=self.win_end - days * DAY)
            self.last_row = self.rules_overlay[-1]
            return ("T11", "retention-schedule-2026-r2.docx class ages: purge only when age exceeds", [c["rec_id"]]) if c else None
        else:
            rest = "logs/" + self._name(vol, ext="log")
        c = self.consumer(vol, rest=rest, mtime=self.win_end - days * DAY)
        self.last_row = {"cls": cls_ext}
        return ("T11", "retention-schedule-2026-r2.docx class ages: purge only when age exceeds", [c["rec_id"]]) if c else None

    def k_noarc(self, file, row, p):
        c = self.consumer("ARC01", rest="tmp/" + self._name("ARC01", ext="tmp"), mtime=self.win_end - 900 * DAY)
        if not c:
            return None
        self.last_row = {"note": "ARC01"}
        return ("T14", "retention-schedule-2026-r2.docx footnote: nothing on ARC01 is purged", [c["rec_id"]])

    def k_d10_class(self, file, row, p):
        vol = self.rng.choice(["ENG01", "OPS01", "LAB01"])
        c = self.consumer(vol, rest="src/" + self._name(vol, ext="tmp"), mtime=self.win_end - 10 * DAY)
        if not c:
            return None
        self.d10_rows[1]["max"] = 14
        self.last_row = self.d10_rows[1]
        return ("T16", "the r3 draft class ages are not in force", [c["rec_id"]])

    def k_ext_e(self, file, row, p):
        if row.get("trapped") or row["part"] != "E" or row["ext"] in self.common_exts:
            return None
        row["trapped"] = True
        self.ext_rows["A"].append({"ext": row["ext"], "family": "TMP", "rev": 1, "status": "active", "part": "A"})
        vol = self.rng.choice(["ENG01", "FIN01", "OPS01"])
        c = self.consumer(vol, rest="src/" + self._name(vol, ext=row["ext"]), mtime=self.win_end - 40 * DAY)
        self.last_row = row
        return ("T7", "ECS 7.2 table precedence A > B > C > D > E", [c["rec_id"]]) if c else None

    def k_void_fmt(self, file, row, p):
        return self.k_fmt(file, row, p)

    def _pad(self):
        r = self.rng
        n = self.N
        for part in ("A", "B"):
            k = 0
            while sum(1 for m in self.merges if m["part"] == part) < n:
                k += 1
                self.merges.append({"merge_id": f"MRG-H{part}{k:05d}", "from": f"P9{k:06d}{part}", "to": r.choice(self.pids),
                                    "effective": self.prev_start - r.randrange(DAY, 2000 * DAY),
                                    "status": r.choice(["applied", "reverted"]), "rev": 1, "part": part})
        for part in VOID_FILES:
            k = 0
            while len(self.void_rows[part]) < n:
                k += 1
                self.void_seq += 1
                self.void_rows[part].append({"void_id": f"VD-{self.void_seq:06d}", "rec_id": f"H{part}{k:02d}-{k:06d}",
                                             "ticket": self.old_ticket(), "status": "active", "rev": 1,
                                             "part": part, "reason": "prior period"})
        for part in ERRATA_FILES:
            k = 0
            while len(self.errata_rows[part]) < n:
                k += 1
                self.err_seq += 1
                self.errata_rows[part].append({"errata_id": f"ER-{self.err_seq:06d}", "rec_id": f"H{part}{k:02d}-{k:06d}",
                                               "field": r.choice(["bytes", "mtime", "owner", "sha256"]),
                                               "value": str(r.randrange(10**6)), "rev": 1,
                                               "ticket": self.old_ticket(), "part": part})
        for part in HOLD_FILES:
            k = 0
            while len(self.hold_rows[part]) < n:
                k += 1
                vol = r.choice(list(VOL))
                self.add_hold(vol, f"/zz-closed-{part}{k:05d}/{r.choice(WORDS)}", self.prev_start - r.randrange(DAY, 900 * DAY),
                              None if r.random() < 0.5 else self.prev_start, part=part)
        k = 0
        while len(self.hold_releases) < n:
            k += 1
            self.hold_releases.append({"hold_id": f"LH-9{k:05d}", "released": self.prev_start - r.randrange(DAY, 400 * DAY),
                                       "ticket": self.old_ticket()})
        k = 0
        while len(self.matters) < n:
            k += 1
            self.matters[f"M-H{k:05d}"] = r.choice(["open", "closed"])
        k = 0
        while len(self.audit_rows) < n:
            k += 1
            self.audit_rows.append({"rec_id": f"HF{k:02d}-{k:06d}"})
        k = 0
        while len(self.scope_overrides) < n:
            k += 1
            vol = r.choice(list(VOL))
            self.scope_overrides.append({"override_id": f"SO-H{k:05d}", "file": f"inv_{vol.lower()}_2025q{1 + k % 4}.csv",
                                         "volume": vol, "prefix": f"/zz-old-{k:05d}/", "ticket": self.old_ticket()})
        for part, rows in self.xwalk_rows.items():
            while len(rows) < n:
                alg = "sha1" if part.startswith("sha1") else "md5"
                rows.append({"digest": g_hex(r, 160 if alg == "sha1" else 128), "sha256": g_hex(r, 256), "status": "ok",
                             "rev": 1, "alg": alg, "origin": "ARC01" if part == "sha1V" else "pad"})
        while len(self.tickets) < n:
            self.ticket(r.random() < 0.75)
        while len(self.reinstatements) < n // 2:
            self.reinstatements.append({"rec_id": f"HR{len(self.reinstatements):06d}", "ticket": self.old_ticket(),
                                        "void_id": "VD-000000"})
        while len(self.revocations) < n // 2:
            self.revocations.append({"oid": f"OVR-H{len(self.revocations):05d}", "ticket": self.old_ticket()})
        while len(self.errata_withdrawals) < n // 2:
            self.errata_withdrawals.append({"errata_id": f"ER-H{len(self.errata_withdrawals):06d}", "ticket": self.old_ticket()})
        while len(self.incidents) < n:
            h = r.choice(sorted(self.hosts))
            t0 = self.prev_start - r.randrange(DAY, 900 * DAY)
            self.incidents.append({"host": h, "from": t0, "to": t0 + 3600 * r.randrange(1, 30),
                                   "skew": r.choice([-3600, 1800, 3600]), "adopted": r.random() < 0.7})
        while len(self.v4_withdrawals) < 40:
            self.v4_withdrawals.append({"seq": 10**7 + len(self.v4_withdrawals), "ticket": self.ticket(True)})
        while len(self.ext_corrections) < n:
            self.ext_corrections.append({"ext": f"zq{len(self.ext_corrections):05d}", "family": r.choice(FAMILIES),
                                         "applies": False})
        self.ratification = [
            {"document": "retention_rules", "version": "v3", "ticket": self.ticket(True)},
            {"document": "retention_rules", "version": "v4", "ticket": self.ticket(False)},
            {"document": "retention-schedule-2026", "version": "r2", "ticket": self.ticket(True)},
            {"document": "retention-schedule-2026", "version": "r3", "ticket": self.ticket(False)},
            {"document": "ECS-annex-hosts", "version": "rev6", "ticket": self.ticket(True)},
            {"document": "ECS-annex-hosts", "version": "rev7", "ticket": self.ticket(False)},
            {"document": "ECS-annex-hosts", "version": "rev7-appendix-D", "ticket": self.ticket(True)},
            {"document": "site-policy", "version": "v1", "ticket": self.ticket(True)},
            {"document": "site-policy", "version": "v2", "ticket": self.ticket(False)},
        ]

    def _index_more(self):
        best = {}
        for inc in self.incidents:
            k = (inc["host"], inc["from"])
            if k not in best or inc.get("rev", 1) > best[k].get("rev", 1):
                best[k] = inc
        self.incidents_eff = [v for v in best.values() if v["adopted"]]
        self.inc_by_host = {}
        for v in self.incidents_eff:
            self.inc_by_host.setdefault(v["host"], []).append(v)
        corr = {}
        for c in self.ext_corrections:
            if c.get("applies"):
                k = c["ext"]
                if k not in corr or c.get("rev", 1) > corr[k].get("rev", 1):
                    corr[k] = c
        for row in self.ext_rows["A"]:
            if row.get("pending") and row["ext"] in corr:
                row["family_eff"] = corr[row["ext"]]["family"]
        cfgp = self.effective_config("prod")
        for f, rows in (("arc01_ltfs_index.db", self.rows["arc01_ltfs_index.db"]),):
            for x in rows:
                raw = self.raw_path(x)
                x["raw_path"] = raw
                vol, cp = self.resolve_path(raw, cfgp)
                if cp is not None and x["file_id"]:
                    self.ltfs_fid[cp] = x["file_id"]

    def _assign(self, ev, prior_keys, next_id):
        ids = {}
        new = []
        for e in ev["entries"]:
            k = (e["vol"], e["path"])
            if k in prior_keys:
                ids[k] = prior_keys[k]
            else:
                new.append(k)
        nid = next_id
        for k in sorted(new):
            ids[k] = nid
            nid += 1
        for e in ev["entries"]:
            e["entry_id"] = ids[(e["vol"], e["path"])]
        ev["new_keys"] = set(new)

    def _post_eval(self):
        r = self.rng
        prod = self.truth["prod"]
        cur = [(e["vol"], e["path"]) for e in prod["entries"]]
        self.prior_rows = []
        used_ids = set()
        nid = 10**6 + r.randrange(10**5)
        for e in prod["entries"]:
            if r.random() < 0.7:
                nid += r.randrange(1, 4)
                diff = r.random() < 0.05
                row = {"entry_id": nid, "volume": e["vol"], "path": e["path"],
                       "sha256": g_hex(r, 256) if diff else e["sha"], "bytes": e["bytes"] + (r.randrange(1, 999) if diff else 0),
                       "owner": e["owner"], "status": "live"}
                self.prior_rows.append(row)
                used_ids.add(nid)
        for k in range(len(cur) // 10):
            nid += r.randrange(1, 4)
            vol = r.choice(list(VOL))
            self.prior_rows.append({"entry_id": nid, "volume": vol, "path": f"/{VOL[vol][3]}-gone/{r.choice(WORDS)}-{k:05d}.dat",
                                    "sha256": g_hex(r, 256), "bytes": r.randrange(10**7), "owner": r.choice(self.pids),
                                    "status": "live"})
        self.prior_next_id = nid + r.randrange(5, 50)
        self._plant_prior()
        live = {}
        for row in self.prior_rows:
            if row["status"] == "live" and row["volume"] in VOL:
                live[(row["volume"], row["path"])] = row["entry_id"]
        self.prior_live = live
        self.prior_open = {"entries": len(live), "logical_bytes": sum(rw["bytes"] for rw in self.prior_rows
                                                                      if rw["status"] == "live" and rw["volume"] in VOL),
                           "store_bytes": r.randrange(10**14, 10**15)}
        shas = []
        seen = set()
        for e in prod["entries"]:
            if e["sha"] not in seen:
                seen.add(e["sha"])
                shas.append(e["sha"])
        r.shuffle(shas)
        present = shas[: len(shas) * 2 // 5]
        parts = list(STORE_FILES)
        for i, s in enumerate(present):
            self.store_rows[parts[i % 4]].append({"sha256": s, "status": "present", "rev": 1, "part": parts[i % 4],
                                                  "stored_bytes": r.randrange(10**9)})
        self._plant_store(shas)
        for part in parts:
            while len(self.store_rows[part]) < self.N:
                self.store_rows[part].append({"sha256": g_hex(r, 256), "status": r.choice(["present", "evicted"]), "rev": 1,
                                              "part": part, "stored_bytes": r.randrange(10**9)})
        best = {}
        for part in parts:
            for row in self.store_rows[part]:
                k = row["sha256"].lower()
                if k not in best or row["rev"] > best[k]["rev"]:
                    best[k] = row
        self.store_present = {k for k, v in best.items() if v["status"] == "present"}
        for prof in ("prod", "dev"):
            self._assign(self.truth[prof], self.prior_live, self.prior_next_id)

    def _plant_prior(self):
        r = self.rng
        file = "estate_manifest_q2.parquet"
        n = len(self.prior_rows)
        slots = self._schedule(n, True)
        for p in slots:
            row = self.prior_rows[p]
            if row.get("trapped") or row["volume"] not in VOL:
                continue
            key = (row["volume"], row["path"])
            origin = next((e["origin"] for e in self.truth["prod"]["entries"] if (e["vol"], e["path"]) == key), None)
            row["trapped"] = True
            mode = r.randrange(6)
            fam = ["T16", "T1", "T6", "T7", "T13", "T11"][mode]
            if mode == 0:
                row["sha256"] = g_hex(r, 256)
                row["bytes"] += 7
            elif mode == 1:
                row["path"] = row["path"].upper() if VOL[row["volume"]][2] == "sensitive" else row["path"] + "/"
            elif mode == 2:
                row["status"] = "retired"
            elif mode == 3:
                self.prior_rows.append(dict(row, entry_id=row["entry_id"] + 10**7, status="retired", trapped=True))
            elif mode == 4:
                row["volume"] = "ARC00" if row["volume"] == "ARC01" else row["volume"].lower()
            else:
                pass
            recs = [origin] if origin else []
            if origin:
                self.rec_by_id[origin]["tags"] |= {fam, "D:" + file}
            self.trap(file, f"entry_id {row['entry_id']}", fam, "estate_manifest_q2.parquet supplies ids and opening only",
                      f"decoy:{file}", recs)

    def _plant_store(self, shas):
        r = self.rng
        by_sha = {}
        for e in self.truth["prod"]["entries"]:
            by_sha.setdefault(e["sha"], []).append(e["origin"])
        for part, file in STORE_FILES.items():
            rows = self.store_rows[part]
            slots = self._schedule(max(len(rows), self.N), False)
            for i, p in enumerate(slots):
                s = r.choice(shas)
                mode = i % 6
                srev = max([x["rev"] for q in self.store_rows.values() for x in q if x["sha256"].lower() == s] or [0])
                n_before = len(rows)
                if mode == 0:
                    rows.append({"sha256": s, "status": "present", "rev": 1, "part": part, "stored_bytes": 1})
                    rows.append({"sha256": s, "status": "evicted", "rev": 2, "part": part, "stored_bytes": 1})
                    fam = "T6"
                elif mode == 1:
                    rows.append({"sha256": s, "status": "evicted", "rev": 1, "part": part, "stored_bytes": 1})
                    rows.append({"sha256": s, "status": "present", "rev": 3, "part": part, "stored_bytes": 1})
                    fam = "T7"
                elif mode == 2:
                    rows.append({"sha256": s.upper(), "status": "present", "rev": 1, "part": part, "stored_bytes": 1})
                    fam = "T1"
                elif mode == 3:
                    rows.append({"sha256": s, "status": "present", "rev": 1, "part": part, "stored_bytes": 1,
                                 "enc_trap": True})
                    fam = "T10"
                elif mode == 4:
                    rows.append({"sha256": s, "status": "present", "rev": 1, "part": part,
                                 "stored_bytes": r.randrange(10**12, 10**13)})
                    fam = "T15"
                else:
                    rows.append({"sha256": s, "status": "present", "rev": 1, "part": part, "stored_bytes": 0,
                                 "delim_trap": True})
                    fam = "T9"
                for x in rows[n_before:]:
                    x["rev"] += srev
                self.trap(file, f"sha256 {s[:12]}", fam, "ECS 6.5 prior store index: highest revision, present only",
                          "concept:C6", by_sha.get(s, [])[:2])

    def _finalize(self):
        for prof in ("prod", "dev"):
            ev = self.truth[prof]
            bs = ev["bs"]
            seen = set()
            new_store = 0
            for e in ev["entries"]:
                if e["sha"] in seen:
                    continue
                seen.add(e["sha"])
                if e["sha"] in self.store_present:
                    continue
                new_store += -(-e["bytes"] // bs) * bs
            carried = sum(1 for e in ev["entries"] if (e["vol"], e["path"]) in self.prior_live)
            keys = {(e["vol"], e["path"]) for e in ev["entries"]}
            retired = sum(1 for k in self.prior_live if k not in keys)
            vols = {}
            for e in ev["entries"]:
                v = vols.setdefault(e["vol"], [0, 0])
                v[0] += 1
                v[1] += e["bytes"]
            exc = {}
            for _rid, (_x, reason) in ev["outcome"].items():
                exc[reason] = exc.get(reason, 0) + 1
            ev["ledger"] = {
                "opening": dict(self.prior_open),
                "movement": {"carried": carried, "new": len(ev["entries"]) - carried, "retired": retired},
                "closing": {"entries": len(ev["entries"]), "logical_bytes": sum(e["bytes"] for e in ev["entries"]),
                            "store_bytes": self.prior_open["store_bytes"] + new_store,
                            "id_hash_total": sum(e["entry_id"] for e in ev["entries"]) % 1000000007},
                "volumes": [{"volume": v, "entries": c[0], "logical_bytes": c[1]} for v, c in sorted(vols.items())],
                "exceptions": dict(sorted(exc.items())),
            }

    def _controls(self):
        r = self.rng
        order = list(FILE_NAMES)
        r.shuffle(order)
        self.chain = order
        self.ctl = {}
        self.prior_ctl = f"CTL-{r.getrandbits(24):06X}"
        prev = self.prior_ctl
        for f in order:
            cid = f"CTL-{r.getrandbits(24):06X}"
            while cid in {c["id"] for c in self.ctl.values()} or cid == self.prior_ctl:
                cid = f"CTL-{r.getrandbits(24):06X}"
            self.ctl[f] = {"id": cid, "prev": prev}
            prev = cid

    def build(self):
        self._period()
        self._tickets()
        self._zones_hosts()
        self._principals()
        self._aliases()
        self._exts_rules()
        self._batches()
        self._config()
        self._contents()
        self._authority()
        self._refs_init()
        self.audit_rows = []
        self.last_row = None
        self.trap_objs = {}
        self._ref_tables()
        self._entries()
        self._journals()
        self._plant()
        self._pad()
        self._index_all()
        self._errata_index()
        self._void_index()
        self._hold_index()
        self._index_more()
        self._index_all()
        self.truth = {p: self._evaluate(p) for p in ("prod", "dev")}
        if self._precedence_pairs():
            self._void_index()
            self.truth = {p: self._evaluate(p) for p in ("prod", "dev")}
        self._post_eval()
        self._finalize()
        self._controls()
        self._plant_foreign_exclusion()
        return self

    def _precedence_pairs(self):
        """Give records a second ECS 9 reason so each adjacent pair of the order decides an outcome."""
        size_sent = {"inv_eng01_q3.csv": "-1", "inv_eng02_q3.txt": "?", "inv_hr01_q3.xlsx": "9999",
                     "inv_obj01_q3_r2.csv": "-1", "arc01_tape_catalog.txt": "*******", "rnd01_cold_listing.pdf": "-",
                     "inv_ops01_q3.tsv": "-", "inv_rnd01_q3.json": "", "inv_lab01_q3.jsonl": "",
                     "inv_mkt01_q3.jsonl": "", "inv_leg01_q3.xml": "", "inv_fin02_q3.tsv": ""}
        owner_sent = {"sid": "S-1-0-0", "email": "nobody@corp.example", "corp": "CORP\\-", "oldcorp": "OLDCORP\\-",
                      "legacy": "-", "s3": "0" * 64, "svc": "svc-none", "mf": "MF?????"}
        digest_len = {"sha256": 64, "md5": 32, "md5b64": 32, "etag": 32, "sha1": 40}

        def add_void(rec):
            self.add_void(rec["rec_id"], part="A")
            return "T6"

        def add_size(rec):
            if rec["file"] not in size_sent:
                return None
            rec["size"] = ("sentinel", size_sent[rec["file"]])
            return "T5"

        def add_hash(rec):
            rec["hash"] = ("sentinel", "0" * digest_len[SOURCE_HASH[rec["file"]]])
            return "T5"

        def add_owner(rec):
            ns = (rec.get("owner") or ("",))[0]
            if ns not in owner_sent:
                return None
            rec["owner"] = ("sentinel", owner_sent[ns])
            return "T5"

        plan = {"SUPERSEDED_SCOPE": add_void, "NOT_A_FILE": add_void, "PATH_UNRESOLVED": add_size,
                "SIZE_UNKNOWN": add_hash, "HASH_UNRESOLVED": add_owner}
        done = {k: 0 for k in plan}
        prod, dev = self.truth["prod"]["outcome"], self.truth["dev"]["outcome"]
        for rec in sorted(self.recs, key=lambda r: r["rec_id"]):
            o = prod.get(rec["rec_id"])
            if rec["kind"] != "inv" or rec["file"] in DECOYS or o is None or dev.get(rec["rec_id"]) != o:
                continue
            reason = o[-1]
            if reason not in plan or done[reason] >= 2:
                continue
            fam = plan[reason](rec)
            if fam:
                rec["tags"].add(fam)
                done[reason] += 1
        planted = self._plant_scope_pair(prod, dev) if self.small else False
        triggers = self._plant_rule_triggers(prod, dev) if self.small else False
        return any(done.values()) or planted or triggers

    def _plant_scope_pair(self, prod, dev):
        """Put one OUT_OF_AUTHORITY record under another export's approved override (ECS 9 OOA before SUPERSEDED_SCOPE)."""
        cfg = self.effective_config("prod")
        for rec in sorted(self.recs, key=lambda r: r["rec_id"]):
            f = rec["file"]
            if rec["kind"] != "inv" or self.self_mode.get(f) in (None, "full", "continuation"):
                continue
            o = prod.get(rec["rec_id"])
            if o is None or o[-1] != "OUT_OF_AUTHORITY" or dev.get(rec["rec_id"]) != o:
                continue
            path = self._resolve(rec, cfg)["path"]
            subject = next((x for x, v in INVENTORY_FILES.items() if v == rec["vol"] and self.self_mode.get(x) == "full"),
                           None)
            if not path or subject is None:
                continue
            self.scope_overrides.append({"override_id": "SO-P00001", "file": subject, "volume": rec["vol"],
                                         "prefix": "/" + path.strip("/").split("/")[0], "ticket": self.ticket(True)})
            rec["tags"].add("T7")
            return True
        return False

    def _plant_rule_triggers(self, prod, dev):
        """Eval tier only (no rng, no new rows): give five ECS rules an input whose outcome only they decide.

        ECS 5.3 empty, . and .. segments plus a .. above the root; ECS 4.3 a wall-clock time inside a spring-forward
        gap; ECS 6.4 a duplicate pair whose batches share captured_utc; ECS 8 a RESTORE after two deletions of its
        path; ECS 8 an OBJ01 sequencer written with a leading zero, so byte order and value order disagree.
        """
        outs = (prod, dev)
        cfgs = [self.effective_config(p) for p in ("prod", "dev")]
        res, users = ({}, {}), ({}, {})
        for rec in self.recs:
            if all(o.get(rec["rec_id"], ("",))[-1] == "OUT_OF_AUTHORITY" for o in outs):
                continue
            for i, cfg in enumerate(cfgs):
                x = res[i][rec["rec_id"]] = self._resolve(rec, cfg)
                for pth in {x["path"], x["newpath"]} - {None}:
                    users[i].setdefault((x["vol"], pth), []).append(rec)

        def key(rec, i):
            x = res[i].get(rec["rec_id"])
            return None if x is None else (x["vol"], x["path"])

        def near(rec):  # the records reaching rec's canonical path in each profile, rec included
            return [users[i].get(key(rec, i), []) for i in (0, 1)]

        def ok(rec):  # an entry origin (inventory) or an applied event, in both profiles
            return all(rec["rec_id"] not in o for o in outs)

        def free(rec):
            return (not rec["tags"] and not rec.get("trapped") and not rec["flags"] and "root_variant" not in rec
                    and rec["file"] not in DECOYS and rec["rec_id"] in res[0] and rec["rec_id"] in res[1])

        def scoped(rec):
            return any(o["volume"] == rec["vol"] and res[i][rec["rec_id"]]["path"]
                       and self.under(res[i][rec["rec_id"]]["path"], o["prefix"]) for o in self.scope_overrides for i in (0, 1))

        planted = 0
        # ECS 5.3: one UNC path through empty, . and .. segments (same canonical path); one posix .. above the root.
        want = {"\\": None, "/": None}
        for rec in sorted(self.rows["inv_eng01_q3.csv"] + self.rows["inv_lab01_q3.jsonl"], key=lambda r: r["rec_id"]):
            lead = rec.get("raw_path", "")[:1]
            head, _, tail = rec["rest"].partition("/")
            if (lead not in want or want[lead] is not None or not tail or rec["kind"] != "inv" or not free(rec)
                    or not ok(rec) or rec["nlink"] != 1 or scoped(rec) or any(len(u) != 1 for u in near(rec))):
                continue
            rest = f"{head}//./{SUBDIRS[0]}/../{tail}" if lead == "\\" else f"../{rec['rest']}"
            raw = self.raw_path(dict(rec, rest=rest))
            got = [self.resolve_path(raw, cfg) for cfg in cfgs]
            if got != ([key(rec, 0), key(rec, 1)] if lead == "\\" else [(None, None)] * 2):
                continue
            rec["raw_path"] = raw
            rec["tags"].add("T1")
            want[lead] = rec
            rule = ("ECS 5.3 canonical form: empty and . segments are dropped, .. removes the previous segment"
                    if lead == "\\" else "ECS 5.3 canonical form: a .. above the root leaves the path unresolved")
            self.trap(rec["file"], rec["rec_id"], "T1", rule, "family:T1", [rec["rec_id"]])
            planted += 1
        # ECS 4.3: a local wall-clock time that no segment of the zone maps (spring-forward gap).
        for rec in sorted(self.rows["inv_ops01_q3.tsv"], key=lambda r: r["rec_id"]):
            zones = {self.vol_zone(rec["vol"], cfg) for cfg in cfgs}
            if (rec["kind"] != "inv" or TIME_DIALECT[rec["file"]] != "local" or not free(rec) or not ok(rec)
                    or scoped(rec) or len(zones) != 1):
                continue
            if any(self.classes[e["class"]][0] is not None for p in ("prod", "dev") for e in self.truth[p]["entries"]
                   if e["origin"] == rec["rec_id"]):
                continue  # mtime decides no purge here, so the record stays an entry whose mtime is graded
            zone = zones.pop()
            segs = self.tz_segments[zone]
            gaps = [(b[0] + a[2], b[0] + b[2]) for a, b in zip(segs, segs[1:]) if b[2] > a[2]]
            gaps = [g for g in gaps if g[0] <= self.utc_to_local(zone, rec["time"][1])]
            if not gaps:
                continue
            lo, hi = gaps[-1]
            local = lo + (hi - lo) // 3 + 7
            if any(s <= local - off < e for s, e, off, _d in segs):
                continue
            rec["time"] = ("utc", local - self.zones[zone]["std"])
            rec["time_raw"] = g_local_str(local)
            rec["tags"].add("T3")
            self.trap(rec["file"], rec["rec_id"], "T3", "ECS 4.3 a wall-clock time in a spring-forward gap reads with the "
                      "standard offset", "family:T3", [rec["rec_id"]])
            planted += 1
            break
        # ECS 6.4: one duplicate pair of the later-capture fixture gets equal captured_utc; the greater id wins.
        for t in list(self.traps):
            a, b = (self.rec_by_id.get(x) for x in (t["recs"] + [None, None])[:2])
            if ("later batch capture wins" not in t["rule"] or len(t["recs"]) != 2 or a is None or b is None
                    or a["file"] != b["file"] or a["tags"] != {"T11"} or b["tags"] != {"T11"} or b["rec_id"] < a["rec_id"]
                    or a["batch"] == b["batch"] or any(c["batch"] == b["batch"] for c in self.batch_conflicts)
                    or not ok(b) or any(o.get(a["rec_id"]) != ("X", "DUPLICATE_PATH") for o in outs)
                    or any(len(u) != 2 or all(y is not a for y in u) for u in near(b))):
                continue
            bat = self.batches[b["batch"]]
            row = next(x for x in self.batch_rows[bat["part"]] if x["batch"] == b["batch"])
            bat["captured"] = row["captured"] = self.batch_eff_captured(a["batch"])
            self.trap(BATCH_FILES[bat["part"]], b["batch"], "T11", "ECS 6.4 duplicate canonical paths: equal batch "
                      "captured_utc goes to the greater record id", "family:T11", [a["rec_id"], b["rec_id"]])
            planted += 1
            break
        # ECS 8: CREATE and DELETE of a RESTORE's path between its deletion and the RESTORE (two deleted entries).
        jr = [r for r in self.recs if r["kind"] == "jrn" and r["vol"] not in ("MKT01", "OBJ01") and free(r) and ok(r)]

        def lone_delete(r):
            for u in near(r):
                inv = [x for x in u if x is not r]
                if len(inv) != 1 or inv[0]["kind"] != "inv" or any(o.get(inv[0]["rec_id"]) != ("X", "DELETED") for o in outs):
                    return False
            return True

        for rst in sorted(jr, key=lambda r: r["rec_id"]):
            same = near(rst)
            if rst["op"] != "RESTORE" or [id(x) for x in same[0]] != [id(x) for x in same[1]]:
                continue
            dels = [r for r in same[0] if r["kind"] == "jrn" and r["op"] == "DELETE" and r["seq"] < rst["seq"] and ok(r)]
            if not dels:
                continue
            dl = max(dels, key=lambda r: r["seq"])
            if any(r is not rst and r["kind"] == "jrn" and r["seq"] > dl["seq"] for r in same[0]):
                continue
            pool = sorted((r for r in jr if r["file"] == rst["file"] and dl["seq"] < r["seq"] < rst["seq"]),
                          key=lambda r: r["seq"])
            c = next((r for r in pool if r["op"] == "CREATE" and all(len(u) == 1 for u in near(r))), None)
            x = c and next((r for r in pool if r["op"] == "DELETE" and r["seq"] > c["seq"] and lone_delete(r)), None)
            if not x:
                continue
            for ev in (c, x):
                ev["top"], ev["rest"], ev["root"], ev["raw_path"] = rst["top"], rst["rest"], rst["root"], rst["raw_path"]
                ev["tags"].add("T13")
            rst["tags"].add("T13")
            self.trap(rst["file"], rst["rec_id"], "T13", "ECS 8 RESTORE brings back the most recently deleted entry of "
                      "its path", "family:T13", [c["rec_id"], x["rec_id"], rst["rec_id"]])
            planted += 1
            break
        # ECS 8: an OBJ01 DELETE whose sequencer has a leading zero sorts first by bytes, after its CREATE by value.
        for d in sorted((r for r in self.recs if r["kind"] == "jrn" and r["vol"] == "OBJ01"), key=lambda r: r["seq"]):
            same = near(d) if d["op"] == "DELETE" and free(d) and ok(d) else [[], []]
            if any(len(u) != 2 for u in same):
                continue
            c = next(r for r in same[0] if r is not d)
            if (all(y is not c for y in same[1]) or c["kind"] != "jrn" or c["op"] != "CREATE" or c["seq"] >= d["seq"] or not free(c)
                    or any(o.get(c["rec_id"]) != ("X", "DELETED") for o in outs)):
                continue
            d["seq_hex"] = f"0{d['seq']:X}"
            for ev in (c, d):
                ev["tags"].add("T3")
            self.trap(d["file"], d["rec_id"], "T3", "ECS 8 OBJ01 sequencers are hexadecimal numbers compared by value",
                      "family:T3", [c["rec_id"], d["rec_id"]])
            planted += 1
            break
        return planted > 0

    def k_casedup_inplace(self, file, rec, p):
        return self.k_casedup(file, rec, p, inplace=True)

    def _plant_foreign_exclusion(self):
        """Name one kept non-finance record in the finance audit letter, over a padding row (no rng, row count kept).

        The letter's prose limits it to finance volumes, so the record stays an entry; a tool that voids every listed
        id turns it into VOIDED and fails C1, C10 and the T14 family on this tier.
        """
        kept = {e["origin"] for e in self.truth["prod"]["entries"]} & {e["origin"] for e in self.truth["dev"]["entries"]}
        cands = sorted(rid for rid in kept if self.rec_by_id[rid]["kind"] == "inv" and not self.rec_by_id[rid]["tags"]
                       and self.rec_by_id[rid]["vol"] not in ("FIN01", "FIN02") and self.rec_by_id[rid]["file"] not in DECOYS)
        if not cands:
            return
        row = next((a for a in self.audit_rows if a["rec_id"].startswith("HF")), None)
        if row is None:
            row = {}
            self.audit_rows.append(row)
        row.clear()
        row["rec_id"] = cands[0]
        self.rec_by_id[cands[0]]["tags"].add("T14")
        self.trap("audit-scope-letter-fin.pdf", cands[0], "T14", "audit-scope-letter-fin.pdf applies to finance volumes only",
                  "family:T14", [cands[0]])


