ZW = "\u200b"
BOMCH = "\ufeff"
FIXED_ZIP_TIME = (1980, 1, 1, 0, 0, 0)


def r_noise(s: str) -> str:
    return BOMCH + s + ZW if s else s


def r_nfd(s: str) -> str:
    return unicodedata.normalize("NFD", s)


def r_delim_note(fmt: str) -> str:
    return {"csv": 'Smith, "J." (ops); see p.4', "tsv": "ops\tteam\nnight shift",
            "pdf": "a | b | c", "md": "a | b", "fixed": "note", "xml": "<ops & admin>",
            "html": "<ops & admin>", "json": 'quote " and \\ slash', "jsonl": 'quote " and , comma',
            "yaml": "key: value, - dash # hash", "toml": 'quote " and \\ back', "ini": "100% ; semi # hash",
            "xlsx": "line one\nline two", "docx": "tab\there", "parquet": "a,b|c\td", "sqlite": "a,b|c\td",
            "ics": "a,b;c\\d", "log": 'say "hi"'}.get(fmt, "x, y")


def r_pdf_text(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ord(ch) < 256 and ch not in "\r\n\t":
            out.append(ch)
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\n":
            out.append("\\n")
        else:
            out.append(f"\\u{ord(ch):04x}" if ord(ch) < 0x10000 else f"\\U{ord(ch):08x}")
    return "".join(out)


def r_pdf_bytes(lines: list[str], title: str) -> bytes:
    """Minimal multi-page PDF (Courier 7pt, WinAnsi), one text line per table row."""
    per_page = 78
    pages = [lines[i:i + per_page] for i in range(0, len(lines), per_page)] or [[]]
    objs = []
    font_id = 3
    page_ids = []
    content_ids = []
    nxt = 4
    for _ in pages:
        page_ids.append(nxt)
        content_ids.append(nxt + 1)
        nxt += 2
    kids = " ".join(f"{p} 0 R" for p in page_ids)
    objs.append((1, b"<< /Type /Catalog /Pages 2 0 R >>"))
    objs.append((2, f"<< /Type /Pages /Kids [{kids}] /Count {len(pages)} >>".encode()))
    objs.append((3, b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>"))
    for pi, plines in enumerate(pages):
        buf = io.BytesIO()
        buf.write(b"BT /F1 7 Tf 8 TL 24 820 Td\n")
        for ln in plines:
            esc = ln.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")
            buf.write(b"(" + esc.encode("cp1252", errors="replace") + b") Tj T*\n")
        buf.write(b"ET\n")
        data = zlib.compress(buf.getvalue(), 9)
        objs.append((page_ids[pi], f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 842] /Resources << /Font << /F1 {font_id} 0 R >> >> /Contents {content_ids[pi]} 0 R >>".encode()))
        objs.append((content_ids[pi], b"<< /Length " + str(len(data)).encode() + b" /Filter /FlateDecode >>\nstream\n" + data + b"\nendstream"))
    objs.sort()
    out = io.BytesIO()
    out.write(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = {}
    for oid, body in objs:
        offsets[oid] = out.tell()
        out.write(f"{oid} 0 obj\n".encode() + body + b"\nendobj\n")
    info_id = len(objs) + 1
    offsets[info_id] = out.tell()
    t = title.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")
    out.write(f"{info_id} 0 obj\n<< /Title ({t}) /Producer (estate-docs) >>\nendobj\n".encode("latin-1", "replace"))
    xref = out.tell()
    n = info_id + 1
    out.write(f"xref\n0 {n}\n0000000000 65535 f \n".encode())
    for i in range(1, n):
        out.write(f"{offsets[i]:010d} 00000 n \n".encode())
    out.write(f"trailer\n<< /Size {n} /Root 1 0 R /Info {info_id} 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode())
    return out.getvalue()


def r_zip(members: list[tuple[str, bytes]]) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for name, data in members:
            info = zipfile.ZipInfo(name, date_time=FIXED_ZIP_TIME)
            info.external_attr = 0o100644 << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            zf.writestr(info, data)
    return buf.getvalue()


def r_col_letter(i: int) -> str:
    s = ""
    i += 1
    while i:
        i, rem = divmod(i - 1, 26)
        s = chr(65 + rem) + s
    return s


def r_xlsx(sheets: list[tuple[str, list[list]]], subject: str, description: str, date1904: bool = False) -> bytes:
    members = []
    ct = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
          '<Default Extension="xml" ContentType="application/xml"/>',
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
          '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>']
    for i in range(len(sheets)):
        ct.append(f'<Override PartName="/xl/worksheets/sheet{i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>')
    ct.append("</Types>")
    members.append(("[Content_Types].xml", "".join(ct).encode()))
    members.append(("_rels/.rels", ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                                    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                                    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                                    '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
                                    '</Relationships>').encode()))
    members.append(("docProps/core.xml", ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                                          '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
                                          'xmlns:dc="http://purl.org/dc/elements/1.1/">'
                                          f"<dc:subject>{_x(subject)}</dc:subject><dc:description>{_x(description)}</dc:description>"
                                          "</cp:coreProperties>").encode()))
    wb = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">',
          f'<workbookPr date1904="{"1" if date1904 else "0"}"/><sheets>']
    rels = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">']
    for i, (name, _rows) in enumerate(sheets):
        wb.append(f'<sheet name="{_x(name)}" sheetId="{i + 1}" r:id="rId{i + 1}"/>')
        rels.append(f'<Relationship Id="rId{i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{i + 1}.xml"/>')
    wb.append("</sheets></workbook>")
    rels.append("</Relationships>")
    members.append(("xl/workbook.xml", "".join(wb).encode()))
    members.append(("xl/_rels/workbook.xml.rels", "".join(rels).encode()))
    for i, (_name, rows) in enumerate(sheets):
        parts = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
                 '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>']
        for ri, row in enumerate(rows, start=1):
            cells = []
            for ci, v in enumerate(row):
                ref = f"{r_col_letter(ci)}{ri}"
                if v is None or v == "":
                    continue
                if isinstance(v, bool):
                    cells.append(f'<c r="{ref}" t="b"><v>{int(v)}</v></c>')
                elif isinstance(v, (int, float)):
                    cells.append(f'<c r="{ref}"><v>{v!r}</v></c>' if isinstance(v, float) else f'<c r="{ref}"><v>{v}</v></c>')
                else:
                    sv = str(v)
                    sp = ' xml:space="preserve"' if sv != sv.strip() or "\n" in sv else ""
                    cells.append(f'<c r="{ref}" t="inlineStr"><is><t{sp}>{_x(sv)}</t></is></c>')
            parts.append(f'<row r="{ri}">' + "".join(cells) + "</row>")
        parts.append("</sheetData></worksheet>")
        members.append((f"xl/worksheets/sheet{i + 1}.xml", "".join(parts).encode("utf-8")))
    return r_zip(members)


def r_docx(blocks: list, subject: str, title: str) -> bytes:
    """blocks: ("p", text) | ("h", text) | ("table", [header], [[cells]])"""
    W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
    body = []

    def para(text, style=None):
        ppr = f'<w:pPr><w:pStyle w:val="{style}"/></w:pPr>' if style else ""
        runs = []
        for k, seg in enumerate(str(text).split("\t")):
            if k:
                runs.append("<w:r><w:tab/></w:r>")
            runs.append(f'<w:r><w:t xml:space="preserve">{_x(seg)}</w:t></w:r>')
        return f"<w:p>{ppr}{''.join(runs)}</w:p>"

    for b in blocks:
        if b[0] == "p":
            body.append(para(b[1]))
        elif b[0] == "h":
            body.append(para(b[1], "Heading1"))
        else:
            _, header, rows = b
            t = ["<w:tbl><w:tblPr><w:tblStyle w:val=\"TableGrid\"/></w:tblPr>"]
            for row in [header] + rows:
                t.append("<w:tr>" + "".join(f"<w:tc>{para(c)}</w:tc>" for c in row) + "</w:tr>")
            t.append("</w:tbl>")
            body.append("".join(t))
    doc = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W}"><w:body>'
           + "".join(body) + "<w:sectPr/></w:body></w:document>")
    members = [
        ("[Content_Types].xml", ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                                 '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                                 '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                                 '<Default Extension="xml" ContentType="application/xml"/>'
                                 '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
                                 '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
                                 "</Types>").encode()),
        ("_rels/.rels", ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                         '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                         '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
                         '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
                         "</Relationships>").encode()),
        ("docProps/core.xml", ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                               '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
                               'xmlns:dc="http://purl.org/dc/elements/1.1/">'
                               f"<dc:title>{_x(title)}</dc:title><dc:subject>{_x(subject)}</dc:subject>"
                               "</cp:coreProperties>").encode()),
        ("word/document.xml", doc.encode("utf-8")),
    ]
    return r_zip(members)


class RenderMixin:
    # ------------------------------------------------------------------ shared helpers
    def r_rng(self, file):
        import random as _random
        return _random.Random(f"{self.seed}:{file}")

    def r_order(self, file, rows):
        objs = self.trap_objs.get(file, [])
        ids = {id(o) for o in objs}
        traps = []
        seen = set()
        for o in objs:
            if id(o) in seen:
                continue
            seen.add(id(o))
            for r in rows:
                if r is o:
                    traps.append(r)
                    break
        others = [r for r in rows if id(r) not in ids]
        n = len(rows)
        bands = max(1, -(-n // 500))
        rr = self.r_rng(file)
        slots = {}
        for b, t in enumerate(traps[:bands]):
            lo = b * 500
            hi = min(n, lo + 500)
            slots[rr.randrange(lo, hi)] = t
        extra = traps[bands:]
        for t in extra:
            others.insert(rr.randrange(len(others) + 1), t)
        out = []
        it = iter(others)
        for pos in range(n):
            if pos in slots:
                out.append(slots[pos])
            else:
                nxt = next(it, None)
                if nxt is not None:
                    out.append(nxt)
        out.extend(it)
        return out

    def r_ctl(self, file, rows):
        c = self.ctl[file]
        self.ctl_rows[file] = rows
        return {"ctl_id": c["id"], "prev": c["prev"], "rows": rows}

    def r_ctl_line(self, file, rows, lead="#ctl"):
        c = self.r_ctl(file, rows)
        return f"{lead} ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']}"

    def r_key(self, s, row, kind="generic"):
        if row.get("enc_trap"):
            s = r_noise(r_nfd(s))
        return s

    def r_note(self, row, fmt):
        if row.get("delim_trap"):
            return r_delim_note(fmt)
        return row.get("note") or ""

    def r_tok(self, ns, tok, variant, rec=None):
        if not variant:
            if ns == "uid" and rec is not None and rec.get("uid_alias"):
                _u, host, n = tok.split(":")
                return f"uid:{rec['uid_alias']}:{n}"
            return tok
        if ns == "sid":
            return tok.lower() + "  "
        if ns == "uid":
            _u, host, n = tok.split(":")
            h = rec["uid_alias"] if rec is not None and rec.get("uid_alias") else host.upper()
            return f"uid:{h}:{int(n):08d}"
        if ns in ("corp", "oldcorp", "legacy"):
            dom, _, login = tok.partition("\\")
            return f" {dom.lower()}\\{login.upper()} "
        if ns == "email":
            local, _, dom = tok.partition("@")
            return f"{local.upper()}+archive@{dom.upper()}"
        if ns == "s3":
            return tok.upper()
        if ns == "svc":
            return tok.upper()
        if ns == "mf":
            return tok.lower()
        return tok

    def r_owner(self, rec):
        o = rec.get("owner")
        if o is None:
            return ""
        if o[0] == "sentinel":
            return o[1]
        return self.r_tok(o[0], o[1], rec.get("tok_variant"), rec)

    def r_hash_cols(self, rec):
        h = rec.get("hash")
        if h is None:
            return "", ""
        alg, dig = h
        up = rec.get("hash_upper")
        if alg == "sentinel":
            if len(dig) == 64:
                return "", dig
            return dig, ""
        if alg == "sha256":
            return "", dig.upper() if up else dig
        if alg == "md5b64":
            return base64.b64encode(bytes.fromhex(dig)).decode(), ""
        if alg == "etag":
            return '"' + (dig.upper() if up else dig) + '"', ""
        return dig.upper() if up else dig, ""

    def r_cfg(self):
        return self.truth["prod"]["cfg"]

    # ------------------------------------------------------------------ generic writers
    def w_text(self, path, text, enc="utf-8"):
        Path(path).write_bytes(text.encode(enc))

    def w_csv(self, path, file, cols, rows, flags, drift=None, meta=(), bom=False, extra_lines=()):
        out = io.StringIO()
        out.write(self.r_ctl_line(file, len(rows)) + "\n")
        for m in meta:
            out.write("#" + m + "\n")
        for ln in extra_lines:
            out.write(ln + "\n")
        cur = cols

        def emit(vals, crlf):
            b = io.StringIO()
            csv.writer(b, lineterminator="\n").writerow(vals)
            out.write(b.getvalue())

        emit(cur, False)
        for i, row in enumerate(rows):
            if drift is not None and i == drift[0]:
                cur = drift[1]
                emit([drift[2].get(c, c) for c in cur], False)
            emit(["" if row.get(c) is None else row.get(c) for c in cur], flags[i])
        data = out.getvalue()
        Path(path).write_bytes((b"\xef\xbb\xbf" if bom else b"") + data.encode("utf-8"))

    def w_tsv(self, path, file, cols, rows, flags, drift=None, meta=(), row_enc=None):
        def esc(v):
            s = "" if v is None else str(v)
            return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n").replace("\r", "\\r")

        chunks = [(self.r_ctl_line(file, len(rows)) + "\n").encode()]
        for m in meta:
            chunks.append(("#" + m + "\n").encode())
        cur = cols
        chunks.append(("\t".join(cur) + "\n").encode())
        for i, row in enumerate(rows):
            if drift is not None and i == drift[0]:
                cur = drift[1]
                chunks.append(("\t".join(drift[2].get(c, c) for c in cur) + "\n").encode())
            line = "\t".join(esc(row.get(c)) for c in cur) + "\n"
            enc = row_enc(row) if row_enc else "utf-8"
            chunks.append(line.encode(enc))
        Path(path).write_bytes(b"".join(chunks))

    def w_jsonl(self, path, file, cols, rows, flags, drift=None, head=()):
        lines = [json.dumps({"_ctl": self.r_ctl(file, len(rows))}, separators=(",", ":"))]
        for h in head:
            lines.append(json.dumps(h, separators=(",", ":"), ensure_ascii=False))
        rename = {}
        out = []
        for i, row in enumerate(rows):
            if drift is not None and i == drift[0]:
                rename = drift[2]
                lines.append(json.dumps({"_schema": {"rename": rename}}, separators=(",", ":")))
            obj = {rename.get(c, c): row.get(c) for c in cols}
            s = json.dumps(obj, separators=(",", ":"), ensure_ascii=bool(flags[i]))
            lines.append(s)
        Path(path).write_bytes(("\n".join(lines) + "\n").encode("utf-8"))

    def w_xml(self, path, file, root, elem, cols, rows, flags, drift=None, attrs=None, extra=""):
        def enc(s, ascii_only):
            s = _x(s)
            if ascii_only:
                s = "".join(ch if ord(ch) < 128 else f"&#x{ord(ch):X};" for ch in s)
            return s

        c = self.r_ctl(file, len(rows))
        at = {"ctl-id": c["ctl_id"], "ctl-prev": c["prev"], "ctl-rows": str(c["rows"])}
        at.update(attrs or {})
        parts = ['<?xml version="1.0" encoding="UTF-8"?>\n',
                 f"<{root} " + " ".join(f'{k}="{_x(str(v), {chr(34): "&quot;"})}"' for k, v in at.items()) + ">\n"]
        names = {c: c for c in cols}
        for i, row in enumerate(rows):
            if drift is not None and i == drift[0]:
                parts.append(f'  <schema-change version="2" renames="{_x(json.dumps(drift[2]), {chr(34): "&quot;"})}"/>\n')
                names = {c: drift[2].get(c, c) for c in cols}
            idattr = cols[0]
            body = "".join(
                f"<{names[c]}>{enc('' if row.get(c) is None else str(row.get(c)), flags[i])}</{names[c]}>"
                for c in cols[1:] if row.get(c) is not None)
            parts.append(f'  <{elem} {names[idattr]}="{enc(str(row.get(idattr)), flags[i]).replace(chr(34), "&quot;")}">{body}</{elem}>\n')
        parts.append(extra)
        parts.append(f"</{root}>\n")
        Path(path).write_bytes("".join(parts).encode("utf-8"))

    def w_xlsx(self, path, file, sheets, flags_by_sheet=None, meta="", date1904=False):
        total = sum(len(rows) for _n, _c, rows, _d in sheets)
        c = self.r_ctl(file, total)
        subj = f"ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']}"
        out = []
        for name, cols, rows, drift in sheets:
            grid = [list(cols)]
            cur = cols
            for i, row in enumerate(rows):
                if drift is not None and i == drift[0]:
                    cur = drift[1]
                    grid.append([drift[2].get(x, x) for x in cur])
                grid.append([row.get(x) for x in cur])
            out.append((name, grid))
        Path(path).write_bytes(r_xlsx(out, subj, meta, date1904))

    def w_parquet(self, path, file, cols, rows, types=None, meta=None):
        import pyarrow as pa
        import pyarrow.parquet as pq
        types = types or {}
        arrays = []
        fields = []
        for col in cols:
            t = types.get(col, "str")
            vals = [row.get(col) for row in rows]
            if t == "int":
                arrays.append(pa.array([None if v is None or v == "" else int(v) for v in vals], type=pa.int64()))
                fields.append(pa.field(col, pa.int64()))
            else:
                arrays.append(pa.array([None if v is None else str(v) for v in vals], type=pa.string()))
                fields.append(pa.field(col, pa.string()))
        c = self.r_ctl(file, len(rows))
        md = {"ctl_id": c["ctl_id"], "ctl_prev": c["prev"], "ctl_rows": str(c["rows"])}
        md.update({k: str(v) for k, v in (meta or {}).items()})
        schema = pa.schema(fields, metadata=md)
        table = pa.Table.from_arrays(arrays, schema=schema)
        pq.write_table(table, path, compression="snappy", row_group_size=4096)

    def w_sqlite(self, path, file, tables, views=None):
        p = Path(path)
        if p.exists():
            p.unlink()
        con = sqlite3.connect(str(p))
        total = 0
        for name, cols, types, rows in tables:
            decl = ", ".join(f'"{c}" {types.get(c, "TEXT")}' for c in cols)
            con.execute(f'CREATE TABLE "{name}" ({decl})')
            con.executemany(f'INSERT INTO "{name}" VALUES ({",".join("?" * len(cols))})',
                            [[row.get(c) for c in cols] for row in rows])
            total += len(rows)
        c = self.r_ctl(file, total)
        con.execute(f"CREATE VIEW _control AS SELECT '{c['ctl_id']}' AS ctl_id, '{c['prev']}' AS prev, {total} AS rows")
        for vname, sql in (views or {}).items():
            con.execute(f"CREATE VIEW {vname} AS {sql}")
        con.commit()
        con.execute("VACUUM")
        con.close()

    def w_yaml(self, path, file, sections, head=None):
        def q(v):
            if v is None:
                return "null"
            if isinstance(v, bool):
                return "true" if v else "false"
            if isinstance(v, int):
                return str(v)
            if isinstance(v, str) and v.startswith("!raw:"):
                return v[5:]
            return json.dumps(str(v), ensure_ascii=False)

        total = sum(len(rows) for _n, _c, rows, _d in sections)
        c = self.r_ctl(file, total)
        lines = ["_ctl:", f"  ctl_id: {c['ctl_id']}", f"  prev: {c['prev']}", f"  rows: {c['rows']}"]
        for k, v in (head or {}).items():
            lines.append(f"{k}: {q(v)}")
        for name, cols, rows, drift in sections:
            lines.append(f"{name}:")
            cur = name
            for i, row in enumerate(rows):
                if drift is not None and i == drift[0]:
                    cur = name + "_v2"
                    lines.append(f"{cur}:")
                    lines.append(f"  - _renames: {json.dumps(drift[2])}")
                ks = cols if cur == name else [drift[2].get(x, x) for x in cols]
                pairs = ", ".join(f"{k2}: {q(row.get(k1))}" for k1, k2 in zip(cols, ks) if row.get(k1) is not None)
                lines.append(f"  - {{{pairs}}}")
        Path(path).write_bytes(("\n".join(lines) + "\n").encode("utf-8"))

    def w_toml(self, path, file, sections, head=None):
        def q(v):
            if isinstance(v, bool):
                return "true" if v else "false"
            if isinstance(v, int):
                return str(v)
            if isinstance(v, str) and v.startswith("!raw:"):
                return v[5:]
            return json.dumps(str(v), ensure_ascii=False)

        total = sum(len(rows) for _n, _c, rows, _d in sections)
        c = self.r_ctl(file, total)
        lines = ["[_ctl]", f'ctl_id = "{c["ctl_id"]}"', f'prev = "{c["prev"]}"', f"rows = {c['rows']}", ""]
        for k, v in (head or {}).items():
            lines.append(f"{k} = {q(v)}")
        lines.append("")
        for name, cols, rows, drift in sections:
            cur = name
            ks = cols
            for i, row in enumerate(rows):
                if drift is not None and i == drift[0]:
                    cur = name + "_v2"
                    ks = [drift[2].get(x, x) for x in cols]
                lines.append(f"[[{cur}]]")
                for k1, k2 in zip(cols, ks):
                    if row.get(k1) is not None:
                        lines.append(f"{k2} = {q(row.get(k1))}")
                lines.append("")
        Path(path).write_bytes("\n".join(lines).encode("utf-8"))

    def w_ini(self, path, file, sec_prefix, keycol, cols, rows, flags, drift=None, bom=True):
        c = self.r_ctl(file, len(rows))
        lines = ["[_ctl]", f"ctl_id = {c['ctl_id']}", f"prev = {c['prev']}", f"rows = {c['rows']}", ""]
        names = {x: x for x in cols}
        for i, row in enumerate(rows):
            if drift is not None and i == drift[0]:
                lines += ["[__layout__]", "version = 2", "renames = " + json.dumps(drift[2]), ""]
                names = {x: drift[2].get(x, x) for x in cols}
            lines.append(f"[{sec_prefix}{row.get(keycol)}]")
            for x in cols:
                if x == keycol or row.get(x) is None:
                    continue
                v = str(row.get(x)).replace("\n", " ")
                lines.append(f"{names[x]} = {v}")
            lines.append("")
        text = "\n".join(lines)
        Path(path).write_bytes((b"\xef\xbb\xbf" if bom else b"") + text.encode("utf-8"))

    def md_table(self, cols, rows):
        def cell(v):
            return ("" if v is None else str(v)).replace("\\", "\\\\").replace("|", "\\|").replace("\n", "<br>")
        out = ["| " + " | ".join(cols) + " |", "|" + "|".join("---" for _ in cols) + "|"]
        for row in rows:
            out.append("| " + " | ".join(cell(row.get(c)) for c in cols) + " |")
        return out

    def w_md(self, path, file, prose_before, tables, prose_after=()):
        total = sum(len(rows) for _t, _c, rows, _d in tables)
        c = self.r_ctl(file, total)
        lines = [f"<!-- ctl ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']} -->", ""]
        lines += prose_before
        for title, cols, rows, drift in tables:
            lines += ["", title, ""]
            if drift is None:
                lines += self.md_table(cols, rows)
            else:
                lines += self.md_table(cols, rows[: drift[0]])
                lines += ["", "Rows below this point use the revised column order.", ""]
                lines += self.md_table(drift[1], [{k: r.get(k) for k in drift[1]} for r in rows[drift[0]:]])
        lines += [""] + list(prose_after)
        Path(path).write_bytes(("\n".join(lines) + "\n").encode("utf-8"))

    def w_html(self, path, file, title, prose, tables, banner=None):
        total = sum(len(rows) for _t, _c, rows, _d in tables)
        c = self.r_ctl(file, total)

        def h(v):
            s = _x("" if v is None else str(v))
            return "".join(ch if ord(ch) < 128 else f"&#{ord(ch)};" for ch in s)

        out = ["<!DOCTYPE html>", "<html><head><meta charset=\"utf-8\">", f"<title>{h(title)}</title></head><body>",
               f"<!-- ctl ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']} -->"]
        if banner:
            out.append(f'<div class="banner">{h(banner)}</div>')
        out.append(f"<h1>{h(title)}</h1>")
        for p in prose:
            out.append(f"<p>{h(p)}</p>")
        for t, cols, rows, drift in tables:
            out.append(f"<h2>{h(t)}</h2>")
            segs = [(cols, rows)] if drift is None else [(cols, rows[: drift[0]]), (drift[1], rows[drift[0]:])]
            for scols, srows in segs:
                out.append("<table>")
                out.append("<tr>" + "".join(f"<th>{h(x)}</th>" for x in scols) + "</tr>")
                for row in srows:
                    out.append("<tr>" + "".join(f"<td>{h(row.get(x))}</td>" for x in scols) + "</tr>")
                out.append("</table>")
        out.append("</body></html>")
        Path(path).write_bytes(("\n".join(out) + "\n").encode("utf-8"))

    def w_docx(self, path, file, title, prose, tables, after=(), subject_extra=""):
        total = sum(len(rows) for _t, _c, rows, _d in tables)
        c = self.r_ctl(file, total)
        blocks = [("h", title)] + [("p", p) for p in prose]
        for t, cols, rows, drift in tables:
            blocks.append(("p", t))
            segs = [(cols, rows)] if drift is None else [(cols, rows[: drift[0]]), (drift[1], rows[drift[0]:])]
            for k, (scols, srows) in enumerate(segs):
                if k:
                    blocks.append(("p", "The table continues with a revised column order."))
                blocks.append(("table", list(scols), [["" if r.get(x) is None else str(r.get(x)) for x in scols] for r in srows]))
        blocks += [("p", p) for p in after]
        subj = f"ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']}" + (f"; {subject_extra}" if subject_extra else "")
        Path(path).write_bytes(r_docx(blocks, subj, title))

    def w_pdf(self, path, file, title, prose, tables, after=()):
        total = sum(len(rows) for _t, _c, rows, _d in tables)
        c = self.r_ctl(file, total)
        lines = [f"CONTROL ctl_id={c['ctl_id']} prev={c['prev']} rows={c['rows']}", r_pdf_text(title), ""]
        for p in prose:
            words = r_pdf_text(p).split(" ")
            cur = ""
            for w in words:
                if len(cur) + len(w) + 1 > 150:
                    lines.append(cur)
                    cur = w
                else:
                    cur = (cur + " " + w).strip()
            if cur:
                lines.append(cur)
            lines.append("")
        for t, cols, rows, drift in tables:
            lines.append(r_pdf_text(t))
            cur_cols = cols
            hdr = "COLUMNS: " + " | ".join(cur_cols)
            lines.append(hdr)
            for i, row in enumerate(rows):
                if drift is not None and i == drift[0]:
                    cur_cols = drift[1]
                    hdr = "COLUMNS: " + " | ".join(cur_cols)
                    lines.append(hdr)
                cells = [(r_pdf_text(str(row.get(x))).replace("|", "\\|") if row.get(x) not in (None, "") else "~") for x in cur_cols]
                lines.append(" | ".join(cells))
                if len(lines) % 78 == 0:
                    lines.append(hdr)
        for p in after:
            lines.append(r_pdf_text(p))
        Path(path).write_bytes(r_pdf_bytes(lines, title))

    def r_drift(self, file, rows, cols):
        d = self.meta[file].get("drift_row")
        if d is None:
            return None
        idx = next((i for i, r in enumerate(rows) if r is d), None)
        if idx is None or idx == 0:
            return None
        new = cols[-2:] + cols[:-2] if len(cols) > 3 else list(reversed(cols))
        if file.endswith((".jsonl", ".xml", ".yaml", ".toml", ".ini", ".db", ".json", ".log", ".mbox", ".ics")):
            new = list(cols)
        ren = {}
        for a, b in (("note", "remark"), ("status", "state"), ("display", "label"), ("reason", "why"),
                     ("size", "bytes_raw"), ("bytes", "size_bytes"), ("sz", "size"), ("owner", "owned_by")):
            if a in cols:
                ren[a] = b
        if not ren:
            ren[cols[-1]] = cols[-1] + "_v2"
        return (idx, new, ren)

    def r_flags(self, rows):
        return [bool(r.get("enc_trap")) for r in rows]

    # ------------------------------------------------------------------ inventory rows
    def inv_row(self, rec, cfg):
        legacy, sha = self.r_hash_cols(rec)
        size = self.size_repr(rec)
        tr = rec.get("time_raw") or self.time_repr(rec, cfg)
        if rec.get("excel_nudge") and tr not in ("SENTINEL0", "SENTINEL60"):
            ip, fp = tr.split(".")
            v = int(ip) * 10**10 + int(fp) - 3
            tr = f"{v // 10**10}.{v % 10**10:010d}"
        path = rec["raw_path"]
        if rec.get("enc_trap") and rec["file"] in ("inv_mkt01_q3.jsonl", "inv_lab01_q3.jsonl", "inv_hr01_q3.xlsx",
                                                     "inv_mkt01_supplement.xlsx", "inv_fin01_q3.parquet"):
            path = r_nfd(path)
        return {"rec_id": rec["rec_id"], "path": path, "size": size, "mtime": tr, "legacy": legacy, "sha256": sha,
                "owner": self.r_owner(rec), "fid": rec.get("file_id") or "", "nlink": rec.get("nlink", 1),
                "batch": rec["batch"]}

    def push_ok(self, rec):
        return self.truth["prod"]["outcome"].get(rec["rec_id"], ("E",))[-1] == "OUT_OF_AUTHORITY"

    def rf_inventory(self, out, file):
        cfg = self.r_cfg()
        recs = self.r_order(file, self.rows[file])
        vol = INVENTORY_FILES_R[file]
        rows = []
        for rec in recs:
            row = self.inv_row(rec, cfg)
            row["_rec"] = rec
            if rec.get("push_sentinel") and self.push_ok(rec):
                row["owner"] = "N/A"
                row["batch"] = "?"
            rows.append(row)
        flags = [bool(r["_rec"].get("enc_trap")) for r in rows]
        mode = self.self_mode[file]
        exported = g_iso_r(self.snapshot[vol] + (5 * 86400 if file in DECOYS_R else 0))
        head_meta = [f"export run_mode={mode} volume={vol} host={self.vol_host[vol]} exported_utc={exported}"]
        p = out / file
        if file == "inv_eng01_q3.csv":
            cols = ["rec_id", "path", "size_bytes", "mtime_filetime", "sha256", "owner_sid", "file_id", "links", "batch"]
            data = [{"rec_id": r["rec_id"], "path": r["path"], "size_bytes": r["size"], "mtime_filetime": r["mtime"],
                     "sha256": r["sha256"] or r["legacy"], "owner_sid": r["owner"], "file_id": f"0x{int(r['fid'], 16):016X}" if r["fid"] else "",
                     "links": r["nlink"], "batch": r["batch"], "_rec": r["_rec"]} for r in rows]
            self.w_csv(p, file, cols, data, flags, self.r_drift(file, recs, cols), head_meta, bom=True)
        elif file == "inv_obj01_q3_r2.csv":
            cols = ["rec_id", "key", "size", "last_modified", "etag", "sha256", "owner_id", "version_id", "is_latest",
                    "delete_marker", "batch"]
            data = []
            for r in rows:
                rec = r["_rec"]
                na = rec["flags"].get("na") and "_temporary/" not in rec["rest"]
                data.append({"rec_id": r["rec_id"], "key": r["path"], "size": r["size"], "last_modified": r["mtime"],
                             "etag": r["legacy"], "sha256": r["sha256"], "owner_id": r["owner"],
                             "version_id": f"v{int(rec['rec_id'][-6:]) * 7919 % 10**8:08d}",
                             "is_latest": "false" if na else "true", "delete_marker": "true" if (na and int(rec["rec_id"][-1]) % 2) else "false",
                             "batch": r["batch"]})
            self.w_csv(p, file, cols, data, flags, self.r_drift(file, recs, cols), head_meta)
        elif file == "inv_fin01_q3_r2.csv":
            cols = ["rec_id", "path", "size", "batch", "mtime", "sha256", "owner", "inode", "nlink"]
            data = [{"rec_id": r["rec_id"], "path": r["path"], "size": r["size"], "batch": r["batch"], "mtime": r["mtime"],
                     "sha256": r["sha256"] or r["legacy"], "owner": r["owner"], "inode": int(r["fid"], 16) if r["fid"] else "",
                     "nlink": r["nlink"]} for r in rows]
            self.w_csv(p, file, cols, data, flags, self.r_drift(file, recs, cols),
                       head_meta + ["note this export was produced by a scheduled rehearsal; see run_mode"], bom=True)
        elif file == "inv_fin02_q3.tsv":
            cols = ["rec_id", "enc", "path", "size_kib", "mtime_epoch", "sha1", "sha256", "owner", "batch"]
            data = []
            for r in rows:
                rec = r["_rec"]
                enc = "cp1252" if rec.get("enc_trap") else "utf-8"
                try:
                    r["path"].encode(enc)
                except UnicodeEncodeError:
                    enc = "utf-8"
                data.append({"rec_id": r["rec_id"], "enc": enc, "path": r["path"], "size_kib": r["size"],
                             "mtime_epoch": r["mtime"], "sha1": r["legacy"], "sha256": r["sha256"], "owner": r["owner"],
                             "batch": r["batch"], "_enc": enc})
            self.w_tsv(p, file, cols, data, [False] * len(data), self.r_drift(file, recs, cols), head_meta,
                       row_enc=lambda row: row["_enc"])
        elif file == "inv_ops01_q3.tsv":
            cols = ["rec_id", "path", "size_kb", "mtime_local", "sha256", "owner", "inode", "nlink", "batch"]
            data = [{"rec_id": r["rec_id"], "path": r["path"], "size_kb": r["size"], "mtime_local": r["mtime"],
                     "sha256": r["sha256"] or r["legacy"], "owner": r["owner"], "inode": int(r["fid"], 16) if r["fid"] else "",
                     "nlink": r["nlink"], "batch": r["batch"]} for r in rows]
            self.w_tsv(p, file, cols, data, flags, self.r_drift(file, recs, cols), head_meta)
        elif file in ("inv_mkt01_q3.jsonl", "inv_lab01_q3.jsonl", "inv_eng01_q3_deep.jsonl"):
            if file == "inv_mkt01_q3.jsonl":
                cols = ["id", "p", "sz", "mt", "md5b64", "sha256", "own", "batch"]
                data = [{"id": r["rec_id"], "p": r["path"], "sz": None if r["size"] == "" else int(r["size"]),
                         "mt": int(r["mtime"]), "md5b64": r["legacy"] or None, "sha256": r["sha256"] or None,
                         "own": r["owner"], "batch": r["batch"]} for r in rows]
            elif file == "inv_lab01_q3.jsonl":
                cols = ["rec", "path", "size", "mtime_local", "tzq", "md5", "sha256", "uid", "batch"]
                data = []
                for r in rows:
                    loc, q = r["mtime"].split("|")
                    data.append({"rec": r["rec_id"], "path": r["path"], "size": None if r["size"] == "" else r["size"],
                                 "mtime_local": loc, "tzq": None if q == "null" else int(q), "md5": r["legacy"] or None,
                                 "sha256": r["sha256"] or None, "uid": r["owner"], "batch": r["batch"]})
            else:
                cols = ["id", "path", "bytes", "mtime", "sha256", "owner", "fid", "links", "batch"]
                data = [{"id": r["rec_id"], "path": r["path"], "bytes": None if r["size"] in ("", "-1") else int(r["size"]),
                         "mtime": r["mtime"], "sha256": r["sha256"] or r["legacy"], "owner": r["owner"],
                         "fid": r["fid"] or None, "links": r["nlink"], "batch": r["batch"]} for r in rows]
            self.w_jsonl(p, file, cols, data, flags, self.r_drift(file, recs, cols),
                         head=[{"_export": {"run_mode": mode, "volume": vol, "host": self.vol_host[vol], "exported_utc": exported}}])
        elif file in ("inv_hr01_q3.xlsx", "inv_mkt01_supplement.xlsx"):
            if file == "inv_hr01_q3.xlsx":
                cols = ["rec_id", "path", "size", "modified", "md5", "sha256", "owner", "batch"]
                names = ["dept-a", "dept-b"]
            else:
                cols = ["record", "location", "size", "modified", "sha256", "owner", "batch"]
                names = ["batch-A", "batch-B"]
            data = []
            for r in rows:
                m = r["mtime"]
                mv = 0 if m == "SENTINEL0" else (60 if m == "SENTINEL60" else float(m))
                d = {"rec_id": r["rec_id"], "record": r["rec_id"], "path": r["path"], "location": r["path"],
                     "size": r["size"], "modified": mv, "md5": r["legacy"],
                     "sha256": r["sha256"] if file == "inv_hr01_q3.xlsx" else (r["sha256"] or r["legacy"]),
                     "owner": r["owner"], "batch": r["batch"], "_rec": r["_rec"]}
                data.append(d)
            half = len(data) // 2
            s1, s2 = data[:half], data[half:]
            cols2 = cols[-3:] + cols[:-3]
            dr = self.r_drift(file, [d["_rec"] for d in s1], cols)
            self.w_xlsx(p, file, [(names[0], cols, s1, dr), (names[1], cols2, s2, None)],
                        meta=" ".join(head_meta), date1904=(file == "inv_mkt01_supplement.xlsx"))
        elif file == "inv_fin01_q3.parquet":
            cols = ["rec_id", "path", "size", "batch", "mtime_ns", "sha256", "owner", "inode", "nlink"]
            data = [{"rec_id": r["rec_id"], "path": r["path"], "size": r["size"] or None, "batch": r["batch"],
                     "mtime_ns": int(r["mtime"]), "sha256": r["sha256"] or r["legacy"], "owner": r["owner"],
                     "inode": int(r["fid"], 16) if r["fid"] else None, "nlink": r["nlink"]} for r in rows]
            self.w_parquet(p, file, cols, data, {"mtime_ns": "int", "inode": "int", "nlink": "int"},
                           {"run_mode": mode, "volume": vol, "host": self.vol_host[vol], "exported_utc": exported})
        elif file in ("inv_eng01_q3_part2.db", "arc01_ltfs_index.db"):
            if file == "inv_eng01_q3_part2.db":
                cols = ["rec_id", "unc_path", "bytes", "mtime_ms", "sha256", "owner", "fid", "nlink", "batch"]
                tname = "inventory"
                types = {"bytes": "INTEGER", "mtime_ms": "INTEGER", "fid": "INTEGER", "nlink": "INTEGER"}
                conv = lambda r: {"rec_id": r["rec_id"], "unc_path": r["path"], "bytes": None if r["size"] == "" else int(r["size"]),
                                  "mtime_ms": int(r["mtime"]), "sha256": r["sha256"] or r["legacy"], "owner": r["owner"],
                                  "fid": int(r["fid"], 16) if r["fid"] else None, "nlink": r["nlink"], "batch": r["batch"]}
            else:
                cols = ["rec_id", "path", "bytes", "mtime", "sha1", "sha256", "owner", "file_id", "nlink", "batch"]
                tname = "ltfs_files"
                types = {"bytes": "INTEGER", "nlink": "INTEGER"}
                conv = lambda r: {"rec_id": r["rec_id"], "path": r["path"], "bytes": None if r["size"] == "" else int(r["size"]),
                                  "mtime": r["mtime"], "sha1": r["legacy"] or None, "sha256": r["sha256"] or None,
                                  "owner": r["owner"], "file_id": r["fid"] or None, "nlink": r["nlink"], "batch": r["batch"]}
            data = [conv(r) for r in rows]
            dr = self.r_drift(file, recs, cols)
            tables = [(tname, cols, types, data if dr is None else data[: dr[0]])]
            if dr is not None:
                tables.append((tname + "_v2", [dr[2].get(c, c) for c in cols], {dr[2].get(k, k): v for k, v in types.items()},
                               [{dr[2].get(k, k): v for k, v in d.items()} for d in data[dr[0]:]]))
            views = {"_export": f"SELECT '{mode}' AS run_mode, '{vol}' AS volume, '{self.vol_host[vol]}' AS host, '{exported}' AS exported_utc"}
            self.w_sqlite(p, file, tables, views)
        elif file in ("inv_eng02_q3.txt", "arc01_tape_catalog.txt"):
            self.rf_fixed_inv(p, file, rows, recs, head_meta)
        elif file == "inv_rnd01_q3.json":
            cols = ["id", "path", "bytes", "mtime_ms", "sha1", "sha256", "owner", "batch"]
            data = [{"id": r["rec_id"], "path": r["path"], "bytes": r["size"], "mtime_ms": int(r["mtime"]),
                     "sha1": r["legacy"] or None, "sha256": r["sha256"] or None, "owner": r["owner"], "batch": r["batch"]}
                    for r in rows]
            dr = self.r_drift(file, recs, cols)
            items = data if dr is None else data[: dr[0]]
            obj = {"_ctl": self.r_ctl(file, len(data)),
                   "export": {"run_mode": mode, "volume": vol, "host": self.vol_host[vol], "exported_utc": exported},
                   "items": items}
            if dr is not None:
                obj["items_v2"] = [{dr[2].get(k, k): v for k, v in d.items()} for d in data[dr[0]:]]
                obj["items_v2_renames"] = dr[2]
            p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode("utf-8"))
        elif file == "rnd01_cold_listing.pdf":
            cols = ["rec_id", "path", "size", "modified", "sha1", "sha256", "owner", "batch"]
            data = [{"rec_id": r["rec_id"], "path": r["path"], "size": r["size"].replace(",", "\u2009") if r["size"] else r["size"],
                     "modified": r["mtime"], "sha1": r["legacy"], "sha256": r["sha256"], "owner": r["owner"], "batch": r["batch"]}
                    for r in rows]
            self.w_pdf(p, file, "RND01 cold tier listing", [f"Export: {head_meta[0]}",
                                                            "Characters outside Latin-1 are written as \\uXXXX escapes; a literal backslash is doubled."],
                       [("Listing", cols, data, self.r_drift(file, recs, cols))])
        elif file == "inv_leg01_q3.xml":
            cols = ["id", "path", "size", "mtime", "md5", "sha256", "owner", "batch"]
            data = []
            for r in rows:
                rec = r["_rec"]
                d = {"id": r["rec_id"], "path": r["path"], "size": r["size"], "mtime": r["mtime"], "md5": r["legacy"] or None,
                     "sha256": r["sha256"] or None, "owner": r["owner"], "batch": r["batch"]}
                if rec.get("xml_kib") and r["size"] not in ("", None):
                    d["size"] = "KiB:" + g_exact_div_r(int(r["size"]), 1024)
                data.append(d)
            self.rf_xml_inv(p, file, cols, data, flags, self.r_drift(file, recs, cols), vol, mode, exported)
        else:
            raise ValueError(file)

    def rf_xml_inv(self, p, file, cols, data, flags, drift, vol, mode, exported):
        c = self.r_ctl(file, len(data))
        parts = ['<?xml version="1.0" encoding="UTF-8"?>\n',
                 f'<inventory ctl-id="{c["ctl_id"]}" ctl-prev="{c["prev"]}" ctl-rows="{c["rows"]}" volume-serial="{self.vol_serial[vol]}" '
                 f'run-mode="{mode}" exported-utc="{exported}">\n']
        sizetag = "size"
        for i, d in enumerate(data):
            if drift is not None and i == drift[0]:
                parts.append('  <schema-change version="2" renames="{&quot;size&quot;: &quot;bytes&quot;}"/>\n')
                sizetag = "bytes"

            def e(s):
                s = _x(s)
                if flags[i]:
                    s = "".join(ch if ord(ch) < 128 else f"&#x{ord(ch):X};" for ch in s)
                return s
            body = [f"<path>{e(d['path'])}</path>"]
            sz = d["size"]
            if sz is not None and sz != "":
                if str(sz).startswith("KiB:"):
                    body.append(f'<{sizetag} unit="KiB">{sz[4:]}</{sizetag}>')
                else:
                    body.append(f'<{sizetag} unit="B">{sz}</{sizetag}>')
            body.append(f"<mtime>{d['mtime']}</mtime>")
            if d["md5"]:
                body.append(f"<md5>{d['md5']}</md5>")
            if d["sha256"]:
                body.append(f"<sha256>{d['sha256']}</sha256>")
            body.append(f"<owner>{e(d['owner'])}</owner><batch>{d['batch']}</batch>")
            parts.append(f'  <file id="{d["id"]}">' + "".join(body) + "</file>\n")
        parts.append("</inventory>\n")
        p.write_bytes("".join(parts).encode("utf-8"))

    def rf_fixed_inv(self, p, file, rows, recs, head_meta):
        dr = self.r_drift(file, recs, ["x"])
        if file == "inv_eng02_q3.txt":
            lay1 = [("rec_id", 12), ("path", 96), ("size", 16), ("mtime_local", 19), ("md5", 32), ("sha256", 64), ("owner", 40), ("batch", 12)]
            lay2 = [("rec_id", 12), ("batch", 12), ("owner", 40), ("path", 96), ("size", 16), ("mtime_local", 19), ("md5", 32), ("sha256", 64)]
            vals = lambda r: {"rec_id": r["rec_id"], "path": r["path"], "size": r["size"], "mtime_local": r["mtime"],
                              "md5": r["legacy"], "sha256": r["sha256"], "owner": r["owner"], "batch": r["batch"]}
        else:
            lay1 = [("rec_id", 12), ("path", 88), ("size", 40), ("mtime_julian", 14), ("sha1", 40), ("sha256", 64), ("owner", 10), ("batch", 12), ("flag", 2)]
            lay2 = [("rec_id", 12), ("flag", 2), ("batch", 12), ("path", 88), ("size", 40), ("mtime_julian", 14), ("sha1", 40), ("sha256", 64), ("owner", 10)]
            vals = lambda r: {"rec_id": r["rec_id"], "path": r["path"], "size": r["size"], "mtime_julian": r["mtime"],
                              "sha1": r["legacy"], "sha256": r["sha256"], "owner": r["owner"], "batch": r["batch"],
                              "flag": "X" if r["_rec"]["flags"].get("na") else ""}

        def layout_line(lay, ver):
            pos = 1
            parts = []
            for name, w in lay:
                parts.append(f"{name}:{pos}-{pos + w - 1}")
                pos += w
            return f"#LAYOUT v{ver} " + " ".join(parts)

        out = []
        out.append((self.r_ctl_line(file, len(rows), "CTL") + "\n").encode())
        for m in head_meta:
            out.append(("#" + m + "\n").encode())
        out.append((layout_line(lay1, 1) + "\n").encode())
        lay = lay1
        cur_enc = "utf-8"
        for i, r in enumerate(rows):
            if dr is not None and i == dr[0]:
                lay = lay2
                out.append((layout_line(lay2, 2) + "\n").encode())
            want = "latin-1" if r["_rec"].get("enc_trap") else "utf-8"
            v = vals(r)
            if want == "latin-1":
                try:
                    for name, _w in lay:
                        str(v.get(name) or "").encode("latin-1")
                except UnicodeEncodeError:
                    want = "utf-8"
            if want != cur_enc:
                out.append(f"#ENC {want}\n".encode())
                cur_enc = want
            line = []
            overflow = ""
            for name, w in lay:
                s = str(v.get(name) or "")
                if name == "path" and len(s) > w:
                    s, overflow = s[: w - 1] + "+", s[w - 1:]
                line.append(s.ljust(w) if name != "size" else s.rjust(w))
            out.append(("".join(line).rstrip() + "\n").encode(cur_enc))
            while overflow:
                chunk, overflow = overflow[:200], overflow[200:]
                out.append(("+" + chunk + "\n").encode(cur_enc))
        p.write_bytes(b"".join(out))

    # ------------------------------------------------------------------ journals
    def jr_row(self, ev, cfg):
        legacy, sha = self.r_hash_cols(ev) if ev.get("hash") else ("", "")
        size = self.size_repr(ev) if ev.get("size") else ""
        if size and SIZE_DIALECT_R.get(ev["file"]) == "dotted":
            size = f"{int(size):,}".replace(",", ".")
        tr = ev.get("time_raw") or self.time_repr(ev, cfg)
        return {"rec_id": ev["rec_id"], "seq": ev["seq"], "op": ev["op"], "path": ev["raw_path"],
                "to": ev.get("raw_newpath") or "", "size": size, "legacy": legacy, "sha256": sha,
                "owner": self.r_owner(ev) if ev.get("owner") else "", "ts": tr, "batch": ev["batch"],
                "host": ev.get("host", ""), "_rec": ev}

    def rf_journal(self, out, file):
        cfg = self.r_cfg()
        evs = self.rows[file]
        rows = [self.jr_row(e, cfg) for e in evs]
        if file == "journal_mkt01_q3.log":
            pass
        flags = [bool(e.get("enc_trap")) for e in evs]
        vol = JOURNAL_FILES_R[file]
        p = out / file
        dr = self.r_drift(file, evs, ["x"])
        role = "replica" if file in DECOYS_R else "primary"
        if file.endswith(".log"):
            alg = {"sha256": "sha256", "md5b64": "md5b64", "sha1": "sha1"}[SOURCE_HASH_R[file]]
            lines = [self.r_ctl_line(file, len(rows), "# ctl"), f"# journal volume={vol} role={role} host={self.vol_host[vol]}"]
            v2 = False
            ckpt = 0
            for i, r in enumerate(rows):
                if dr is not None and i == dr[0]:
                    lines.append("# FORMAT v2 renames size=sz sha256=h256 owner=own")
                    v2 = True
                k_size, k_sha, k_own = ("sz", "h256", "own") if v2 else ("size", "sha256", "owner")
                q = lambda s: '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'
                parts = [f"ts={q(r['ts']) if ' ' in r['ts'] else r['ts']}", f"host={r['host']}", f"seq={r['seq']}", f"op={r['op']}", f"path={q(r['path'])}"]
                if r["to"]:
                    parts.append(f"to={q(r['to'])}")
                if r["size"] != "":
                    parts.append(f"{k_size}={r['size']}")
                if r["sha256"]:
                    parts.append(f"{k_sha}={r['sha256']}")
                if r["legacy"]:
                    parts.append(f"{alg}={r['legacy']}")
                if r["owner"]:
                    parts.append(f"{k_own}={q(r['owner'])}")
                parts.append(f"batch={r['batch']}")
                parts.append(f"id={r['rec_id']}")
                lines.append(" ".join(parts))
                if file in DECOYS_R:
                    ckpt += 1
                    if ckpt % 250 == 0:
                        lines.append(f"# CHECKPOINT through_seq={r['seq']} events={ckpt}")
            p.write_bytes(("\n".join(lines) + "\n").encode("utf-8"))
        elif file == "journal_eng02_q3.csv":
            cols = ["rec_id", "seq", "op", "path", "new_path", "size", "md5", "sha256", "owner", "filetime", "batch"]
            data = [{"rec_id": r["rec_id"], "seq": r["seq"], "op": r["op"], "path": r["path"], "new_path": r["to"],
                     "size": r["size"], "md5": r["legacy"], "sha256": r["sha256"], "owner": r["owner"], "filetime": r["ts"],
                     "batch": r["batch"]} for r in rows]
            self.w_csv(p, file, cols, data, flags, None if dr is None else (dr[0], cols[-2:] + cols[:-2], {}),
                       [f"journal volume={vol} role={role}"])
        elif file == "journal_hr01_q3.jsonl":
            cols = ["id", "seq", "op", "path", "to", "size", "md5", "sha256", "owner", "at", "batch"]
            data = [{"id": r["rec_id"], "seq": r["seq"], "op": r["op"], "path": r["path"], "to": r["to"] or None,
                     "size": None if r["size"] == "" else int(r["size"]), "md5": r["legacy"] or None,
                     "sha256": r["sha256"] or None, "owner": r["owner"] or None, "at": r["ts"], "batch": r["batch"]}
                    for r in rows]
            self.w_jsonl(p, file, cols, data, flags, dr and (dr[0], cols, {"owner": "owned_by", "size": "bytes"}),
                         head=[{"_journal": {"volume": vol, "role": role}}])
        elif file == "journal_obj01_events.jsonl":
            lines = [json.dumps({"_ctl": self.r_ctl(file, len(rows))}, separators=(",", ":")),
                     json.dumps({"_journal": {"volume": vol, "role": role}}, separators=(",", ":"))]
            for i, r in enumerate(rows):
                ev = r["_rec"]
                bucket, _, key = r["path"][5:].partition("/")
                if r["op"] == "CREATE":
                    name = "ObjectCreated:Put"
                elif ev.get("s3_marker"):
                    name = "ObjectRemoved:DeleteMarkerCreated"
                else:
                    name = "ObjectRemoved:Delete"
                obj = {"id": r["rec_id"], "eventName": name, "eventTime": r["ts"],
                       "s3": {"bucket": {"name": bucket}, "object": {"key": key, "sequencer": ev.get("seq_hex") or f"{r['seq']:X}"}}}
                if r["op"] == "CREATE":
                    obj["s3"]["object"].update({"size": None if r["size"] == "" else int(r["size"]),
                                                "eTag": r["legacy"].strip('"') or None, "sha256": r["sha256"] or None})
                    obj["userIdentity"] = {"canonicalId": r["owner"]}
                obj["batch"] = r["batch"]
                lines.append(json.dumps(obj, separators=(",", ":"), ensure_ascii=flags[i]))
            p.write_bytes(("\n".join(lines) + "\n").encode("utf-8"))
        elif file == "journal_fin02_q3.xml":
            c = self.r_ctl(file, len(rows))
            parts = ['<?xml version="1.0" encoding="UTF-8"?>\n',
                     f'<journal ctl-id="{c["ctl_id"]}" ctl-prev="{c["prev"]}" ctl-rows="{c["rows"]}" volume="{vol}" role="{role}">\n']
            ptag = "path"
            for i, r in enumerate(rows):
                if dr is not None and i == dr[0]:
                    parts.append('  <schema-change version="2" renames="{&quot;path&quot;: &quot;source&quot;}"/>\n')
                    ptag = "source"
                e = (lambda s: "".join(ch if ord(ch) < 128 else f"&#x{ord(ch):X};" for ch in _x(s))) if flags[i] else _x
                body = [f"<{ptag}>{e(r['path'])}</{ptag}>"]
                if r["to"]:
                    body.append(f"<to>{e(r['to'])}</to>")
                if r["size"] != "":
                    body.append(f"<size>{r['size']}</size>")
                if r["legacy"]:
                    body.append(f"<sha1>{r['legacy']}</sha1>")
                if r["sha256"]:
                    body.append(f"<sha256>{r['sha256']}</sha256>")
                if r["owner"]:
                    body.append(f"<owner>{e(r['owner'])}</owner>")
                parts.append(f'  <event id="{r["rec_id"]}" seq="{r["seq"]}" op="{r["op"]}" at="{r["ts"]}" batch="{r["batch"]}">'
                             + "".join(body) + "</event>\n")
            parts.append("</journal>\n")
            p.write_bytes("".join(parts).encode("utf-8"))
        elif file == "journal_rnd01_q3.json":
            data = [{"id": r["rec_id"], "seq": r["seq"], "op": r["op"], "path": r["path"], "to": r["to"] or None,
                     "bytes": r["size"] or None, "sha1": r["legacy"] or None, "sha256": r["sha256"] or None,
                     "owner": r["owner"] or None, "at": r["ts"], "batch": r["batch"]} for r in rows]
            obj = {"_ctl": self.r_ctl(file, len(rows)), "journal": {"volume": vol, "role": role}}
            if dr is None:
                obj["events"] = data
            else:
                obj["events"] = data[: dr[0]]
                obj["events_v2"] = [{("owned_by" if k == "owner" else k): v for k, v in d.items()} for d in data[dr[0]:]]
                obj["events_v2_renames"] = {"owner": "owned_by"}
            p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode("utf-8"))
        elif file == "journal_leg01_notifications.mbox":
            self.rf_mbox(p, file, rows, flags, dr, vol)
        else:
            raise ValueError(file)

    def rf_mbox(self, p, file, rows, flags, dr, vol):
        import quopri
        out = []
        c = self.r_ctl(file, len(rows))
        v2 = False
        for i, r in enumerate(rows):
            if dr is not None and i == dr[0]:
                v2 = True
            hdr = [f"From fswatch@{self.vol_host[vol]} Thu Jan  1 00:00:00 1970",
                   f"From: fswatch <fswatch@{self.vol_host[vol]}>", f"Date: {r['ts']}",
                   f"Message-ID: <{r['rec_id']}@{self.vol_host[vol]}>", f"Subject: [FSWATCH] {r['op']} {r['rec_id']}",
                   f"X-Seq: {r['seq']}", f"X-Batch: {r['batch']}"]
            if i == 0:
                hdr += [f"X-Ctl-Id: {c['ctl_id']}", f"X-Ctl-Prev: {c['prev']}", f"X-Ctl-Rows: {c['rows']}",
                        f"X-Journal: volume={vol} role=primary"]
            if v2 and (i == dr[0]):
                hdr.append("X-Schema: 2 (X-Size renamed X-Size-Bytes, X-Owner renamed X-Principal)")
            if r["size"] != "":
                hdr.append(f"{'X-Size-Bytes' if v2 else 'X-Size'}: {r['size']}")
            if r["legacy"]:
                hdr.append(f"X-Md5: {r['legacy']}")
            if r["sha256"]:
                hdr.append(f"X-Sha256: {r['sha256']}")
            if r["owner"]:
                hdr.append(f"{'X-Principal' if v2 else 'X-Owner'}: {r['owner']}")
            body_lines = [f"Path: {r['path']}"] + ([f"To: {r['to']}"] if r["to"] else [])
            body = "\n".join(body_lines) + "\n"
            if i % 9 == 4:
                body += "From the watcher: event recorded.\n"
            if flags[i]:
                if i % 2:
                    enc = base64.encodebytes(body.encode("utf-8")).decode()
                    hdr += ["MIME-Version: 1.0", 'Content-Type: text/plain; charset="utf-8"', "Content-Transfer-Encoding: base64"]
                else:
                    enc = quopri.encodestring(body.encode("utf-8")).decode()
                    hdr += ["MIME-Version: 1.0", 'Content-Type: text/plain; charset="utf-8"', "Content-Transfer-Encoding: quoted-printable"]
                body = enc
            else:
                hdr += ["MIME-Version: 1.0", 'Content-Type: text/plain; charset="utf-8"', "Content-Transfer-Encoding: 8bit"]
            body = "\n".join((">" + ln if ln.startswith("From ") else ln) for ln in body.split("\n"))
            out.append("\n".join(hdr) + "\n\n" + body.rstrip("\n") + "\n")
        p.write_bytes(("\n".join(out)).encode("utf-8"))

    # ------------------------------------------------------------------ reference tables
    def ref_alias_rows(self, file, part):
        rows = self.r_order(file, self.alias_rows[part])
        out = []
        for a in rows:
            root = a["root"]
            if a.get("case_trap"):
                root = root.upper() if not root.startswith("/") else root
            root = self.r_key(root, a)
            out.append({"alias_id": a["alias_id"], "root": root, "volume": a["volume"], "prefix": a["prefix"],
                        "rev": a["rev"], "status": a["status"], "note": self.r_note(a, FILE_FMT_R[file]), "_row": a})
        return rows, out

    def ref_ext_rows(self, file, part, src=None):
        rows = self.r_order(file, src if src is not None else self.ext_rows[part])
        out = []
        for e in rows:
            ext = e["ext"]
            if e.get("case_trap"):
                ext = "." + ext.upper()
            ext = self.r_key(ext, e)
            d = {"ext": ext, "family": e["family"], "rev": e["rev"], "status": e["status"],
                 "note": self.r_note(e, FILE_FMT_R[file]), "_row": e}
            if part == "A":
                d["pending"] = "yes" if e.get("pending") else "no"
            out.append(d)
        return rows, out

    def tok_cell(self, ns, row):
        tok = row["token"]
        if row.get("render_variant") or row.get("case_trap"):
            tok = self.r_tok(ns, tok, True)
        return self.r_key(tok, row)

    def ref_tok_rows(self, file, ns, src=None):
        rows = self.r_order(file, src if src is not None else self.tok_rows[ns])
        out = []
        for t in rows:
            d = {"principal_id": t["pid"], "valid_from": g_iso_r(t.get("valid_from", self.prev_start - 400 * 86400)),
                 "status": t.get("status", "active"), "display": self.r_note(t, FILE_FMT_R[file]) or
                 self.principals.get(t["pid"], {"account": "former staff"})["account"].replace(".", " ").title(), "_row": t}
            tok = self.tok_cell(ns, t)
            if ns == "uid":
                _u, host, n = t["token"].split(":")
                if t.get("render_variant") or t.get("case_trap"):
                    host, n = host.upper(), f"{int(n):08d}"
                d.update(host=self.r_key(host, t), uid=n)
            elif ns in ("corp", "oldcorp", "legacy"):
                dom, _, login = tok.strip().partition("\\")
                d.update(domain=dom, login=login)
            elif ns == "sid":
                d.update(sid=tok, domain=t.get("domain", ""))
            elif ns == "email":
                d.update(email=tok)
            elif ns == "s3":
                d.update(canonical_id=tok)
            elif ns == "svc":
                d.update(account=tok)
            elif ns == "mf":
                d.update(mf_id=tok)
            out.append(d)
        return rows, out

    def rf_ref(self, out, file):
        fmt = FILE_FMT_R[file]
        role = FILE_ROLE_R[file]
        kind, _, arg = role.partition(":")
        p = out / file
        cfg = self.r_cfg()
        if kind == "alias" and file not in ("ECS-handbook-paths.docx", "volumes.yaml", "ECS-standard.md"):
            src, rows = self.ref_alias_rows(file, arg)
            cols = ["alias_id", "root", "volume", "prefix", "rev", "status", "note"]
            dr = self.r_drift(file, src, cols)
            if fmt == "tsv":
                self.w_tsv(p, file, cols, rows, self.r_flags(src), dr, ["roots compare case-insensitively for UNC and smb forms"])
            elif fmt == "xlsx":
                half = len(rows) // 2
                self.w_xlsx(p, file, [("aliases-1", cols, rows[:half], self.r_drift(file, src[:half], cols)),
                                      ("aliases-2", cols[::-1], rows[half:], None)], meta="SharePoint and NFS alias roots")
            elif fmt == "xml":
                self.w_xml(p, file, "aliases", "alias", cols, rows, self.r_flags(src), dr)
            return
        if kind == "ext" and file != "tool.zip":
            src, rows = self.ref_ext_rows(file, arg)
            cols = ["ext", "family", "rev", "status", "note"] + (["pending"] if arg == "A" else [])
            dr = self.r_drift(file, src, cols)
            if fmt == "tsv":
                self.w_tsv(p, file, cols, rows, self.r_flags(src), dr)
            elif fmt == "xlsx":
                half = len(rows) // 2
                self.w_xlsx(p, file, [("families-1", cols, rows[:half], self.r_drift(file, src[:half], cols)),
                                      ("families-2", cols[1:] + cols[:1], rows[half:], None)])
            elif fmt == "html":
                self.w_html(p, file, "Extension family wiki (table D)", WIKI_PROSE, [("Families", cols, rows, dr)])
            return
        if kind == "tok" and file not in ("owner-migration-plan.docx", "hr-roster-q3.pdf", "principal_map_ldap.html",
                                          "principal_sid_map.xlsx"):
            ns = arg
            src, rows = self.ref_tok_rows(file, ns)
            if ns == "uid":
                cols = ["host", "uid", "principal_id", "valid_from", "status", "display"]
                self.w_tsv(p, file, cols, rows, self.r_flags(src), self.r_drift(file, src, cols),
                           ["uid tokens: uid:<host or host alias>:<number>"])
            elif ns == "legacy":
                cols = ["domain", "login", "principal_id", "valid_from", "status", "display"]
                dr = self.r_drift(file, src, cols)
                tables = [("logins", cols, {}, rows if dr is None else rows[: dr[0]])]
                if dr is not None:
                    tables.append(("logins_v2", [dr[2].get(c, c) for c in cols], {},
                                   [{dr[2].get(k, k): v for k, v in r.items()} for r in rows[dr[0]:]]))
                self.w_sqlite(p, file, tables)
            elif ns == "s3":
                cols = ["canonical_id", "principal_id", "valid_from", "status", "display"]
                dr = self.r_drift(file, src, cols)
                obj = {"_ctl": self.r_ctl(file, len(rows)), "ids": [{c: r[c] for c in cols} for r in (rows if dr is None else rows[: dr[0]])]}
                if dr is not None:
                    obj["ids_v2"] = [{dr[2].get(c, c): r[c] for c in cols} for r in rows[dr[0]:]]
                    obj["ids_v2_renames"] = dr[2]
                p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode())
            elif ns == "svc":
                cols = ["account", "principal_id", "valid_from", "status", "display"]
                self.w_ini(p, file, "", "account", cols, rows, self.r_flags(src), self.r_drift(file, src, cols))
            elif ns == "mf":
                cols = ["mf_id", "principal_id", "valid_from", "status", "display"]
                self.w_fixed_ref(p, file, cols, [8, 9, 21, 9, 60], rows, src)
            return
        if file == "principal_sid_map.xlsx":
            src, rows = self.ref_tok_rows(file, "sid")
            cols = ["sid", "principal_id", "domain", "valid_from", "status", "display"]
            prin = [{"principal_id": pid, "account": self.principals[pid]["account"], "status": self.principals[pid]["status"]}
                    for pid in self.pids]
            self.w_xlsx(p, file, [("principals", ["principal_id", "account", "status"], prin, None),
                                  ("sids", cols, rows, self.r_drift(file, src, cols))], meta="principal register and SID map")
            return
        self.rf_ref2(out, file)

    def w_fixed_ref(self, p, file, cols, widths, rows, src):
        dr = self.r_drift(file, src, cols)
        def lay(cs, ws, v):
            pos = 1
            parts = []
            for c, w in zip(cs, ws):
                parts.append(f"{c}:{pos}-{pos + w - 1}")
                pos += w
            return f"#LAYOUT v{v} " + " ".join(parts)
        out = [(self.r_ctl_line(file, len(rows), "CTL") + "\n").encode(), (lay(cols, widths, 1) + "\n").encode()]
        cs, ws = cols, widths
        enc = "utf-8"
        for i, r in enumerate(rows):
            if dr is not None and i == dr[0]:
                cs = cols[1:] + cols[:1]
                ws = widths[1:] + widths[:1]
                out.append((lay(cs, ws, 2) + "\n").encode())
            want = "latin-1" if src[i].get("enc_trap") else "utf-8"
            try:
                "".join(str(r.get(c) or "") for c in cs).encode(want)
            except UnicodeEncodeError:
                want = "utf-8"
            if want != enc:
                out.append(f"#ENC {want}\n".encode())
                enc = want
            line = "".join(str(r.get(c) or "")[:w].ljust(w) for c, w in zip(cs, ws)).rstrip()
            out.append((line + "\n").encode(enc))
        p.write_bytes(b"".join(out))

    def rf_ref2(self, out, file):
        fmt = FILE_FMT_R[file]
        role = FILE_ROLE_R[file]
        kind, _, arg = role.partition(":")
        p = out / file
        iso = g_iso_r

        def flagged(src, rows):
            return self.r_flags(src)

        if kind == "merges" or file == "ops-runbook.md":
            part = "A" if file == "principal_merges.csv" else "B"
            src = self.r_order(file, [m for m in self.merges if m["part"] == part])
            cols = ["merge_id", "from_principal", "to_principal", "effective_utc", "status", "rev", "note"]
            rows = [{"merge_id": self.r_key(m["merge_id"], m), "from_principal": m["from"].lower() if m.get("case_trap") else m["from"],
                     "to_principal": m["to"], "effective_utc": iso(m["effective"]), "status": m["status"], "rev": m["rev"],
                     "note": self.r_note(m, fmt)} for m in src]
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src, rows), dr)
            else:
                self.w_md(p, file, self.doc("ops-runbook.md"), [("## Appendix M. Principal merges (partition B)", cols, rows, dr)])
            return
        if kind == "xwalk" or file == "hash_index_master.parquet":
            part = {v: k for k, v in XWALK_FILE_R.items()}[file]
            src = self.r_order(file, self.xwalk_rows[part])
            cols = ["digest", "alg", "sha256", "status", "rev", "origin", "note"]
            rows = []
            for x in src:
                dig = x["digest"].upper() if (x.get("render_upper") or x.get("case_trap")) else x["digest"]
                rows.append({"digest": self.r_key(dig, x), "alg": x["alg"], "sha256": x["sha256"], "status": x["status"],
                             "rev": x["rev"], "origin": x.get("origin", ""), "note": self.r_note(x, fmt)})
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src, rows), dr)
            elif fmt == "jsonl":
                self.w_jsonl(p, file, cols, rows, flagged(src, rows), dr)
            elif fmt == "parquet":
                meta = {}
                if file == "hash_index_master.parquet":
                    for q in ("md5A", "md5B", "md5C", "sha1A", "sha1B"):
                        meta[f"control_rows_{q}"] = len(self.xwalk_rows[q])
                    meta["producer"] = "vendor-x hashing appliance"
                    meta["note"] = "reference index; rows carry the origin volume they were computed for"
                self.w_parquet(p, file, cols, rows, {"rev": "int"}, meta)
            elif fmt == "json":
                obj = {"_ctl": self.r_ctl(file, len(rows)), "crosswalk": rows if dr is None else rows[: dr[0]]}
                if dr is not None:
                    obj["crosswalk_v2"] = [{dr[2].get(k, k): v for k, v in r.items()} for r in rows[dr[0]:]]
                    obj["crosswalk_v2_renames"] = dr[2]
                p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode())
            elif fmt == "pdf":
                self.w_pdf(p, file, "Vendor hash attestation (SHA-1 to SHA-256)", self.doc(file), [("Attested digests", cols, rows, dr)])
            return
        if kind == "batches":
            src = self.r_order(file, self.batch_rows[arg] + (self.batch_conflicts if arg == "D" else []))
            cols = ["batch_id", "unit", "captured_utc", "source", "note"]
            rows = [{"batch_id": self.r_key(b["batch"].lower() if b.get("case_trap") else b["batch"], b), "unit": b["unit"],
                     "captured_utc": iso(b["captured"]), "source": "correction" if b in self.batch_conflicts else f"exporter-{b['part']}",
                     "note": self.r_note(b, fmt)} for b in src]
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src, rows), dr)
            elif fmt == "tsv":
                self.w_tsv(p, file, cols, rows, flagged(src, rows), dr)
            elif fmt == "docx":
                self.w_docx(p, file, "Tape operations notes", self.doc(file), [("Batch register C", cols, rows, dr)])
            else:
                self.w_pdf(p, file, "Units bulletin", self.doc(file), [("Batch units (register D and corrections)", cols, rows, dr)])
            return
        if kind == "csdirs":
            src = self.r_order(file, self.cs_rows[arg])
            cols = ["volume", "prefix", "status", "rev", "ticket", "note"]
            rows = [{"volume": c["vol"], "prefix": self.r_key(c["prefix"].upper() if c.get("case_trap") else c["prefix"], c),
                     "status": c["status"], "rev": c["rev"], "ticket": c["ticket"], "note": self.r_note(c, fmt)} for c in src]
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src, rows), dr)
            else:
                self.w_xml(p, file, "case-sensitive-dirs", "dir", ["prefix"] + [c for c in cols if c != "prefix"], rows,
                           flagged(src, rows), dr)
            return
        if kind == "tz":
            src = self.r_order(file, self.tz_rows[arg])
            cols = ["zone", "from_utc", "to_utc", "offset_seconds", "is_dst", "note"]
            rows = []
            for t in src:
                off = t["off"]
                offs = str(off)
                if t.get("off_hhmm"):
                    sign = "+" if off >= 0 else "-"
                    offs = f"{sign}{abs(off) // 3600:02d}:{abs(off) % 3600 // 60:02d}"
                zone = t["zone"].upper() if t.get("case_trap") else t["zone"]
                rows.append({"zone": self.r_key(zone, t), "from_utc": iso(t["from"]), "to_utc": iso(t["to"]),
                             "offset_seconds": offs, "is_dst": t["dst"], "note": self.r_note(t, fmt)})
            dr = self.r_drift(file, src, cols)
            if fmt == "tsv":
                self.w_tsv(p, file, cols, rows, flagged(src, rows), dr, ["segments are half-open [from_utc, to_utc)"])
            else:
                self.w_parquet(p, file, cols, rows, {"is_dst": "int"}, {"semantics": "segments are half-open [from_utc, to_utc)"})
            return
        if kind == "hosts" or file in ("source-register.md", "ECS-annex-hosts-rev7.pdf"):
            part = "A" if file == "source-register.md" else "B"
            base = self.host_rows[part]
            src = self.r_order(file, base)
            cols = ["host", "zone", "note"]
            diffs = set(getattr(self, "host_rows_d11_diff", []))
            rows = []
            for h in src:
                zone = h["zone"]
                if file == "ECS-annex-hosts-rev7.pdf" and (h["host"] in diffs or int(hashlib_r(h["host"]), 16) % 20 == 0):
                    zone = self.zone_names[(self.zone_names.index(zone) + 1) % len(self.zone_names)]
                host = h["host"].upper() if h.get("case_trap") else h["host"]
                rows.append({"host": self.r_key(host, h), "zone": zone, "note": self.r_note(h, fmt)})
            dr = self.r_drift(file, src, cols)
            if file == "source-register.md":
                self.w_md(p, file, self.doc(file), [("## Appendix H. Host register (part A)", cols, rows, dr)] , self.register_tables())
            elif file == "ECS-annex-hosts-rev6.pdf":
                self.w_pdf(p, file, "ECS Annex H, host register part B, revision 6", self.doc(file), [("Hosts", cols, rows, dr)])
            else:
                inc_cols = ["host", "from_utc", "to_utc", "skew_seconds", "status", "rev"]
                incs = [{"host": i["host"], "from_utc": iso(i["from"]), "to_utc": iso(i["to"]), "skew_seconds": i["skew"],
                         "status": "adopted" if i["adopted"] else "rejected", "rev": i.get("rev", 1)} for i in self.incidents]
                self.w_pdf(p, file, "ECS Annex H, host register part B, revision 7 (withdrawn draft)", self.doc(file),
                           [("Hosts", cols, rows, dr), ("Appendix D. Clock incidents", inc_cols, incs, None)])
            return
        if file == "host_aliases.ini":
            src = self.r_order(file, self.hostalias_rows)
            rows = [{"alias": self.r_key(a["alias"].lower() if a.get("case_trap") else a["alias"], a), "host": a["host"],
                     "note": self.r_note(a, fmt)} for a in src]
            self.w_ini(p, file, "alias:", "alias", ["alias", "host", "note"], rows, flagged(src, rows),
                       self.r_drift(file, src, ["alias", "host", "note"]))
            return
        if kind == "config":
            self.rf_config(p, file, int(arg))
            return
        if kind == "rules" and arg == "v3":
            src = self.r_order(file, self.rules_v3)
            cols = ["seq", "scope", "pattern", "class", "status", "note"]
            rows = [{"seq": x["seq"], "scope": x["scope"], "pattern": self.r_key(x["pattern"], x),
                     "class": x["class"].upper() if x.get("case_trap") else x["class"], "status": x["status"],
                     "note": self.r_note(x, fmt)} for x in src]
            self.w_yaml(p, file, [("rules", cols, rows, self.r_drift(file, src, cols))],
                        head={"ruleset": "v3", "ratified_by": next(r["ticket"] for r in self.ratification if r["version"] == "v3")})
            return
        if kind == "rules":
            src = self.r_order(file, self.rules_overlay)
            cols = ["seq", "scope", "pattern", "class", "note"]
            rows = [{"seq": x["seq"], "scope": x["scope"], "pattern": self.r_key(x["pattern"], x),
                     "class": x["class"].upper() if x.get("case_trap") else x["class"], "note": self.r_note(x, fmt)} for x in src]
            self.w_toml(p, file, [("overlay", cols, rows, self.r_drift(file, src, cols))], head={"applies_after": "retention_rules_v3.yaml"})
            return
        self.rf_ref3(out, file)

    def rf_ref3(self, out, file):
        fmt = FILE_FMT_R[file]
        role = FILE_ROLE_R[file]
        kind, _, arg = role.partition(":")
        p = out / file
        iso = g_iso_r
        flagged = self.r_flags
        if kind == "voids" or file == "void_register_q3_r2.xml":
            part = "A" if file != "void_register_supplement.jsonl" else "B"
            src = self.r_order(file, self.void_rows[part])
            cols = ["void_id", "rec_id", "ticket", "status", "rev", "reason"]
            d07 = {(x["void_id"]): x for x in self.d07_rows}
            rows = []
            for v in src:
                st = v["status"]
                if file == "void_register_q3_r2.xml" and (v["void_id"] in d07 or int(hashlib_r(v["void_id"]), 16) % 20 == 0):
                    st = "cancelled" if st == "active" else "active"
                rid = v["rec_id"].lower() if v.get("case_trap") else v["rec_id"]
                rows.append({"void_id": v["void_id"], "rec_id": self.r_key(rid, v), "ticket": v["ticket"], "status": st,
                             "rev": v["rev"], "reason": self.r_note(v, fmt) or v["reason"]})
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src), dr)
            elif fmt == "jsonl":
                self.w_jsonl(p, file, cols, rows, flagged(src), dr)
            else:
                rein = "".join(f'  <reinstate rec-id="{_x(x["rec_id"])}" void-id="{x["void_id"]}" ticket="{x["ticket"]}"/>\n'
                               for x in self.r_order(file + "#r", self.reinstatements))
                self.w_xml(p, file, "void-register", "void", cols, rows, flagged(src), dr,
                           attrs={"status": "draft", "supersedes": "void_register_q3.csv"}, extra=rein)
            return
        if kind == "errata" or file == "errata_register_q3_r2.tsv":
            part = {"errata_register_q3.csv": "A", "errata_register_tape.xml": "B", "errata-bulletin-q3.docx": "C",
                    "errata_register_q3_r2.tsv": "A"}[file]
            src = self.r_order(file, self.errata_rows[part] + (self.d15_rows if file == "errata_register_q3_r2.tsv" else []))
            cols = ["errata_id", "rec_id", "field", "value", "rev", "ticket", "note"]
            rows = []
            for e in src:
                val = e["value"]
                if e.get("grouped") and e["field"] == "bytes":
                    val = f"{int(val):,}"
                rid = e["rec_id"].lower() if e.get("case_trap") else e["rec_id"]
                tk = e.get("ticket") or self.old_ticket_r()
                rev = e["rev"]
                if file == "errata_register_q3_r2.tsv" and int(hashlib_r(e.get("errata_id", rid)), 16) % 20 == 0:
                    rev += 1
                rows.append({"errata_id": e.get("errata_id", "ER-P" + rid[-6:]), "rec_id": self.r_key(rid, e), "field": e["field"],
                             "value": val, "rev": rev, "ticket": tk, "note": self.r_note(e, fmt)})
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src), dr)
            elif fmt == "xml":
                self.w_xml(p, file, "errata", "erratum", cols, rows, flagged(src), dr)
            elif fmt == "docx":
                self.w_docx(p, file, "Errata bulletin Q3", self.doc(file), [("Errata register C", cols, rows, dr)], self.doc(file + "#after"))
            else:
                wd = self.r_order(file + "#w", self.errata_withdrawals)
                wrows = [{"errata_id": w["errata_id"], "rec_id": "", "field": "WITHDRAW", "value": "", "rev": 0,
                          "ticket": w["ticket"], "note": "withdrawal"} for w in wd]
                self.w_tsv(p, file, cols, rows + wrows, flagged(src) + [False] * len(wrows), dr,
                           ["status=preview generated-by=errata-desk"])
            return
        if kind == "holds" or file == "legal-hold-memo-q3.docx":
            if file == "legal-hold-memo-q3.docx":
                src = self.r_order(file, self.hold_releases)
                cols = ["hold_id", "released_utc", "ticket", "note"]
                rows = [{"hold_id": self.r_key(h["hold_id"].lower() if h.get("case_trap") else h["hold_id"], h),
                         "released_utc": iso(h["released"]), "ticket": h["ticket"], "note": self.r_note(h, fmt)} for h in src]
                self.w_docx(p, file, "Legal hold memo Q3: releases", self.doc(file), [("Releases", cols, rows, self.r_drift(file, src, cols))])
                return
            src = self.r_order(file, self.hold_rows[arg])
            cols = ["hold_id", "volume", "prefix", "from_utc", "to_utc", "status", "matter", "note"]
            rows = [{"hold_id": self.r_key(h["hold_id"].lower() if h.get("case_trap") else h["hold_id"], h), "volume": h["volume"],
                     "prefix": h["prefix"], "from_utc": iso(h["from"]), "to_utc": iso(h["to"]) if h["to"] is not None else "",
                     "status": h["status"], "matter": h["matter"], "note": self.r_note(h, fmt)} for h in src]
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src), dr)
            elif fmt == "xlsx":
                mats = [{"matter_id": m, "status": s} for m, s in sorted(self.matters.items())]
                self.w_xlsx(p, file, [("holds", cols, rows, dr), ("matters", ["matter_id", "status"], mats, None)])
            elif fmt == "html":
                self.w_html(p, file, "Legal holds portal export (partition D)", self.doc(file), [("Holds", cols, rows, dr)])
            else:
                self.rf_ics(p, file, src, rows, dr)
            return
        if file == "change_tickets.csv":
            src = self.r_order(file, self.ticket_rows)
            cols = ["ticket", "rev", "state", "decided_utc", "note"]
            rows = [{"ticket": self.r_key(t["ticket"].lower() if t.get("case_trap") else t["ticket"], t), "rev": t["rev"],
                     "state": t["state"], "decided_utc": iso(t["decided"]) if t["decided"] is not None else "0000-00-00T00:00:00Z",
                     "note": self.r_note(t, fmt)} for t in src]
            self.w_csv(p, file, cols, rows, flagged(src), self.r_drift(file, src, cols))
            return
        if kind == "store":
            src = self.r_order(file, self.store_rows[arg])
            cols = ["sha256", "status", "rev", "stored_bytes", "note"]
            rows = [{"sha256": self.r_key(s["sha256"].upper() if s.get("case_trap") else s["sha256"], s), "status": s["status"],
                     "rev": s["rev"], "stored_bytes": s["stored_bytes"], "note": self.r_note(s, fmt)} for s in src]
            dr = self.r_drift(file, src, cols)
            if fmt == "csv":
                self.w_csv(p, file, cols, rows, flagged(src), dr)
            elif fmt == "jsonl":
                self.w_jsonl(p, file, cols, rows, flagged(src), dr)
            elif fmt == "parquet":
                self.w_parquet(p, file, cols, rows, {"rev": "int", "stored_bytes": "int"})
            else:
                self.w_sqlite(p, file, [("store_index", cols, {"rev": "INTEGER", "stored_bytes": "INTEGER"}, rows)])
            return
        if file == "authority_matrix.xlsx":
            src = self.r_order(file, self.runs)
            cols = ["run_id", "file", "volume", "kind", "completed_utc", "status", "superseded_by"]
            rows = [{"run_id": self.r_key(r["run_id"], r), "file": r["file"], "volume": r["volume"], "kind": r["kind"],
                     "completed_utc": iso(r["completed"]), "status": r["status"], "superseded_by": r["superseded_by"]} for r in src]
            scope = [{"record": "override", "id": o["override_id"], "subject": o["file"], "volume_or_version": o["volume"],
                      "prefix": o["prefix"], "ticket": o["ticket"]} for o in self.r_order(file + "#s", self.scope_overrides)]
            scope += [{"record": "ratification", "id": f"RAT-{i + 1:03d}", "subject": r["document"], "volume_or_version": r["version"],
                       "prefix": "", "ticket": r["ticket"]} for i, r in enumerate(self.ratification)]
            self.w_xlsx(p, file, [("runs", cols, rows, self.r_drift(file, src, cols)),
                                  ("scope", ["record", "id", "subject", "volume_or_version", "prefix", "ticket"], scope, None)],
                        meta="export runs, scope overrides and document ratifications")
            return
        if file == "audit-scope-letter-fin.pdf":
            src = self.r_order(file, self.audit_rows)
            cols = ["rec_id", "status", "note"]
            rows = [{"rec_id": self.r_key(a["rec_id"].lower() if a.get("case_trap") else a["rec_id"], a),
                     "status": a.get("status", "excluded"), "note": self.r_note(a, fmt)} for a in src]
            self.w_pdf(p, file, "Audit scope letter, finance volumes", self.doc(file), [("Excluded records", cols, rows, self.r_drift(file, src, cols))])
            return
        self.rf_ref4(out, file)

    def old_ticket_r(self):
        return next(iter(self.tickets))

    def rf_ics(self, p, file, src, rows, dr):
        def esc(s):
            return s.replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,").replace("\n", "\\n")

        def fold(line):
            b = line.encode("utf-8")
            if len(b) <= 75:
                return [line]
            out, cur = [], ""
            for ch in line:
                if len((cur + ch).encode("utf-8")) > 74:
                    out.append(cur)
                    cur = " " + ch
                else:
                    cur += ch
            out.append(cur)
            return out

        c = self.r_ctl(file, len(rows))
        lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//estate//holds//EN", f"X-CTL-ID:{c['ctl_id']}",
                 f"X-CTL-PREV:{c['prev']}", f"X-CTL-ROWS:{c['rows']}"]
        pfx = "X-HOLD-PREFIX"
        for i, r in enumerate(rows):
            if dr is not None and i == dr[0]:
                pfx = "X-PREFIX"
            h = src[i]
            ev = ["BEGIN:VEVENT", f"UID:{r['hold_id']}", f"DTSTART:{r['from_utc'].replace('-', '').replace(':', '')}"]
            if r["to_utc"]:
                ev.append(f"DTEND:{r['to_utc'].replace('-', '').replace(':', '')}")
            ev += [f"SUMMARY:{esc('Legal hold ' + h['matter'])}", f"STATUS:{'CONFIRMED' if r['status'] == 'active' else 'CANCELLED'}",
                   f"X-VOLUME:{r['volume']}", f"{pfx}:{esc(r['prefix'])}", f"X-MATTER:{r['matter']}"]
            if pfx == "X-PREFIX" and i == dr[0]:
                ev.append("X-SCHEMA:2")
            if r["note"]:
                ev.append(f"DESCRIPTION:{esc(r['note'])}")
            ev.append("END:VEVENT")
            for e in ev:
                lines += fold(e)
        lines.append("END:VCALENDAR")
        p.write_bytes(("\n".join(lines) + "\n").encode("utf-8"))

    def rf_ref4(self, out, file):
        fmt = FILE_FMT_R[file]
        p = out / file
        iso = g_iso_r
        flagged = self.r_flags
        if file in ("retention-schedule-2026-r2.docx", "retention-schedule-2026-r3.docx"):
            src, rows = self.ref_ext_rows(file, "C")
            if file.endswith("r3.docx"):
                for i, r in enumerate(rows):
                    if int(hashlib_r(r["ext"] + "r3"), 16) % 20 == 0:
                        r["family"] = FAMILIES_R[(FAMILIES_R.index(r["family"]) + 1) % len(FAMILIES_R)] if r["family"] in FAMILIES_R else r["family"]
                classes = [{"class": d["cls"], "purge_after_days": "" if d["max"] is None else d["max"],
                            "archive_after_days": "" if d["arch"] is None else d["arch"]} for d in self.d10_rows]
                corr = [{"ext": c["ext"], "family": c["family"], "rev": c.get("rev", 1)} for c in self.r_order(file + "#c", self.ext_corrections)]
                tables = [("Table 1. Class ages (draft r3)", ["class", "purge_after_days", "archive_after_days"], classes, None),
                          ("Annex C. Extension families (draft)", ["ext", "family", "rev", "status", "note"], rows,
                           self.r_drift(file, src, ["ext", "family", "rev", "status", "note"])),
                          ("Annex F. Family corrections", ["ext", "family", "rev"], corr, None)]
                self.w_docx(p, file, "Retention schedule 2026, revision 3 (DRAFT)", self.doc(file), tables,
                            self.doc(file + "#after"), subject_extra="status=DRAFT")
            else:
                classes = [{"class": c, "purge_after_days": "" if v[0] is None else v[0],
                            "archive_after_days": "" if v[1] is None else v[1]} for c, v in self.classes.items()]
                tables = [("Table 1. Class ages", ["class", "purge_after_days", "archive_after_days"], classes, None),
                          ("Annex C. Extension families (table C)", ["ext", "family", "rev", "status", "note"], rows,
                           self.r_drift(file, src, ["ext", "family", "rev", "status", "note"]))]
                self.w_docx(p, file, "Retention schedule 2026, revision 2", self.doc(file), tables, self.doc(file + "#after"))
            return
        if file in ("ECS-handbook-paths.docx", "volumes.yaml", "ECS-standard.md"):
            part = {"ECS-handbook-paths.docx": "D", "volumes.yaml": "E", "ECS-standard.md": "F"}[file]
            src, rows = self.ref_alias_rows(file, part)
            cols = ["alias_id", "root", "volume", "prefix", "rev", "status", "note"]
            dr = self.r_drift(file, src, cols)
            if file.endswith(".docx"):
                self.w_docx(p, file, "ECS handbook: path canonicalisation", self.doc(file), [("Table D. Legacy share aliases", cols, rows, dr)])
            elif file.endswith(".yaml"):
                vols = [{"code": v[0], "fs_type": v[1], "host": self.vol_host[v[0]]} for v in VOLUMES_R]
                self.w_yaml(p, file, [("volumes", ["code", "fs_type", "host"], vols, None), ("aliases", cols, rows, dr)])
            else:
                self.w_md(p, file, self.doc(file), [("## Appendix F. Alias roots, partition F", cols, rows, dr)], self.doc(file + "#after"))
            return
        if file in ("owner-migration-plan.docx", "hr-roster-q3.pdf", "principal_map_ldap.html"):
            ns = {"owner-migration-plan.docx": "corp", "hr-roster-q3.pdf": "email", "principal_map_ldap.html": "oldcorp"}[file]
            src, rows = self.ref_tok_rows(file, ns)
            if ns == "email":
                cols = ["email", "principal_id", "valid_from", "status", "display"]
                self.w_pdf(p, file, "HR roster Q3 (e-mail to principal)", self.doc(file), [("Roster", cols, rows, self.r_drift(file, src, cols))])
            elif ns == "corp":
                cols = ["domain", "login", "principal_id", "valid_from", "status", "display"]
                self.w_docx(p, file, "Owner migration plan: CORP logins", self.doc(file), [("Login map", cols, rows, self.r_drift(file, src, cols))])
            else:
                cols = ["domain", "login", "principal_id", "valid_from", "status", "display"]
                extra = []
                for i, lt in enumerate(self.tok_rows["legacy"]):
                    alt = next((d for d in self.d12_rows if d["token"] == lt["token"]), None)
                    dom, _, login = lt["token"].partition("\\")
                    pid = alt["pid"] if alt else (lt["pid"] if int(hashlib_r(lt["token"]), 16) % 20 else self.pids[i % len(self.pids)])
                    extra.append({"domain": dom, "login": login, "principal_id": pid, "valid_from": iso(self.prev_start - 900 * 86400),
                                  "status": "active", "display": "archived copy"})
                self.w_html(p, file, "LDAP principal map (archived page)", self.doc(file),
                            [("OLDCORP accounts", cols, rows, self.r_drift(file, src, cols)), ("Other domains (copy)", cols, extra, None)],
                            banner="ARCHIVED: this page is kept for reference and is no longer maintained.")
            return
        if file == "principal_directory.xlsx":
            hist = self.r_order(file, self.d02_hist)
            dirr = self.r_order(file + "#d", self.d02_dir)
            hcols = ["old_sid", "new_sid", "migrated_utc", "rev"]
            hrows = [{"old_sid": self.r_key(h["old"].lower() if h.get("case_trap") else h["old"], h), "new_sid": h["new"],
                      "migrated_utc": iso(h["migrated"]), "rev": h["rev"]} for h in hist]
            drows = [{"principal_id": d["pid"], "account": d["account"], "status": d["status"],
                      "updated_utc": iso(self.win_start - 200 * 86400)} for d in dirr]
            self.w_xlsx(p, file, [("directory", ["principal_id", "account", "status", "updated_utc"], drows, None),
                                  ("sid_history", hcols, hrows, self.r_drift(file, hist, hcols))],
                        meta="snapshot_of=2025-03-31 source=AD export; kept for SID history")
            return
        if file == "retention_rules_v4.toml":
            src = self.r_order(file, self.d04_rows)
            cols = ["seq", "scope", "pattern", "class", "status"]
            rows = [{"seq": x["seq"], "scope": x["scope"], "pattern": self.r_key(x["pattern"], x), "class": x["class"],
                     "status": x["status"]} for x in src]
            wd = [{"rule_seq": w["seq"], "ticket": w["ticket"]} for w in self.r_order(file + "#w", self.v4_withdrawals)]
            self.w_toml(p, file, [("rule", cols, rows, self.r_drift(file, src, cols)), ("withdrawal", ["rule_seq", "ticket"], wd, None)],
                        head={"ruleset": "v4", "label": "FINAL", "status": "pending-cab"})
            return
        if file == "volumes_cmdb.json":
            src = self.r_order(file, self.d05_rows)
            vols = []
            for v in VOLUMES_R:
                fs = v[1] if v[0] != "RND01" else "apfs (case-insensitive)"
                vols.append({"code": v[0], "fs_type": fs, "host": self.vol_host[v[0]], "asset_tag": f"AT-{hashlib_r(v[0])[:6]}",
                             "location": "dc-" + v[0][:3].lower()})
            ser = []
            for s in src:
                key = self.r_key(s["serial"].lower() if s.get("case_trap") else s["serial"], s)
                if s.get("rev_noise"):
                    ser.append({"serial": key, "volume": "ARC00", "status": "active", "rev": 1})
                ser.append({"serial": key, "volume": s["volume"], "status": s["status"], "rev": 2 if s.get("rev_noise") else 1})
            obj = {"_ctl": self.r_ctl(file, len(ser) + len(vols)), "authoritative_for": ["asset_tag", "location", "serial"],
                   "volumes": vols, "serials": ser}
            p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode())
            return
        if file == "estate_manifest_q2.parquet":
            src = self.prior_rows
            cols = ["entry_id", "volume", "path", "sha256", "bytes", "owner", "status"]
            rows = [{c: r[c] for c in cols} for r in src]
            self.w_parquet(p, file, cols, rows, {"entry_id": "int", "bytes": "int"},
                           {"period": self.prev_quarter, "next_entry_id": self.prior_next_id,
                            "closing_entries": self.prior_open["entries"], "closing_logical_bytes": self.prior_open["logical_bytes"],
                            "closing_store_bytes": self.prior_open["store_bytes"], "closing_ctl_id": self.prior_ctl})
            return
        if file == "site-policy-v2.yaml":
            self.rf_config(p, file, 20, proposed=True)
            return
        if file == "tool.zip":
            p.write_bytes(self.tool_zip())
            return
        raise ValueError(f"no renderer for {file}")

    def rf_config(self, p, file, layer, proposed=False):
        rows_src = self.r_order(file, self.cfg_layers[layer])
        fmt = "yaml" if proposed else FILE_FMT_R[file]
        cols = ["key", "value", "profile", "final"] + (["ticket", "override_id"] if layer == 40 else [])
        rows = []
        d13 = {x["key"]: x["value"] for x in self.d13_rows}
        for r in rows_src:
            v = r["value"]
            if proposed and r["key"] in d13:
                v = d13[r["key"]]
            if proposed and isinstance(v, bool) and int(hashlib_r(r["key"]), 16) % 20 == 0:
                v = not v
            key = r["key"]
            if r.get("case_trap"):
                key = key.replace("subtree.", "SUBTREE.", 1)
            key = self.r_key(key, r)
            if fmt == "yaml":
                vv = ("!raw:" + r["bool_form"]) if r.get("bool_form") else v
                if r.get("num_form"):
                    vv = "!raw:" + f"{v:_}"
            elif fmt == "toml":
                vv = ("!raw:" + f"{v:_}") if r.get("num_form") else v
            elif fmt == "json":
                vv = f"{v:,}" if r.get("num_form") else v
                if r.get("bool_form"):
                    vv = r["bool_form"]
            else:
                vv = v
                if isinstance(v, bool):
                    vv = r.get("bool_form") or ("true" if v else "false")
                if r.get("num_form") or (r["key"] == "store.block_size" and r.get("unit")):
                    vv = f"{v // 1024} KiB" if v % 1024 == 0 else str(v)
            rows.append({"key": key, "value": vv, "profile": r["profile"], "final": bool(r["final"]),
                         "ticket": r.get("ticket"), "override_id": r.get("oid"), "note": self.r_note(r, fmt)})
        cols = cols + ["note"]
        dr = self.r_drift(file, rows_src, cols)
        if proposed:
            rev = [{"override_id": x["oid"], "ticket": x["ticket"]} for x in self.r_order(file + "#r", self.revocations)]
            self.w_yaml(p, file, [("settings", cols, rows, dr), ("revocations", ["override_id", "ticket"], rev, None)],
                        head={"layer": 20, "status": "proposed", "replaces": "site-policy.yaml"})
        elif fmt == "yaml":
            self.w_yaml(p, file, [("settings", cols, rows, dr)], head={"layer": layer})
        elif fmt == "toml":
            self.w_toml(p, file, [("setting", cols, rows, dr)], head={"layer": layer})
        elif fmt == "json":
            obj = {"_ctl": self.r_ctl(file, len(rows)), "layer": layer,
                   "settings": [{c: r[c] for c in cols if r.get(c) is not None} for r in (rows if dr is None else rows[: dr[0]])]}
            if dr is not None:
                obj["settings_v2"] = [{dr[2].get(c, c): r[c] for c in cols if r.get(c) is not None} for r in rows[dr[0]:]]
                obj["settings_v2_renames"] = dr[2]
            p.write_bytes(json.dumps(obj, ensure_ascii=False, indent=1).encode())
        else:
            for i, r in enumerate(rows):
                r["sec"] = r["override_id"] or f"S{i:05d}"
            self.w_ini(p, file, "override:", "sec", ["sec"] + cols, rows, self.r_flags(rows_src), dr)

    def render(self, out):
        out = Path(out)
        out.mkdir(parents=True, exist_ok=True)
        self.ctl_rows = {}
        for f in FILE_NAMES_R:
            if f in INVENTORY_FILES_R:
                self.rf_inventory(out, f)
            elif f in JOURNAL_FILES_R:
                self.rf_journal(out, f)
            else:
                self.rf_ref(out, f)
        self.truth_summary()
        return out

    def truth_summary(self):
        chain = [{"file": f, "ctl_id": self.ctl[f]["id"], "rows": self.ctl_rows[f]} for f in self.chain]
        self.summary = {"opening_ctl_id": self.prior_ctl, "chain": chain,
                        "profiles": {p: self.truth[p]["ledger"] for p in ("prod", "dev")}}

    def expected_outputs(self):
        out = {}
        for prof in ("prod", "dev"):
            ev = self.truth[prof]
            ents = [{"entry_id": e["entry_id"], "volume": e["vol"], "path": e["path"], "sha256": e["sha"], "bytes": e["bytes"],
                     "mtime": g_iso_r(e["mtime"]), "owner": e["owner"], "class": e["class"], "action": e["action"],
                     "origin": e["origin"]} for e in ev["entries"]]
            out[f"profile_{prof}.json"] = {"profile": prof, "config": ev["cfg"], "control": ev["ledger"]["closing"],
                                           "entries": ents}
        out["config.json"] = self.truth["prod"]["cfg"]
        out["validation_report.json"] = {p: [{"rec_id": k, "reason": v[1]} for k, v in sorted(self.truth[p]["outcome"].items())]
                                         for p in ("prod", "dev")}
        out["summary.json"] = self.summary
        return out

