def _register_desc():
    out = {}
    for name, fmt, role, _d in FILES:
        kind, _, arg = role.partition(":")
        if kind in ("inventory",):
            out[name] = f"inventory export of volume {arg[:5]}"
        elif kind == "journal":
            out[name] = f"change journal of volume {arg}"
        elif kind == "decoy":
            out[name] = {"inv_fin01_dryrun": "inventory export of volume FIN01",
                         "inv_eng01_deep": "inventory export of volume ENG01",
                         "ltfs_index": "LTFS index of volume ARC01",
                         "journal_replica": "change journal of volume MKT01",
                         "principal_directory": "principal directory export with SID history",
                         "hash_vendor": "hash index (digest crosswalk)",
                         "rules_v4": "retention ruleset v4",
                         "cmdb": "CMDB volume export with serials",
                         "void_draft": "void register revision 2",
                         "prior_manifest": "placement manifest of the previous period",
                         "schedule_draft": "retention schedule 2026 revision 3",
                         "hosts_rev7": "ECS annex H revision 7 with appendix D",
                         "ldap_archive": "LDAP principal map",
                         "policy_proposed": "site policy revision 2",
                         "errata_preview": "errata register revision 2"}[arg]
        else:
            out[name] = {
                "merges": "principal merges", "voids": "void register", "tickets": "change tickets",
                "errata": "errata register", "holds": "legal holds", "store": "prior store index",
                "xwalk": "digest crosswalk", "csdirs": "case-sensitive subtrees", "batches": "export batch register",
                "tz": "time-zone transitions", "ext": "extension families", "alias": "alias roots",
                "tok": "owner token map", "authority": "export runs, scope overrides, ratifications",
                "config": "configuration layer", "schedule": "retention schedule 2026 revision 2",
                "holdrel": "legal hold releases", "hosts": "host register", "audit": "finance audit letter",
                "volumes": "volume table and alias roots", "rules": "retention rules", "hostalias": "host aliases",
                "standard": "this standard's companion", "register": "source register", "runbook": "operations runbook",
                "tool": "estatectl tool archive"}[kind] + (f" ({arg})" if arg else "")
    return out


REGISTER_DESC.update(_register_desc())


class ToolMixin:
    def tool_zip(self):
        file = "tool.zip"
        src, rows = self.ref_ext_rows(file, "E")
        cols = ["ext", "family", "rev", "status", "note"]
        dr = self.r_drift(file, src, cols)

        def esc(v):
            s = "" if v is None else str(v)
            return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n").replace("\r", "\\r")

        lines = ["\t".join(cols)]
        cur = cols
        for i, r in enumerate(rows):
            if dr is not None and i == dr[0]:
                cur = dr[1]
                lines.append("\t".join(dr[2].get(c, c) for c in cur))
            lines.append("\t".join(esc(r.get(c)) for c in cur))
        c = self.r_ctl(file, len(rows))
        members = [("CONTROL", f"ctl_id={c['ctl_id']}\nprev={c['prev']}\nrows={c['rows']}\n".encode()),
                   ("estatectl/README.md", TOOL_README.encode()),
                   ("estatectl/estatectl.py", TOOL_PY.encode()),
                   ("estatectl/ext_families_builtin.tsv", ("\n".join(lines) + "\n").encode("utf-8"))]
        return r_zip(members)

