# ---------------------------------------------------------------- criteria
@criterion(description="All seven declared artifacts exist and every JSON artifact parses")
def artifacts_present_and_parse(workspace: Path) -> bool:
    try:
        if not all((OUT / n).is_file() and (OUT / n).stat().st_size > 0 for n in ARTIFACTS):
            return False
        return all(_read_json(OUT / n) is not None for n in ARTIFACTS if n.endswith(".json"))
    except Exception:
        return False


@criterion(description="config.json equals the config object of profile_prod.json")
def config_matches_prod_profile(workspace: Path) -> bool:
    try:
        cfg = _read_json(OUT / "config.json")
        prof = _read_json(OUT / "profile_prod.json")
        return isinstance(cfg, dict) and bool(cfg) and cfg == prof["config"]
    except Exception:
        return False


@criterion(description="report.json records a successful run command and the config.json digest")
def report_records_tool_run(workspace: Path) -> bool:
    try:
        rep = _read_json(OUT / "report.json")
        digest = hashlib.sha256((OUT / "config.json").read_bytes()).hexdigest()
        cmds = rep["commands"]
        runs = [c for c in cmds if "run" in [str(a) for a in c["argv"]]]
        return (rep["ok"] is True and rep["tool"] == "estatectl" and rep["config_sha256"] == digest
                and bool(runs) and all(c["returncode"] == 0 for c in cmds))
    except Exception:
        return False


@criterion(description="tool.zip keeps the shipped layout: estatectl/estatectl.py and estatectl/ext_families_builtin.tsv")
def tool_archive_layout(workspace: Path) -> bool:
    tool = _tool_dir()  # None unless the archive extracts safely and holds estatectl/estatectl.py
    return tool is not None and (tool / "estatectl" / "ext_families_builtin.tsv").is_file()


@criterion(description="validation_report.json lists rec_id and reason objects per profile, sorted, with ECS reason codes")
def validation_report_shape(workspace: Path) -> bool:
    try:
        vr = _read_json(OUT / "validation_report.json")
        for prof in ("prod", "dev"):
            ids = [x["rec_id"] for x in vr[prof]]
            if ids != sorted(ids) or len(ids) != len(set(ids)) or not ids:
                return False
            if any(x["reason"] not in ECS_REASONS or set(x) != {"rec_id", "reason"} for x in vr[prof]):
                return False
        return set(vr) == {"prod", "dev"}
    except Exception:
        return False


@criterion(description="Each profile file names its profile and lists entries sorted by volume and path in code-point order")
def profile_shape(workspace: Path) -> bool:
    try:
        for prof in ("prod", "dev"):
            doc = _read_json(OUT / f"profile_{prof}.json")
            if not isinstance(doc, dict) or doc.get("profile") != prof:
                return False
            ents = doc["entries"]
            keys = [(e["volume"], e["path"]) for e in ents]
            if not keys or not all(isinstance(v, str) and isinstance(p, str) for v, p in keys):
                return False
            if keys != sorted(keys):
                return False
        return True
    except Exception:
        return False


